import React, { useState, useRef, useEffect } from 'react';
import { GoogleGenAI } from "@google/genai";
import { Send, X, Sparkles, Bot, User, Loader2 } from 'lucide-react';
import { TURFS } from '../constants';

interface Message {
  id: string;
  role: 'user' | 'model';
  text: string;
}

export const AIChat: React.FC<{ onClose: () => void }> = ({ onClose }) => {
  const [input, setInput] = useState('');
  const [messages, setMessages] = useState<Message[]>([
    { id: 'init', role: 'model', text: "Hi! I'm Coach Gemini. I can help you find turfs, suggest tactics, or organize your team. What's the plan?" }
  ]);
  const [isLoading, setIsLoading] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim() || isLoading) return;

    const userMessage: Message = { id: Date.now().toString(), role: 'user', text: input };
    setMessages(prev => [...prev, userMessage]);
    setInput('');
    setIsLoading(true);

    try {
      // Initialize Gemini
      // Note: In a real prod environment, calls should go through a backend to protect the Key.
      // For this demo structure, we use process.env.API_KEY directly.
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      // Prepare Context
      const turfContext = JSON.stringify(TURFS.map(t => ({
        name: t.name,
        location: t.location,
        price: t.pricePerHour,
        amenities: t.amenities
      })));

      const systemInstruction = `You are Footlink's AI Assistant, "Coach Gemini". 
      You are helpful, sporty, and concise.

      Here is the list of available Turfs in our database: ${turfContext}.

      Rules:
      1. If asked about turfs, ONLY recommend from the list above.
      2. If asked about prices, quote them in UGX.
      3. You can also give football coaching advice (tactics, rules, nutrition).
      4. Keep responses under 100 words unless asked for a detailed drill.
      `;

      const chat = ai.chats.create({
        model: 'gemini-3-flash-preview',
        config: {
          systemInstruction: systemInstruction,
        },
        history: messages.map(m => ({
          role: m.role,
          parts: [{ text: m.text }]
        }))
      });

      const result = await chat.sendMessageStream({ message: userMessage.text });

      let fullResponse = "";
      const modelMsgId = (Date.now() + 1).toString();

      // Add placeholder for stream
      setMessages(prev => [...prev, { id: modelMsgId, role: 'model', text: '' }]);

      for await (const chunk of result) {
        const text = chunk.text;
        if (text) {
          fullResponse += text;
          setMessages(prev => prev.map(m => 
            m.id === modelMsgId ? { ...m, text: fullResponse } : m
          ));
        }
      }
    } catch (error) {
      console.error("AI Error:", error);
      setMessages(prev => [...prev, { id: 'error', role: 'model', text: "Sorry, I'm having trouble connecting to the locker room (server error). Try again!" }]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="fixed inset-0 z-[60] flex items-end sm:items-center justify-center pointer-events-none">
      {/* Backdrop */}
      <div className="absolute inset-0 bg-black/50 backdrop-blur-sm pointer-events-auto" onClick={onClose} />

      {/* Chat Window */}
      <div className="bg-slate-50 dark:bg-slate-900 w-full sm:w-[400px] h-[85vh] sm:h-[600px] rounded-t-3xl sm:rounded-2xl shadow-2xl flex flex-col pointer-events-auto overflow-hidden animate-slideUp border border-slate-200 dark:border-slate-700">

        {/* Header */}
        <div className="bg-white dark:bg-slate-800 p-4 flex items-center justify-between border-b border-slate-200 dark:border-slate-700">
          <div className="flex items-center">
            <div className="w-10 h-10 rounded-full bg-gradient-to-tr from-brand-primary to-blue-500 flex items-center justify-center mr-3 shadow-lg">
              <Bot className="text-white" size={24} />
            </div>
            <div>
              <h3 className="font-bold text-slate-900 dark:text-white">Coach Gemini</h3>
              <p className="text-xs text-brand-secondary font-medium flex items-center">
                <span className="w-2 h-2 rounded-full bg-brand-secondary mr-1 animate-pulse" /> Online
              </p>
            </div>
          </div>
          <button onClick={onClose} className="p-2 hover:bg-slate-100 dark:hover:bg-slate-700 rounded-full transition-colors text-slate-500">
            <X size={20} />
          </button>
        </div>

        {/* Messages Area */}
        <div className="flex-1 overflow-y-auto p-4 space-y-4 bg-slate-50 dark:bg-slate-900/50">
          {messages.map((msg) => (
            <div key={msg.id} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
              <div className={`max-w-[85%] rounded-2xl px-4 py-3 shadow-sm ${
                msg.role === 'user' 
                  ? 'bg-brand-secondary text-white rounded-br-none' 
                  : 'bg-white dark:bg-slate-800 text-slate-800 dark:text-slate-200 rounded-bl-none border border-slate-200 dark:border-slate-700'
              }`}>
                {msg.text ? (
                   <div className="text-sm leading-relaxed whitespace-pre-wrap">{msg.text}</div>
                ) : (
                   <Loader2 size={16} className="animate-spin text-slate-400" />
                )}
              </div>
            </div>
          ))}
          <div ref={messagesEndRef} />
        </div>

        {/* Input Area */}
        <div className="p-4 bg-white dark:bg-slate-800 border-t border-slate-200 dark:border-slate-700">
          <div className="flex items-center gap-2 bg-slate-100 dark:bg-slate-900 rounded-full px-4 py-2 border border-slate-200 dark:border-slate-700 focus-within:border-brand-primary transition-colors">
            <input
              type="text"
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleSend()}
              placeholder="Ask about turfs, tactics..."
              className="flex-1 bg-transparent border-none outline-none text-sm text-slate-900 dark:text-white placeholder-slate-400 h-10"
              disabled={isLoading}
            />
            <button 
              onClick={handleSend}
              disabled={!input.trim() || isLoading}
              className="p-2 bg-brand-primary text-white rounded-full hover:bg-violet-600 disabled:opacity-50 disabled:scale-100 transition-all active:scale-95 shadow-md"
            >
              <Send size={16} className={isLoading ? 'opacity-0' : 'ml-0.5'} />
              {isLoading && <Loader2 size={16} className="absolute animate-spin" />}
            </button>
          </div>
          <div className="text-center mt-2">
             <p className="text-[10px] text-slate-400 flex items-center justify-center">
                <Sparkles size={10} className="mr-1 text-brand-primary" /> Powered by Gemini
             </p>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { Target, Calendar, Users, Trophy, User, Home, Activity, Sparkles } from 'lucide-react';
import { AIChat } from './AIChat';

interface LayoutProps {
  children: React.ReactNode;
  isOwner?: boolean;
}

export const Layout: React.FC<LayoutProps> = ({ children, isOwner = false }) => {
  const navigate = useNavigate();
  const location = useLocation();
  const [isChatOpen, setIsChatOpen] = useState(false);

  const isActive = (path: string) => location.pathname === path;

  // Standard Nav Item
  const NavItem = ({ path, icon: Icon, label }: { path: string, icon: any, label: string }) => (
    <button
      onClick={() => navigate(path)}
      className={`flex flex-col items-center justify-center w-full h-full py-2 transition-colors duration-300 ${
        isActive(path) 
          ? 'text-brand-secondary' 
          : 'text-slate-400 hover:text-slate-200'
      }`}
    >
      <Icon size={24} strokeWidth={isActive(path) ? 2.5 : 2} className="mb-1" />
      <span className="text-[10px] font-medium">{label}</span>
    </button>
  );

  return (
    <div className="flex flex-col h-screen bg-slate-50 dark:bg-brand-dark overflow-hidden transition-colors duration-300 font-sans relative">
      <main className="flex-1 overflow-y-auto pb-20 scrollbar-hide">
        {children}
      </main>

      {/* AI Assistant FAB */}
      {!isOwner && !isChatOpen && (
        <button
          onClick={() => setIsChatOpen(true)}
          className="fixed bottom-24 right-5 z-40 w-14 h-14 bg-gradient-to-r from-brand-primary to-violet-600 rounded-full shadow-lg shadow-violet-500/40 flex items-center justify-center text-white hover:scale-105 active:scale-95 transition-transform group animate-bounce-slow"
        >
          <Sparkles size={24} className="group-hover:rotate-12 transition-transform" />
          <span className="absolute -top-1 -right-1 flex h-3 w-3">
            <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-violet-400 opacity-75"></span>
            <span className="relative inline-flex rounded-full h-3 w-3 bg-violet-500"></span>
          </span>
        </button>
      )}

      {/* AI Chat Overlay */}
      {isChatOpen && <AIChat onClose={() => setIsChatOpen(false)} />}

      {!isOwner && (
        <div className="fixed bottom-0 left-0 right-0 h-20 bg-white dark:bg-slate-900 border-t border-slate-200 dark:border-slate-800 flex justify-around items-center z-50 px-2 pb-2 safe-area-bottom">
            <NavItem path="/home" icon={Home} label="Home" />
            <NavItem path="/live" icon={Activity} label="Live" />
            <NavItem path="/bookings" icon={Calendar} label="Bookings" />
            <NavItem path="/teams" icon={Users} label="Teams" />
            <NavItem path="/profile" icon={User} label="Profile" />
        </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Search, Filter, Bell, MapPin, Star, Heart, Moon, Sun, Dribbble, Zap, CloudSun, Trophy, Users, Calendar } from 'lucide-react';
import { TURFS, LIVE_MATCHES } from '../constants';
import { Layout } from '../components/Layout';
import { useTheme } from '../ThemeContext';

export const Home: React.FC = () => {
  const navigate = useNavigate();
  const [filter, setFilter] = useState('5-a-side');
  const [searchTerm, setSearchTerm] = useState('');
  const { theme, toggleTheme } = useTheme();

  // Featured is the first one
  const featuredTurf = TURFS[0];
  const liveMatch = LIVE_MATCHES[0];

  // Logic to filter turfs based on Search input
  const allTurfs = TURFS; // In a real app, this might come from context/API
  const filteredTurfs = allTurfs.filter(turf => {
      const lowerTerm = searchTerm.toLowerCase();
      const matchesSearch = turf.name.toLowerCase().includes(lowerTerm) || 
                            turf.location.toLowerCase().includes(lowerTerm);
      // We skip the Featured one in the list below to avoid duplication, unless searching
      if (!searchTerm && turf.id === featuredTurf.id) return false;
      return matchesSearch;
  });

  const categories = [
      { name: '5-a-side', icon: <Users size={16} /> },
      { name: '7-a-side', icon: <Users size={16} /> },
      { name: '11-a-side', icon: <Dribbble size={16} /> },
      { name: 'Training', icon: <Zap size={16} /> },
      { name: 'Leagues', icon: <Trophy size={16} /> },
  ];

  return (
    <Layout>
      <div className="p-5 pt-8 bg-slate-50 dark:bg-brand-dark min-h-screen text-slate-900 dark:text-white font-sans transition-colors duration-300">
