        <div className="flex justify-between items-center mb-6">
          <div className="flex items-center space-x-3">
             <div className="w-12 h-12 rounded-full overflow-hidden border-2 border-brand-secondary p-0.5 shadow-md">
                <img src="https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?ixlib=rb-4.0.3&fit=facearea&facepad=2&w=256&h=256&q=80" alt="Profile" className="w-full h-full rounded-full object-cover" />
             </div>
             <div>
                <p className="text-slate-500 dark:text-slate-400 text-xs font-bold uppercase tracking-wider">Location</p>
                <div className="flex items-center text-slate-900 dark:text-white font-bold text-lg">
                    <MapPin size={16} className="text-brand-secondary mr-1 fill-current" />
                    Kampala, Uganda
                </div>
             </div>
          </div>

          <div className="flex space-x-3">
             <button 
                onClick={toggleTheme} 
                className="p-3 bg-white dark:bg-slate-800 rounded-full border border-slate-200 dark:border-slate-700 text-slate-500 dark:text-slate-400 hover:text-brand-secondary dark:hover:text-white transition shadow-sm active:scale-95"
                aria-label="Toggle Theme"
             >
                {theme === 'dark' ? <Sun size={20} /> : <Moon size={20} />}
             </button>
             <button className="p-3 bg-white dark:bg-slate-800 rounded-full border border-slate-200 dark:border-slate-700 relative text-slate-500 dark:text-slate-400 hover:text-brand-secondary dark:hover:text-white transition shadow-sm active:scale-95">
                <Bell size={20} />
                <span className="absolute top-2.5 right-2.5 w-2 h-2 bg-red-500 rounded-full border border-white dark:border-brand-dark"></span>
             </button>
          </div>
        </div>

        {/* Vital Info: Weather Widget - Hide when searching to save space */}
        {!searchTerm && (
            <div className="mb-6 bg-gradient-to-r from-blue-500 to-cyan-500 rounded-2xl p-4 text-white shadow-lg shadow-blue-500/20 flex justify-between items-center relative overflow-hidden animate-fadeIn">
                <div className="absolute -right-10 -top-10 w-40 h-40 bg-white/10 rounded-full blur-2xl"></div>
                <div className="relative z-10">
                    <p className="text-blue-100 text-xs font-bold mb-1 uppercase tracking-wider">Pitch Conditions</p>
                    <h3 className="text-3xl font-bold flex items-center">
                        26°C <span className="text-sm font-medium ml-2 opacity-90">Sunny</span>
                    </h3>
                    <p className="text-xs text-blue-50 mt-1 font-medium">Perfect weather for a match at Lugogo!</p>
                </div>
                <CloudSun size={56} className="text-yellow-300 relative z-10 drop-shadow-lg" />
            </div>
        )}

        {/* Search Bar */}
        <div className="flex space-x-3 mb-6 sticky top-0 z-20 py-2 bg-slate-50 dark:bg-brand-dark transition-colors duration-300">
          <div className="flex-1 bg-white dark:bg-slate-800 rounded-xl flex items-center px-4 py-4 border border-slate-200 dark:border-slate-700 shadow-sm focus-within:border-brand-secondary transition-all">
            <Search className="text-slate-400" size={20} />
            <input 
              type="text" 
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              placeholder="Find turfs by name or location..." 
              className="bg-transparent border-none outline-none text-slate-900 dark:text-white ml-3 w-full placeholder-slate-400 font-medium"
            />
            {searchTerm && (
                <button onClick={() => setSearchTerm('')} className="p-1 rounded-full bg-slate-200 dark:bg-slate-700">
                    <Filter size={14} className="text-slate-500" />
