            )}
          </div>
          <button className="bg-brand-secondary p-4 rounded-xl text-white shadow-lg shadow-emerald-500/30 hover:bg-emerald-600 transition-all flex items-center justify-center aspect-square active:scale-95">
            <Filter size={20} />
          </button>
        </div>

        {/* Categories - Hide when searching */}
        {!searchTerm && (
            <div className="flex space-x-3 mb-8 overflow-x-auto scrollbar-hide pb-2">
                {categories.map(c => (
                    <button 
                        key={c.name}
                        onClick={() => setFilter(c.name)}
                        className={`flex items-center space-x-2 px-5 py-3 rounded-full text-xs font-bold transition-all border whitespace-nowrap ${
                            filter === c.name 
                            ? 'bg-brand-secondary border-brand-secondary text-white shadow-md' 
                            : 'bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-700 text-slate-500 dark:text-slate-400 hover:border-brand-secondary hover:text-brand-secondary'
                        }`}
                    >
