        )}

        {/* Live Match Ticker - Hide when searching */}
        {!searchTerm && (
            <div className="mb-8">
                <div className="flex justify-between items-center mb-3">
                    <h2 className="text-lg font-bold text-slate-900 dark:text-white flex items-center">
                        Uganda Premier League
                        <span className="ml-2 w-1.5 h-1.5 bg-red-500 rounded-full animate-pulse"></span>
                    </h2>
                    <span className="text-brand-secondary text-xs font-bold cursor-pointer hover:underline">View All</span>
                </div>
                <div onClick={() => navigate('/live')} className="bg-white dark:bg-slate-800 rounded-2xl p-4 border border-slate-200 dark:border-slate-700 shadow-sm flex items-center justify-between cursor-pointer hover:border-brand-secondary transition-colors relative overflow-hidden group">
                     <div className="flex flex-col items-center w-1/3 relative z-10">
                         <div className="w-10 h-10 rounded-full bg-slate-100 dark:bg-slate-700 mb-2 flex items-center justify-center font-bold text-xs">KCC</div>
                         <div className="font-bold text-slate-900 dark:text-white text-sm mb-1">{liveMatch.homeTeam}</div>
                     </div>
                     <div className="flex flex-col items-center w-1/3 px-2 relative z-10">
                         <div className="text-2xl font-black text-slate-900 dark:text-white tracking-widest mb-1">
                            {liveMatch.homeScore} : {liveMatch.awayScore}
