                         <span className="text-[10px] font-bold text-red-500 bg-red-500/10 px-2 py-0.5 rounded-full animate-pulse">LIVE • {liveMatch.time}</span>
                     </div>
                     <div className="flex flex-col items-center w-1/3 relative z-10">
                         <div className="w-10 h-10 rounded-full bg-slate-100 dark:bg-slate-700 mb-2 flex items-center justify-center font-bold text-xs">VIP</div>
                         <div className="font-bold text-slate-900 dark:text-white text-sm mb-1">{liveMatch.awayTeam}</div>
                     </div>
                </div>
            </div>
        )}

        {/* Featured Turf - Only show if not searching or if search matches it */}
        {!searchTerm && (
            <div className="mb-8" onClick={() => navigate(`/turf/${featuredTurf.id}`)}>
                <div className="flex justify-between items-center mb-4">
                    <h2 className="text-xl font-bold text-slate-900 dark:text-white">Popular in Bugolobi</h2>
                    <button className="text-brand-secondary text-xs font-bold hover:text-emerald-600 transition">View All</button>
                </div>
                <div className="bg-white dark:bg-slate-800 rounded-3xl p-3 border border-slate-200 dark:border-slate-700 shadow-lg overflow-hidden group transition-transform active:scale-[0.98] cursor-pointer">
                    <div className="relative h-52 rounded-2xl overflow-hidden mb-4">
                        <img src={featuredTurf.image} alt={featuredTurf.name} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" />

                        <div className="absolute top-3 left-3 bg-white/90 dark:bg-black/60 backdrop-blur-md text-slate-900 dark:text-white text-xs font-bold px-3 py-1.5 rounded-full flex items-center shadow-sm">
                            <Zap size={12} className="text-orange-500 fill-current mr-1" /> Trending
                        </div>
                        <div className="absolute top-3 right-3 bg-black/40 backdrop-blur-md p-2 rounded-full hover:bg-red-500 transition-colors">
                            <Heart className="text-white" size={18} />
                        </div>
                        <div className="absolute bottom-3 left-3 flex gap-2">
                            {featuredTurf.amenities.slice(0,2).map(am => (
                                <span key={am} className="text-[10px] font-bold bg-black/60 backdrop-blur-md text-white px-2 py-1 rounded-lg">
                                    {am}
