                            <label className="text-xs font-bold text-slate-500 uppercase mb-3 block">Sort By</label>
                            <div className="flex gap-2">
                                <button className="flex-1 py-3 border border-brand-secondary bg-brand-secondary/10 text-brand-secondary font-bold rounded-xl text-sm">Recommended</button>
                                <button className="flex-1 py-3 border border-slate-200 dark:border-slate-700 text-slate-500 font-bold rounded-xl text-sm">Lowest Price</button>
                            </div>
                        </div>

                        <button 
                            onClick={() => setShowFilterModal(false)}
                            className="w-full py-4 bg-brand-secondary text-white font-bold rounded-xl shadow-lg hover:bg-emerald-600 active:scale-95 transition-all"
                        >
                            Apply Filters
                        </button>
                    </div>
                </div>
            </div>
        )}
      </div>
    </Layout>
  );
};

import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { ChevronLeft, ChevronRight, Share2, Heart, Star, CheckCircle, Home, Calendar, Clock, Lock, Users, Zap, Coffee, Shirt, Car, HeartPulse, ShoppingBag, Trophy, MapPin, QrCode } from 'lucide-react';
import { useBooking } from '../context/BookingContext';
import { useUser } from '../context/UserContext';

export const TurfDetail: React.FC = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const { turfs, bookings, addBooking } = useBooking();
  const { addXP } = useUser();

  const turf = turfs.find(t => t.id === id) || turfs[0];

  const [step, setStep] = useState<'details' | 'booking' | 'success'>('details');
  const [bookingId, setBookingId] = useState<string>('');

  // Calendar State
  const [currentMonth, setCurrentMonth] = useState(new Date());
  const [selectedDate, setSelectedDate] = useState<Date>(new Date());

  const [selectedTime, setSelectedTime] = useState<string | null>(null);
  const [duration, setDuration] = useState(1);
  const [splitPayment, setSplitPayment] = useState(false);

  // Derived State
  const totalPrice = turf.pricePerHour * duration;
  const splitPrice = Math.round(totalPrice / 5); // Mock 4 teammates + 1 user
  const dateStr = selectedDate.toISOString().split('T')[0];
  const isDateBlocked = turf.blockedDates.includes(dateStr);

  const getAmenityIcon = (amenity: string) => {
    const lower = amenity.toLowerCase();
    if (lower.includes('floodlight')) return <Zap size={18} className="text-yellow-400" />;
    if (lower.includes('bar')) return <Coffee size={18} className="text-amber-600" />;
    if (lower.includes('lounge')) return <Coffee size={18} className="text-orange-400" />;
    if (lower.includes('changing')) return <Shirt size={18} className="text-blue-400" />;
    if (lower.includes('shower')) return <Shirt size={18} className="text-cyan-400" />;
    if (lower.includes('parking')) return <Car size={18} className="text-slate-400" />;
    if (lower.includes('stand') || lower.includes('seat')) return <Users size={18} className="text-brand-secondary" />;
    if (lower.includes('aid')) return <HeartPulse size={18} className="text-red-500" />;
    if (lower.includes('shop')) return <ShoppingBag size={18} className="text-purple-400" />;
    if (lower.includes('turf')) return <Trophy size={18} className="text-emerald-400" />;
    return <CheckCircle size={18} className="text-slate-500" />;
  };

  // Generate Available Times based on Turf Operating Hours
  const generateTimeSlots = () => {
      const slots = [];
      const start = parseInt(turf.openingHour.split(':')[0]);
      const end = parseInt(turf.closingHour.split(':')[0]);

      for (let i = start; i < end; i++) {
          const time = `${i.toString().padStart(2, '0')}:00`;

          const isBooked = bookings.some(b => 
              b.turfId === turf.id && 
              b.date === dateStr && 
              b.time === time && 
              b.status !== 'CANCELLED'
          );

          slots.push({ time, isBooked });
      }
      return slots;
  };

  const timeSlots = generateTimeSlots();

  const handleBookingSubmit = () => {
      if (!selectedTime) return;

      const newId = Math.random().toString(36).substr(2, 9).toUpperCase();
      setBookingId(newId);

      addBooking({
          id: newId,
          turfId: turf.id,
          turfName: turf.name,
          userName: 'You', // In a real app, this comes from Auth
          date: dateStr,
          time: selectedTime,
          duration: duration,
          status: 'PENDING',
          price: totalPrice,
          createdAt: new Date().toISOString()
      });

      // Award XP for booking
      addXP(150);
      setStep('success');
  };

  // Calendar Helpers
  const daysInMonth = new Date(currentMonth.getFullYear(), currentMonth.getMonth() + 1, 0).getDate();
  const firstDayOfMonth = new Date(currentMonth.getFullYear(), currentMonth.getMonth(), 1).getDay();
  const prevMonth = () => setCurrentMonth(new Date(currentMonth.getFullYear(), currentMonth.getMonth() - 1, 1));
  const nextMonth = () => setCurrentMonth(new Date(currentMonth.getFullYear(), currentMonth.getMonth() + 1, 1));

  const isSelected = (day: number) => {
    return selectedDate.getDate() === day && 
           selectedDate.getMonth() === currentMonth.getMonth() && 
           selectedDate.getFullYear() === currentMonth.getFullYear();
  };

  if (step === 'success') {
      return (
          <div className="min-h-screen bg-slate-900 flex flex-col items-center justify-center p-6 text-center relative overflow-hidden">
              <div className="absolute inset-0 bg-brand-secondary/5" />

              <div className="bg-brand-secondary w-16 h-16 rounded-full flex items-center justify-center mb-4 shadow-[0_0_20px_rgba(16,185,129,0.5)] animate-bounce">
                  <CheckCircle size={32} className="text-white" />
              </div>

              <h1 className="text-2xl font-bold text-white mb-1">Booking Confirmed!</h1>
              <p className="text-slate-400 text-sm mb-6">Your slot has been reserved.</p>

              {/* Ticket / QR Card */}
              <div className="bg-white text-slate-900 w-full max-w-sm rounded-3xl overflow-hidden shadow-2xl relative mb-8">
                  {/* Top Part: Details */}
                  <div className="p-6 border-b border-dashed border-slate-300 relative">
                       {/* Punch holes for ticket effect */}
                       <div className="absolute bottom-0 left-0 transform -translate-x-1/2 translate-y-1/2 w-6 h-6 bg-slate-900 rounded-full"></div>
                       <div className="absolute bottom-0 right-0 transform translate-x-1/2 translate-y-1/2 w-6 h-6 bg-slate-900 rounded-full"></div>

                       <div className="text-center mb-4">
                           <h2 className="text-xl font-bold mb-1">{turf.name}</h2>
                           <p className="text-slate-500 text-xs flex items-center justify-center">
                               <MapPin size={10} className="mr-1" /> {turf.location}
                           </p>
                       </div>

                       <div className="grid grid-cols-2 gap-4 text-left">
                           <div>
                               <p className="text-[10px] text-slate-400 uppercase font-bold">Date</p>
                               <p className="font-bold text-sm">{dateStr}</p>
                           </div>
                           <div className="text-right">
                               <p className="text-[10px] text-slate-400 uppercase font-bold">Time</p>
                               <p className="font-bold text-sm">{selectedTime}</p>
                           </div>
                           <div>
                               <p className="text-[10px] text-slate-400 uppercase font-bold">Duration</p>
                               <p className="font-bold text-sm">{duration} hr{duration > 1 ? 's' : ''}</p>
                           </div>
                           <div className="text-right">
                               <p className="text-[10px] text-slate-400 uppercase font-bold">Total</p>
                               <p className="font-bold text-brand-secondary text-sm">UGX {totalPrice.toLocaleString()}</p>
                           </div>
                       </div>
                  </div>

                  {/* Bottom Part: QR */}
                  <div className="p-6 flex flex-col items-center justify-center bg-slate-50">
                      <div className="bg-white p-2 rounded-xl shadow-sm border border-slate-100 mb-2">
                           <QrCode size={120} className="text-slate-900" />
                      </div>
                      <p className="text-xs font-mono text-slate-500">ID: {bookingId}</p>
                      <p className="text-[10px] text-slate-400 mt-2">Scan at venue for entry</p>
                  </div>
              </div>

              <div className="w-full max-w-sm space-y-3">
                  <button onClick={() => navigate('/bookings')} className="bg-brand-secondary text-white w-full py-4 rounded-xl font-bold flex items-center justify-center shadow-lg hover:bg-emerald-600 transition-colors">
                      View My Bookings
                  </button>
                  <button onClick={() => navigate('/home')} className="text-slate-400 text-sm font-medium hover:text-white transition-colors">
                      Back to Home
                  </button>
              </div>
          </div>
      );
  }

  if (step === 'booking') {
      return (
          <div className="min-h-screen bg-slate-50 dark:bg-brand-dark p-4 flex flex-col">
              <div className="flex items-center justify-between mb-6">
                  <button onClick={() => setStep('details')} className="p-2 bg-slate-200 dark:bg-slate-800 rounded-full text-slate-600 dark:text-white">
                      <ChevronLeft />
                  </button>
                  <div className="text-center">
                      <h2 className="text-slate-900 dark:text-white font-bold text-lg">Select Slot</h2>
                      <p className="text-slate-500 dark:text-slate-400 text-xs">{turf.name}</p>
                  </div>
                  <div className="w-10" />
              </div>

              <div className="flex-1 overflow-y-auto pb-24 scrollbar-hide">
                  {/* Calendar Strip */}
                  <div className="mb-6 bg-white dark:bg-slate-800 rounded-2xl p-4 border border-slate-200 dark:border-slate-700">
                      <div className="flex justify-between items-center mb-4 text-slate-900 dark:text-white">
                          <button onClick={prevMonth} className="p-2 hover:bg-slate-100 dark:hover:bg-slate-700 rounded-full transition-colors hover:text-brand-secondary"><ChevronLeft size={20} /></button>
                          <h3 className="font-bold text-lg">{currentMonth.toLocaleDateString('en-US', { month: 'long', year: 'numeric' })}</h3>
                          <button onClick={nextMonth} className="p-2 hover:bg-slate-100 dark:hover:bg-slate-700 rounded-full transition-colors hover:text-brand-secondary"><ChevronRight size={20} /></button>
                      </div>
                      <div className="grid grid-cols-7 gap-1 text-center text-xs text-slate-400 dark:text-slate-500 mb-2 font-medium">
                          <div>Su</div><div>Mo</div><div>Tu</div><div>We</div><div>Th</div><div>Fr</div><div>Sa</div>
                      </div>
                      <div className="grid grid-cols-7 gap-y-2 gap-x-1 text-center">
                           {Array.from({ length: firstDayOfMonth }).map((_, i) => <div key={`empty-${i}`} />)}
                           {Array.from({ length: daysInMonth }).map((_, i) => {
                               const day = i + 1;
                               const selected = isSelected(day);
                               return (
                                   <button 
                                       key={day}
                                       onClick={() => setSelectedDate(new Date(currentMonth.getFullYear(), currentMonth.getMonth(), day))}
                                       className={`w-8 h-8 rounded-full flex items-center justify-center mx-auto text-sm transition-all relative
                                           ${selected 
                                               ? 'bg-brand-secondary text-white font-bold shadow-lg ring-2 ring-offset-2 ring-offset-white dark:ring-offset-slate-800 ring-brand-secondary scale-110 z-10' 
                                               : 'text-slate-600 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-700'
                                           }
                                       `}
                                   >
                                       {day}
                                   </button>
                               );
                           })}
                      </div>
                  </div>

                  {/* Available Slots */}
                  <div className="mb-6">
                      <h3 className="text-slate-900 dark:text-white font-bold flex items-center mb-3">
                          <span className="mr-2 text-brand-secondary"><Calendar size={18} /></span>
                          {isDateBlocked ? 'Venue Closed' : 'Available Slots'}
                      </h3>

                      {isDateBlocked ? (
                          <div className="bg-red-500/10 border border-red-500/30 rounded-xl p-4 flex flex-col items-center justify-center text-center">
                              <Lock className="text-red-500 mb-2" size={24} />
                              <p className="text-red-400 font-bold">This turf is closed on this date.</p>
                              <p className="text-red-400/70 text-sm">Please select another day.</p>
                          </div>
                      ) : (
                          <div className="grid grid-cols-3 gap-3">
                              {timeSlots.map(({ time, isBooked }) => (
                                  <button 
                                    key={time}
                                    disabled={isBooked}
                                    onClick={() => setSelectedTime(time)}
                                    className={`py-3 rounded-xl text-sm font-bold border transition-all ${
                                        isBooked 
                                            ? 'bg-slate-100 dark:bg-slate-800 text-slate-400 dark:text-slate-600 border-slate-200 dark:border-slate-800 cursor-not-allowed decoration-slate-400' 
                                            : selectedTime === time 
                                                ? 'bg-brand-secondary border-brand-secondary text-white shadow-md' 
                                                : 'bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-700 text-slate-600 dark:text-slate-300 hover:border-brand-secondary/50' 
                                    }`}
                                  >
                                      {time}
                                      {isBooked && <span className="block text-[8px] uppercase mt-1">Booked</span>}
                                  </button>
                              ))}
                          </div>
