                  </div>

                  {/* Duration Picker */}
                  {!isDateBlocked && (
                      <div className="mb-6">
                          <h3 className="text-slate-900 dark:text-white font-bold flex items-center mb-3">
                              <span className="mr-2 text-brand-secondary"><Clock size={18} /></span>
                              Duration
                          </h3>
                          <div className="flex bg-white dark:bg-slate-800 p-1 rounded-xl border border-slate-200 dark:border-slate-700">
                              {[1, 2, 3].map(h => (
                                  <button 
                                    key={h}
                                    onClick={() => setDuration(h)}
                                    className={`flex-1 py-3 rounded-lg text-sm font-bold transition-all ${
                                        duration === h 
                                        ? 'bg-brand-secondary text-white shadow-md' 
                                        : 'text-slate-500 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white'
                                    }`}
                                  >
                                      {h} hr{h > 1 ? 's' : ''}
                                  </button>
                              ))}
                          </div>
                      </div>
                  )}

                  {/* Split Payment Toggle */}
                  {!isDateBlocked && (
                    <div className="mb-8">
                        <div 
                            onClick={() => setSplitPayment(!splitPayment)}
                            className={`p-4 rounded-xl flex items-center justify-between border cursor-pointer active:scale-[0.98] transition-all ${
                                splitPayment 
                                ? 'bg-white dark:bg-slate-800 border-brand-secondary ring-1 ring-brand-secondary/50' 
                                : 'bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-700'
