                                    {/* Divider */}
                                    <div className="h-px w-8 bg-slate-300 dark:bg-slate-700"></div>

                                    {/* Teammates Mock */}
                                    <div className="flex -space-x-3">
                                        {[1,2,3,4].map(i => (
                                            <div key={i} className="w-12 h-12 rounded-full bg-slate-200 dark:bg-slate-700 text-slate-500 dark:text-slate-400 flex items-center justify-center border-2 border-white dark:border-slate-800 font-bold text-xs relative z-0" style={{zIndex: 4-i}}>
                                                <Users size={16} />
                                            </div>
                                        ))}
                                    </div>

                                    <div className="flex flex-col items-end">
                                        <span className="text-slate-500 dark:text-slate-400 text-xs">4 others</span>
                                        <span className="text-slate-900 dark:text-white font-bold text-xs">UGX {splitPrice.toLocaleString()} ea</span>
                                    </div>
                                </div>

                                <div className="pt-3 border-t border-slate-200 dark:border-slate-700 flex justify-between items-center">
