                                <div className="bg-slate-900/50 backdrop-blur-sm px-3 py-1 rounded-full flex items-center text-slate-400 text-[10px] font-bold border border-slate-700">
                                    Full Time
                                </div>
                            )}
                        </div>

                        <div className="flex justify-between items-center px-1 relative z-10">
                            {/* Home */}
                            <div className="flex flex-col items-center w-1/3">
                                <div className="w-14 h-14 rounded-full bg-slate-800 mb-3 flex items-center justify-center border border-slate-700 p-2 shadow-inner">
                                    <img src={match.home.logo} className="w-full h-full object-contain" alt={match.home.name} />
                                </div>
                                <span className="text-center text-xs font-bold uppercase tracking-wide text-slate-300">{match.home.name}</span>
                            </div>

                            {/* Scores */}
                            <div className="flex flex-col items-center justify-center w-1/3">
                                <div className="text-4xl font-bold text-white mb-2 tracking-tighter">{match.score}</div>
                                <div className={`text-xs font-bold px-3 py-1 rounded-full border ${match.status === 'LIVE' ? 'text-brand-secondary bg-brand-secondary/10 border-brand-secondary/20' : 'text-slate-500 border-slate-700'}`}>
                                    {match.time}
                                </div>
                            </div>

                            {/* Away */}
                            <div className="flex flex-col items-center w-1/3">
                                <div className="w-14 h-14 rounded-full bg-slate-800 mb-3 flex items-center justify-center border border-slate-700 p-2 shadow-inner">
                                    <img src={match.away.logo} className="w-full h-full object-contain" alt={match.away.name} />
                                </div>
                                <span className="text-center text-xs font-bold uppercase tracking-wide text-slate-300">{match.away.name}</span>
                            </div>
                        </div>

                        <div className="mt-4 pt-4 border-t border-slate-700/50 flex justify-between items-center">
                             <div className="flex -space-x-2">
                                 {[1,2,3].map(i => <div key={i} className="w-6 h-6 rounded-full bg-slate-700 border border-slate-800"></div>)}
                             </div>
                             <div className="text-[10px] text-brand-secondary font-bold flex items-center">
                                 Match Details <ChevronRight size={12} className="ml-1" />
                             </div>
                        </div>
                    </div>
                ))}
            </div>
        </div>
    </Layout>
  );
};

