import React, { useState, useRef, useEffect } from 'react';
import { Layout } from '../components/Layout';
import { MY_TEAMS, TURFS, TEAM_LEADERBOARD } from '../constants';
import { Plus, Users, Swords, Search, MessageCircle, X, ChevronRight, Trophy, TrendingUp, Medal, Send, CheckCheck, Phone, MoreVertical, ArrowLeft, ChevronDown, Calendar, Clock, MapPin, CheckCircle, Bell, Mic, MicOff, PhoneOff, Volume2, Reply, Trash2, Info, Copy } from 'lucide-react';

export const Teams: React.FC = () => {
  const [showChallengeModal, setShowChallengeModal] = useState(false);
  const [showChat, setShowChat] = useState(false);
  const [activeTab, setActiveTab] = useState<'My Teams' | 'Leaderboard'>('My Teams');
  const myTeam = MY_TEAMS[0];

  // Chat State (Lifted for persistence)
  const [chatMessages, setChatMessages] = useState([
    { id: 1, text: "Tactics for tomorrow?", sender: "Mike", avatar: "https://images.unsplash.com/photo-1599566150163-29194dcaad36?w=100&h=100&fit=crop", time: "09:41 AM", isMe: false, read: true, replyTo: null },
    { id: 2, text: "4-3-3, high press. We need to win this.", sender: "Coach", avatar: "https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?w=100&h=100&fit=crop", time: "09:42 AM", isMe: false, read: true, replyTo: null },
    { id: 3, text: "I'll be there early to warm up.", sender: "You", avatar: "", time: "09:45 AM", isMe: true, read: true, replyTo: null },
  ]);
  const [unreadCount, setUnreadCount] = useState(0);

  // Challenge State
  const [selectedOpponent, setSelectedOpponent] = useState(TEAM_LEADERBOARD.find(t => t.name !== myTeam.name) || TEAM_LEADERBOARD[1]);
  const [selectedVenue, setSelectedVenue] = useState(TURFS[0]);
  const [challengeDate, setChallengeDate] = useState("");
  const [challengeTime, setChallengeTime] = useState("18:00");
  const [challengeDuration, setChallengeDuration] = useState(1);
  const [challengeSent, setChallengeSent] = useState(false);

  // Initialize Date
  useEffect(() => {
    if (showChallengeModal) {
        setChallengeSent(false);
        const tomorrow = new Date();
        tomorrow.setDate(tomorrow.getDate() + 1);
        setChallengeDate(tomorrow.toISOString().split('T')[0]);
    }
  }, [showChallengeModal]);

  // Simulate Incoming Message for Notification
  useEffect(() => {
      const timer = setTimeout(() => {
          const newMsg = {
              id: Date.now(),
              text: "Don't forget the bibs! 🎽",
              sender: "Sarah",
              avatar: "https://images.unsplash.com/photo-1438761681033-6461ffad8d80?w=100&h=100&fit=crop",
              time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
              isMe: false,
              read: false,
              replyTo: null
          };
          setChatMessages(prev => [...prev, newMsg]);
          if (!showChat) {
              setUnreadCount(prev => prev + 1);
          }
      }, 5000);
      return () => clearTimeout(timer);
  }, []);

  // Clear unread when chat opens
  useEffect(() => {
      if (showChat) setUnreadCount(0);
  }, [showChat]);

  const ChatModal = () => {
    const messagesEndRef = useRef<null | HTMLDivElement>(null);
    const inputRef = useRef<HTMLInputElement>(null);
    const [inputValue, setInputValue] = useState("");
    const [showOnlineList, setShowOnlineList] = useState(false);
    const [isTyping, setIsTyping] = useState(false);

    // Feature States
    const [activeCall, setActiveCall] = useState(false);
    const [isMuted, setIsMuted] = useState(false);
    const [isSpeaker, setIsSpeaker] = useState(false);
    const [callDuration, setCallDuration] = useState(0);
    const [replyingTo, setReplyingTo] = useState<any>(null);
    const [showMenu, setShowMenu] = useState(false);

    const ONLINE_MEMBERS = [
        { name: "Mike", avatar: "https://images.unsplash.com/photo-1599566150163-29194dcaad36?w=100&h=100&fit=crop", status: 'online' },
        { name: "Coach", avatar: "https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?w=100&h=100&fit=crop", status: 'online' },
        { name: "Sarah", avatar: "https://images.unsplash.com/photo-1438761681033-6461ffad8d80?w=100&h=100&fit=crop", status: 'away' },
        { name: "John", avatar: "https://images.unsplash.com/photo-1500648767791-00dcc994a43e?w=100&h=100&fit=crop", status: 'offline' },
    ];

    const activeMembers = ONLINE_MEMBERS.filter(m => m.status !== 'offline');

    const scrollToBottom = () => {
      messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
    };

    useEffect(scrollToBottom, [chatMessages, isTyping, replyingTo]);

    // Call Timer
    useEffect(() => {
        let interval: any;
        if (activeCall) {
            interval = setInterval(() => {
                setCallDuration(prev => prev + 1);
            }, 1000);
        } else {
            setCallDuration(0);
        }
        return () => clearInterval(interval);
    }, [activeCall]);

    const formatTime = (seconds: number) => {
        const mins = Math.floor(seconds / 60).toString().padStart(2, '0');
        const secs = (seconds % 60).toString().padStart(2, '0');
        return `${mins}:${secs}`;
    };

    // Simulate random typing from others
    useEffect(() => {
        const timeout = setTimeout(() => {
            setIsTyping(true);
            setTimeout(() => setIsTyping(false), 4000);
        }, 3000);
        return () => clearTimeout(timeout);
    }, []);

    const sendMessage = () => {
        if (!inputValue.trim()) return;
        const newMsg = {
            id: Date.now(),
            text: inputValue,
            sender: "You",
            avatar: "",
            time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
            isMe: true,
            read: false,
            replyTo: replyingTo ? { sender: replyingTo.sender, text: replyingTo.text } : null
        };
        setChatMessages([...chatMessages, newMsg]);
        setInputValue("");
        setReplyingTo(null);

        // Simulate read receipt
        setTimeout(() => {
             setChatMessages(prev => prev.map(m => m.id === newMsg.id ? {...m, read: true} : m));
        }, 2000);
    };

    return (
        <div className="fixed inset-0 z-50 bg-slate-50 dark:bg-brand-dark flex flex-col animate-slideUp">

            {/* Audio Call Overlay */}
            {activeCall && (
                <div className="absolute inset-0 z-[60] bg-slate-900 flex flex-col items-center justify-center text-white animate-fadeIn">
                    <div className="flex-1 flex flex-col items-center justify-center w-full">
                        <div className="relative mb-8">
                            <div className="w-32 h-32 rounded-full overflow-hidden border-4 border-brand-secondary z-10 relative shadow-[0_0_30px_rgba(16,185,129,0.5)]">
                                <img src={myTeam.logo} className="w-full h-full object-cover" />
                            </div>
                            <div className="absolute inset-0 rounded-full bg-brand-secondary/30 animate-ping"></div>
                            <div className="absolute inset-[-20px] rounded-full bg-brand-secondary/10 animate-pulse delay-75"></div>
                        </div>

                        <h3 className="text-3xl font-bold mb-2">{myTeam.name}</h3>
                        <p className="text-brand-secondary font-mono text-xl tracking-widest mb-2">{formatTime(callDuration)}</p>
                        <p className="text-slate-400 text-sm flex items-center">
                            <Users size={14} className="mr-2" /> {activeMembers.length + 1} participants
                        </p>
                    </div>

                    <div className="bg-slate-800 w-full rounded-t-3xl p-8 pb-12">
                        <div className="flex justify-center items-center space-x-8">
                            <button 
                                onClick={() => setIsMuted(!isMuted)}
                                className={`p-5 rounded-full transition-all ${isMuted ? 'bg-white text-slate-900' : 'bg-slate-700 text-white hover:bg-slate-600'}`}
                            >
                                {isMuted ? <MicOff size={24} /> : <Mic size={24} />}
                            </button>

                            <button 
                                onClick={() => setActiveCall(false)}
                                className="p-6 bg-red-500 rounded-full text-white shadow-lg hover:bg-red-600 transform hover:scale-105 transition-all"
                            >
                                <PhoneOff size={32} />
                            </button>

                            <button 
                                onClick={() => setIsSpeaker(!isSpeaker)}
                                className={`p-5 rounded-full transition-all ${isSpeaker ? 'bg-white text-slate-900' : 'bg-slate-700 text-white hover:bg-slate-600'}`}
                            >
                                <Volume2 size={24} />
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* Header */}
            <div className="bg-white dark:bg-brand-surface p-4 border-b border-slate-200 dark:border-slate-700 shadow-sm flex justify-between items-center z-20 relative">
                <div className="flex items-center">
                    <button onClick={() => setShowChat(false)} className="mr-3 p-2 hover:bg-slate-100 dark:hover:bg-slate-700 rounded-full transition-colors">
                        <ArrowLeft size={20} className="text-slate-600 dark:text-slate-300" />
                    </button>
                    <div 
                        className="cursor-pointer group" 
                        onClick={() => setShowOnlineList(!showOnlineList)}
                    >
                        <h3 className="font-bold text-slate-900 dark:text-white text-lg leading-tight flex items-center">
                            {myTeam.name}
                            <ChevronDown size={14} className={`ml-1 transition-transform ${showOnlineList ? 'rotate-180' : ''}`} />
                        </h3>
                        <div className="flex items-center text-xs text-brand-secondary font-medium">
                            <span className="w-2 h-2 bg-brand-secondary rounded-full mr-1.5 animate-pulse"></span>
                            {activeMembers.length} Online
                        </div>
                    </div>
                </div>
                <div className="flex space-x-1 text-slate-500 dark:text-slate-400 relative">
                    <button 
                        onClick={() => setActiveCall(true)}
                        className="p-2 hover:bg-slate-100 dark:hover:bg-slate-700 rounded-full transition-colors text-brand-secondary"
                    >
                        <Phone size={20} />
                    </button>
                    <button 
                        onClick={() => setShowMenu(!showMenu)}
                        className="p-2 hover:bg-slate-100 dark:hover:bg-slate-700 rounded-full transition-colors"
                    >
                        <MoreVertical size={20} />
                    </button>

                    {/* Menu Dropdown */}
                    {showMenu && (
                        <div className="absolute top-full right-0 mt-2 w-48 bg-white dark:bg-slate-800 rounded-xl shadow-xl border border-slate-100 dark:border-slate-700 z-50 overflow-hidden animate-fadeIn">
                            <button className="w-full text-left px-4 py-3 hover:bg-slate-50 dark:hover:bg-slate-700 flex items-center text-sm text-slate-700 dark:text-slate-200">
                                <Info size={16} className="mr-2" /> Group Info
                            </button>
                            <button className="w-full text-left px-4 py-3 hover:bg-slate-50 dark:hover:bg-slate-700 flex items-center text-sm text-slate-700 dark:text-slate-200">
                                <Search size={16} className="mr-2" /> Search Chat
                            </button>
                            <button className="w-full text-left px-4 py-3 hover:bg-red-50 dark:hover:bg-red-900/20 flex items-center text-sm text-red-500">
                                <Trash2 size={16} className="mr-2" /> Clear Chat
                            </button>
                        </div>
                    )}
                </div>

                {/* Online Users Dropdown */}
                {showOnlineList && (
                    <div className="absolute top-full left-12 mt-2 bg-white dark:bg-slate-800 shadow-xl rounded-2xl p-3 border border-slate-100 dark:border-slate-700 w-56 animate-fadeIn z-50">
                        <h4 className="text-[10px] font-bold text-slate-400 mb-3 uppercase tracking-wider">Team Members</h4>
                        {ONLINE_MEMBERS.map((u, i) => (
                            <div key={i} className="flex items-center mb-3 last:mb-0">
                                <div className="relative mr-3">
                                    <img src={u.avatar} className={`w-8 h-8 rounded-full object-cover ${u.status === 'offline' ? 'grayscale opacity-60' : ''}`} />
                                    <div className={`absolute bottom-0 right-0 w-2.5 h-2.5 rounded-full border-2 border-white dark:border-slate-800 ${
                                        u.status === 'online' ? 'bg-brand-secondary' : u.status === 'away' ? 'bg-yellow-500' : 'bg-slate-400'
                                    }`}></div>
                                </div>
                                <div>
                                    <span className="text-sm font-bold text-slate-700 dark:text-slate-200 block leading-tight">{u.name}</span>
                                    <span className="text-[10px] text-slate-400 capitalize">{u.status}</span>
                                </div>
                            </div>
                        ))}
                    </div>
                )}
            </div>

            {/* Messages */}
            <div className="flex-1 overflow-y-auto p-4 space-y-4 bg-slate-50 dark:bg-brand-dark">
                 {/* Date Divider */}
                 <div className="flex justify-center my-4">
                     <span className="bg-slate-200 dark:bg-slate-800 text-slate-500 dark:text-slate-400 text-[10px] font-bold px-3 py-1 rounded-full uppercase tracking-wider shadow-sm">Today</span>
                 </div>

                 {chatMessages.map((msg) => (
                     <div key={msg.id} className={`flex flex-col ${msg.isMe ? 'items-end' : 'items-start'} animate-fadeIn group`}>
                         <div className={`flex ${msg.isMe ? 'justify-end' : 'justify-start'} max-w-[85%]`}>
                            {!msg.isMe && (
                                <div className="relative mr-2 self-end">
                                    <img src={msg.avatar} className="w-8 h-8 rounded-full border border-slate-200 dark:border-slate-700 object-cover" />
                                    <div className="absolute bottom-0 right-0 w-2.5 h-2.5 bg-brand-secondary border-2 border-slate-50 dark:border-brand-dark rounded-full"></div>
                                </div>
                            )}
                            <div className="relative">
                                {/* Reply Context Bubble */}
                                {msg.replyTo && (
                                    <div className={`mb-1 p-2 rounded-lg text-xs border-l-4 opacity-80 ${
                                        msg.isMe 
                                        ? 'bg-brand-secondary/20 text-slate-900 dark:text-white border-brand-secondary rounded-br-none' 
                                        : 'bg-slate-200 dark:bg-slate-700 text-slate-600 dark:text-slate-300 border-slate-400 rounded-bl-none'
                                    }`}>
                                        <div className="font-bold mb-0.5">{msg.replyTo.sender}</div>
                                        <div className="truncate max-w-[150px]">{msg.replyTo.text}</div>
                                    </div>
                                )}

                                {/* Main Message Bubble */}
                                <div className={`px-4 py-2 relative shadow-sm transition-all ${
                                    msg.isMe 
                                    ? 'bg-brand-secondary text-white rounded-2xl rounded-br-none' 
                                    : 'bg-white dark:bg-slate-800 text-slate-800 dark:text-slate-200 rounded-2xl rounded-bl-none border border-slate-200 dark:border-slate-700'
                                }`}>
                                    {!msg.isMe && <p className="text-[10px] font-bold opacity-70 mb-0.5 text-brand-secondary">{msg.sender}</p>}
                                    <p className="text-sm leading-relaxed break-words">{msg.text}</p>
                                    <div className={`flex items-center justify-end space-x-1 mt-1 ${msg.isMe ? 'text-emerald-100' : 'text-slate-400'}`}>
                                        <span className="text-[10px]">{msg.time}</span>
                                        {msg.isMe && (
                                            <CheckCheck size={14} className={msg.read ? 'text-white' : 'text-emerald-200 opacity-60'} />
                                        )}
                                    </div>
                                </div>
                            </div>

                            {/* Actions (Reply/Copy) - Visible on Hover/Group Focus */}
                            <div className={`flex items-center opacity-0 group-hover:opacity-100 transition-opacity px-2 ${msg.isMe ? 'flex-row-reverse' : ''}`}>
                                <button 
                                    onClick={() => { setReplyingTo(msg); inputRef.current?.focus(); }}
                                    className="p-1.5 text-slate-400 hover:text-brand-secondary hover:bg-slate-100 dark:hover:bg-slate-700 rounded-full"
                                    title="Reply"
                                >
                                    <Reply size={14} />
                                </button>
                                <button className="p-1.5 text-slate-400 hover:text-brand-secondary hover:bg-slate-100 dark:hover:bg-slate-700 rounded-full">
                                    <Copy size={14} />
                                </button>
                            </div>
                         </div>
                     </div>
                 ))}

                 {/* Typing Indicator */}
                 {isTyping && (
                     <div className="flex items-end justify-start animate-fadeIn">
                         <div className="relative mr-2">
                             <img src={ONLINE_MEMBERS[0].avatar} className="w-8 h-8 rounded-full object-cover grayscale opacity-70" />
                         </div>
                         <div className="bg-slate-200 dark:bg-slate-800 px-4 py-3 rounded-2xl rounded-bl-none text-slate-500 flex items-center space-x-1 h-10">
                             <span className="w-1.5 h-1.5 bg-slate-400 rounded-full animate-bounce" style={{ animationDelay: '0ms' }}></span>
                             <span className="w-1.5 h-1.5 bg-slate-400 rounded-full animate-bounce" style={{ animationDelay: '150ms' }}></span>
                             <span className="w-1.5 h-1.5 bg-slate-400 rounded-full animate-bounce" style={{ animationDelay: '300ms' }}></span>
                         </div>
                     </div>
                 )}
                 <div ref={messagesEndRef} />
            </div>

            {/* Input */}
            <div className="bg-white dark:bg-brand-surface border-t border-slate-200 dark:border-slate-700 safe-area-bottom">
                 {/* Reply Preview Bar */}
                 {replyingTo && (
                     <div className="px-4 py-2 bg-slate-50 dark:bg-slate-800/50 flex justify-between items-center border-b border-slate-100 dark:border-slate-700 animate-slideUp">
                         <div className="flex items-center overflow-hidden">
                             <div className="w-1 h-8 bg-brand-secondary rounded-full mr-3"></div>
                             <div>
                                 <p className="text-brand-secondary text-xs font-bold flex items-center">
                                     <Reply size={10} className="mr-1" /> Replying to {replyingTo.sender}
                                 </p>
                                 <p className="text-slate-500 dark:text-slate-400 text-xs truncate max-w-[250px]">{replyingTo.text}</p>
                             </div>
                         </div>
                         <button 
                            onClick={() => setReplyingTo(null)}
                            className="p-1 text-slate-400 hover:text-slate-600 dark:hover:text-slate-200"
                         >
                             <X size={16} />
                         </button>
                     </div>
                 )}

                 <div className="p-3 flex items-center gap-2">
                    <button className="p-2 text-slate-400 hover:text-brand-secondary transition-colors bg-slate-100 dark:bg-slate-800 rounded-full">
                        <Plus size={20} />
                    </button>
                    <input 
                        ref={inputRef}
                        type="text" 
                        value={inputValue}
                        onChange={(e) => setInputValue(e.target.value)}
                        onKeyDown={(e) => e.key === 'Enter' && sendMessage()}
                        placeholder="Type a message..." 
                        className="flex-1 bg-slate-100 dark:bg-slate-800 border-none rounded-full px-4 py-3 text-sm focus:ring-2 focus:ring-brand-secondary outline-none text-slate-900 dark:text-white placeholder-slate-400"
                    />
                    <button 
                        onClick={sendMessage}
                        className="p-3 bg-brand-secondary text-white rounded-full shadow-lg hover:bg-emerald-600 transition-transform active:scale-95 disabled:opacity-50 disabled:scale-100"
                        disabled={!inputValue.trim()}
                    >
                        <Send size={18} className="ml-0.5" />
                    </button>
                 </div>
            </div>
        </div>
    );
  };

  const ChallengeModal = () => (
      <div className="fixed inset-0 z-50 flex items-end sm:items-center justify-center bg-black/80 backdrop-blur-sm animate-fadeIn">
          <div className="bg-white dark:bg-brand-surface w-full sm:w-[500px] rounded-t-3xl sm:rounded-3xl p-6 border-t border-slate-200 dark:border-slate-700 max-h-[90vh] overflow-y-auto">
              {challengeSent ? (
                  <div className="flex flex-col items-center justify-center py-10 text-center animate-fadeIn">
                      <div className="w-20 h-20 bg-green-500/20 text-green-500 rounded-full flex items-center justify-center mb-6 animate-bounce">
                          <CheckCircle size={40} />
                      </div>
                      <h3 className="text-2xl font-bold text-slate-900 dark:text-white mb-2">Challenge Sent!</h3>
                      <p className="text-slate-500 dark:text-slate-400">
                          We've notified <span className="font-bold text-slate-900 dark:text-white">{selectedOpponent?.name}</span>.<br/>
                          You'll be alerted when they accept.
                      </p>
                  </div>
              ) : (
                  <>
                    <div className="flex justify-between items-center mb-6">
                        <h3 className="text-xl font-bold text-slate-900 dark:text-white">Challenge a Team</h3>
                        <button onClick={() => setShowChallengeModal(false)}><X className="text-slate-500 dark:text-slate-400" /></button>
                    </div>

                    <div className="space-y-6">
                        {/* Matchup Header */}
                        <div className="flex items-center justify-between bg-slate-50 dark:bg-slate-800 p-4 rounded-2xl border border-slate-200 dark:border-slate-700">
                            <div className="flex flex-col items-center w-1/3">
                                <img src={myTeam.logo} className="w-12 h-12 rounded-xl mb-2 object-cover" />
                                <span className="text-xs font-bold text-center text-slate-900 dark:text-white leading-tight">{myTeam.name}</span>
                            </div>
                            <div className="flex flex-col items-center text-brand-secondary font-bold">
                                <span className="text-xs uppercase tracking-widest text-slate-400 mb-1">VS</span>
                                <Swords size={24} />
                            </div>
                            <div className="flex flex-col items-center w-1/3">
                                {/* Opponent Selector Trigger */}
                                <div className="relative group cursor-pointer w-full flex flex-col items-center">
                                    <img src={selectedOpponent?.logo || ''} className="w-12 h-12 rounded-xl mb-2 object-cover border-2 border-transparent group-hover:border-brand-secondary transition-colors" />
                                    {/* Simple Dropdown for demo */}
                                    <select 
                                        className="absolute inset-0 opacity-0 cursor-pointer"
                                        onChange={(e) => {
                                            const team = TEAM_LEADERBOARD.find(t => t.id === e.target.value);
                                            if (team) setSelectedOpponent(team);
                                        }}
                                        value={selectedOpponent?.id}
                                    >
                                        {TEAM_LEADERBOARD.filter(t => t.name !== myTeam.name).map(t => (
                                            <option key={t.id} value={t.id}>{t.name}</option>
                                        ))}
                                    </select>
                                    <span className="text-xs font-bold text-center text-slate-900 dark:text-white leading-tight flex items-center justify-center">
                                        {selectedOpponent?.name} <ChevronDown size={10} className="ml-1" />
                                    </span>
                                </div>
                            </div>
                        </div>

                        {/* Date & Time */}
                        <div className="grid grid-cols-2 gap-4">
                            <div>
                                <label className="text-slate-500 dark:text-slate-400 text-xs uppercase font-bold mb-2 block">Date</label>
                                <div className="relative">
                                    <Calendar className="absolute left-3 top-3 text-slate-400" size={16} />
                                    <input 
                                        type="date" 
                                        value={challengeDate}
                                        onChange={(e) => setChallengeDate(e.target.value)}
                                        className="w-full bg-slate-100 dark:bg-slate-800 border-none rounded-xl py-3 pl-10 pr-3 text-sm font-bold text-slate-900 dark:text-white focus:ring-2 focus:ring-brand-secondary outline-none"
                                    />
                                </div>
                            </div>
                            <div>
                                <label className="text-slate-500 dark:text-slate-400 text-xs uppercase font-bold mb-2 block">Time</label>
                                <div className="relative">
                                    <Clock className="absolute left-3 top-3 text-slate-400" size={16} />
                                    <input 
                                        type="time" 
                                        value={challengeTime}
                                        onChange={(e) => setChallengeTime(e.target.value)}
                                        className="w-full bg-slate-100 dark:bg-slate-800 border-none rounded-xl py-3 pl-10 pr-3 text-sm font-bold text-slate-900 dark:text-white focus:ring-2 focus:ring-brand-secondary outline-none"
                                    />
                                </div>
                            </div>
                        </div>

                         {/* Duration */}
                        <div>
                            <label className="text-slate-500 dark:text-slate-400 text-xs uppercase font-bold mb-2 block">Duration</label>
                            <div className="flex bg-slate-100 dark:bg-slate-800 p-1 rounded-xl">
                                {[1, 1.5, 2].map(d => (
                                    <button 
                                        key={d}
                                        onClick={() => setChallengeDuration(d)}
                                        className={`flex-1 py-2 rounded-lg text-sm font-bold transition-all ${
                                            challengeDuration === d 
                                            ? 'bg-white dark:bg-slate-700 text-slate-900 dark:text-white shadow-sm' 
                                            : 'text-slate-500 hover:text-slate-700 dark:hover:text-slate-300'
                                        }`}
                                    >
                                        {d}h
                                    </button>
                                ))}
                            </div>
                        </div>

                        {/* Venue Selection */}
                        <div>
                            <label className="text-slate-500 dark:text-slate-400 text-xs uppercase font-bold mb-2 flex justify-between">
                                <span>Proposed Venue</span>
                                <span className="text-brand-secondary">{selectedVenue?.name}</span>
                            </label>
                            <div className="flex overflow-x-auto space-x-3 pb-2 scrollbar-hide">
                                {TURFS.map(turf => (
                                    <div 
                                        key={turf.id} 
                                        onClick={() => setSelectedVenue(turf)}
                                        className={`min-w-[140px] rounded-xl overflow-hidden border transition-all cursor-pointer relative ${
                                            selectedVenue?.id === turf.id 
                                            ? 'border-brand-secondary ring-2 ring-brand-secondary/50' 
                                            : 'border-slate-200 dark:border-slate-700 opacity-70 hover:opacity-100'
                                        }`}
                                    >
                                        <div className="h-20 relative">
                                            <img src={turf.image} className="w-full h-full object-cover" />
                                            {selectedVenue?.id === turf.id && (
                                                <div className="absolute inset-0 bg-brand-secondary/20 flex items-center justify-center">
                                                    <div className="bg-brand-secondary rounded-full p-1">
                                                        <CheckCheck size={16} className="text-white" />
                                                    </div>
                                                </div>
                                            )}
                                        </div>
                                        <div className="p-2 bg-slate-50 dark:bg-slate-800">
                                            <p className="text-slate-900 dark:text-white text-xs font-bold truncate">{turf.name}</p>
                                            <p className="text-slate-500 text-[10px] truncate">{turf.location}</p>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        </div>

                        {/* Message (Optional) */}
                        <div>
                             <label className="text-slate-500 dark:text-slate-400 text-xs uppercase font-bold mb-2 block">Note (Optional)</label>
                             <textarea 
                                placeholder="Winner pays for drinks? 🍻"
                                className="w-full bg-slate-100 dark:bg-slate-800 border-none rounded-xl p-3 text-sm text-slate-900 dark:text-white focus:ring-2 focus:ring-brand-secondary outline-none resize-none h-20"
                             ></textarea>
                        </div>

                        <button 
                            onClick={() => {
                                setChallengeSent(true);
                                setTimeout(() => {
                                    setShowChallengeModal(false);
                                }, 2500);
                            }}
                            className="w-full py-4 bg-brand-secondary text-white font-bold rounded-xl shadow-lg hover:bg-emerald-600 flex items-center justify-center"
                        >
                            <Send size={18} className="mr-2" /> Send Challenge
                        </button>
                    </div>
                  </>
              )}
          </div>
      </div>
  );

  return (
    <Layout>
        {showChallengeModal && <ChallengeModal />}
        {showChat && <ChatModal />}

        <div className="p-5 pt-8 bg-slate-50 dark:bg-brand-dark min-h-screen">
