        >
          <Sparkles size={20} className="group-hover:rotate-12 transition-transform" />
        </button>
      )}

      {/* AI Chat Overlay */}
      {isChatOpen && <AIChat onClose={() => setIsChatOpen(false)} />}

      {!isOwner && (
        <div className="fixed bottom-0 left-0 right-0 h-20 bg-white dark:bg-slate-900 border-t border-slate-200 dark:border-slate-800 flex justify-around items-center z-50 px-2 pb-2 safe-area-bottom">
            <NavItem path="/home" icon={Home} label="Home" />
            <NavItem path="/teams" icon={Users} label="Teams" />

            {/* Center Button - Match AI */}
            <div className="relative -top-5">
              <button
                onClick={() => navigate('/live')}
                className={`w-16 h-16 rounded-full flex items-center justify-center shadow-lg transition-transform active:scale-95 border-4 border-slate-50 dark:border-brand-dark ${
                   isActive('/live') 
                   ? 'bg-brand-secondary text-white shadow-emerald-500/30' 
                   : 'bg-slate-800 text-slate-400 dark:bg-slate-700 hover:bg-slate-700'
                }`}
              >
                <Sparkles size={28} className={isActive('/live') ? 'animate-pulse' : ''} />
              </button>
              <span className={`absolute -bottom-4 left-1/2 transform -translate-x-1/2 text-[10px] font-bold whitespace-nowrap ${isActive('/live') ? 'text-brand-secondary' : 'text-slate-400'}`}>
                Match AI
              </span>
            </div>

            <NavItem path="/bookings" icon={Calendar} label="Bookings" />
            <NavItem path="/profile" icon={User} label="Profile" />
        </div>
      )}
    </div>
  );
};

