    useEffect(() => {
        const timeout = setTimeout(() => {
            setIsTyping(true);
            setTimeout(() => setIsTyping(false), 4000);
        }, 3000);
        return () => clearTimeout(timeout);
    }, []);

    const sendMessage = () => {
        if (!inputValue.trim()) return;
        const newMsg = {
            id: Date.now(),
            text: inputValue,
            sender: "You",
            avatar: "",
            time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
            isMe: true,
            read: false,
            replyTo: replyingTo ? { sender: replyingTo.sender, text: replyingTo.text } : null
        };
        setChatMessages([...chatMessages, newMsg]);
        setInputValue("");
        setReplyingTo(null);

        // Simulate read receipt
        setTimeout(() => {
             setChatMessages(prev => prev.map(m => m.id === newMsg.id ? {...m, read: true} : m));
        }, 2000);
    };

    return (
        <div className="fixed inset-0 z-50 bg-slate-50 dark:bg-brand-dark flex flex-col animate-slideUp">

            {/* Audio Call Overlay */}
            {activeCall && (
                <div className="absolute inset-0 z-[60] bg-slate-900 flex flex-col items-center justify-center text-white animate-fadeIn">
                    <div className="flex-1 flex flex-col items-center justify-center w-full">
