                                className={`p-5 rounded-full transition-all ${isMuted ? 'bg-white text-slate-900' : 'bg-slate-700 text-white hover:bg-slate-600'}`}
                            >
                                {isMuted ? <MicOff size={24} /> : <Mic size={24} />}
                            </button>

                            <button 
                                onClick={() => setActiveCall(false)}
                                className="p-6 bg-red-500 rounded-full text-white shadow-lg hover:bg-red-600 transform hover:scale-105 transition-all"
