                                <PhoneOff size={32} />
                            </button>

                            <button 
                                onClick={() => setIsSpeaker(!isSpeaker)}
                                className={`p-5 rounded-full transition-all ${isSpeaker ? 'bg-white text-slate-900' : 'bg-slate-700 text-white hover:bg-slate-600'}`}
