                    <button onClick={() => setShowChat(false)} className="mr-3 p-2 hover:bg-slate-100 dark:hover:bg-slate-700 rounded-full transition-colors">
                        <ArrowLeft size={20} className="text-slate-600 dark:text-slate-300" />
                    </button>
                    <div 
                        className="cursor-pointer group" 
                        onClick={() => setShowOnlineList(!showOnlineList)}
                    >
                        <h3 className="font-bold text-slate-900 dark:text-white text-lg leading-tight flex items-center">
                            {myTeam.name}
                            <ChevronDown size={14} className={`ml-1 transition-transform ${showOnlineList ? 'rotate-180' : ''}`} />
                        </h3>
                        <div className="flex items-center text-xs text-brand-secondary font-medium">
                            <span className="w-2 h-2 bg-brand-secondary rounded-full mr-1.5 animate-pulse"></span>
                            {activeMembers.length} Online
                        </div>
                    </div>
                </div>
                <div className="flex space-x-1 text-slate-500 dark:text-slate-400 relative">
                    <button 
                        onClick={() => setActiveCall(true)}
                        className="p-2 hover:bg-slate-100 dark:hover:bg-slate-700 rounded-full transition-colors text-brand-secondary"
                    >
                        <Phone size={20} />
                    </button>
                    <button 
                        onClick={() => setShowMenu(!showMenu)}
