                        <MoreVertical size={20} />
                    </button>

                    {/* Menu Dropdown */}
                    {showMenu && (
                        <div className="absolute top-full right-0 mt-2 w-48 bg-white dark:bg-slate-800 rounded-xl shadow-xl border border-slate-100 dark:border-slate-700 z-50 overflow-hidden animate-fadeIn">
                            <button className="w-full text-left px-4 py-3 hover:bg-slate-50 dark:hover:bg-slate-700 flex items-center text-sm text-slate-700 dark:text-slate-200">
                                <Info size={16} className="mr-2" /> Group Info
                            </button>
                            <button className="w-full text-left px-4 py-3 hover:bg-slate-50 dark:hover:bg-slate-700 flex items-center text-sm text-slate-700 dark:text-slate-200">
                                <Search size={16} className="mr-2" /> Search Chat
