                        </div>
                    )}
                </div>

                {/* Online Users Dropdown */}
                {showOnlineList && (
                    <div className="absolute top-full left-12 mt-2 bg-white dark:bg-slate-800 shadow-xl rounded-2xl p-3 border border-slate-100 dark:border-slate-700 w-56 animate-fadeIn z-50">
                        <h4 className="text-[10px] font-bold text-slate-400 mb-3 uppercase tracking-wider">Team Members</h4>
