                    <div className="flex justify-between items-center mb-6">
                        <h3 className="text-xl font-bold text-slate-900 dark:text-white">Challenge a Team</h3>
                        <button onClick={() => setShowChallengeModal(false)}><X className="text-slate-500 dark:text-slate-400" /></button>
                    </div>

                    <div className="space-y-6">
                        {/* Matchup Header */}
