                            <div className="flex flex-col items-center w-1/3">
                                <img src={myTeam.logo} className="w-12 h-12 rounded-xl mb-2 object-cover" />
                                <span className="text-xs font-bold text-center text-slate-900 dark:text-white leading-tight">{myTeam.name}</span>
                            </div>
                            <div className="flex flex-col items-center text-brand-secondary font-bold">
