                                <Swords size={24} />
                            </div>
                            <div className="flex flex-col items-center w-1/3">
                                {/* Opponent Selector Trigger */}
                                <div className="relative group cursor-pointer w-full flex flex-col items-center">
                                    <img src={selectedOpponent?.logo || ''} className="w-12 h-12 rounded-xl mb-2 object-cover border-2 border-transparent group-hover:border-brand-secondary transition-colors" />
                                    {/* Simple Dropdown for demo */}
                                    <select 
