import React, { useState } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { Calendar, Users, User, Home, Sparkles } from 'lucide-react';
import { AIChat } from './AIChat';

interface LayoutProps {
  children: React.ReactNode;
  isOwner?: boolean;
}

export const Layout: React.FC<LayoutProps> = ({ children, isOwner = false }) => {
  const navigate = useNavigate();
  const location = useLocation();
  const [isChatOpen, setIsChatOpen] = useState(false);

  const isActive = (path: string) => location.pathname === path;

  // Standard Nav Item
  const NavItem = ({ path, icon: Icon, label }: { path: string, icon: any, label: string }) => (
    <button
      onClick={() => navigate(path)}
      className={`flex flex-col items-center justify-center w-full h-full py-2 transition-colors duration-300 group ${
        isActive(path) 
          ? 'text-brand-secondary' 
          : 'text-slate-400 hover:text-slate-600 dark:hover:text-slate-200'
      }`}
    >
      <Icon size={24} strokeWidth={isActive(path) ? 2.5 : 2} className={`mb-1 transition-transform group-active:scale-95 ${isActive(path) ? 'scale-110' : ''}`} />
      <span className="text-[10px] font-medium">{label}</span>
    </button>
  );

  return (
    <div className="flex flex-col h-screen bg-slate-50 dark:bg-brand-dark overflow-hidden transition-colors duration-300 font-sans relative">
      <main className="flex-1 overflow-y-auto pb-20 scrollbar-hide">
        {children}
      </main>

      {/* AI Assistant FAB (Only show if not on Match Center to avoid clutter, optional logic) */}
      {!isOwner && !isChatOpen && location.pathname !== '/live' && (
        <button
          onClick={() => setIsChatOpen(true)}
          className="fixed bottom-24 right-5 z-40 w-12 h-12 bg-gradient-to-r from-brand-primary to-violet-600 rounded-full shadow-lg shadow-violet-500/40 flex items-center justify-center text-white hover:scale-105 active:scale-95 transition-transform group"
        >
          <Sparkles size={20} className="group-hover:rotate-12 transition-transform" />
        </button>
      )}

      {/* AI Chat Overlay */}
      {isChatOpen && <AIChat onClose={() => setIsChatOpen(false)} />}

      {!isOwner && (
        <div className="fixed bottom-0 left-0 right-0 h-20 bg-white dark:bg-slate-900 border-t border-slate-200 dark:border-slate-800 flex justify-around items-center z-50 px-2 pb-2 safe-area-bottom">
            <NavItem path="/home" icon={Home} label="Home" />
            <NavItem path="/teams" icon={Users} label="Teams" />

            {/* Center Button - Match Center */}
            <div className="relative -top-5">
              <button
                onClick={() => navigate('/live')}
                className={`w-16 h-16 rounded-full flex items-center justify-center shadow-lg transition-transform active:scale-95 border-4 border-slate-50 dark:border-brand-dark ${
                   isActive('/live') 
                   ? 'bg-brand-secondary text-white shadow-emerald-500/30' 
                   : 'bg-slate-800 text-slate-400 dark:bg-slate-700 hover:bg-slate-700'
                }`}
              >
                <Sparkles size={28} className={isActive('/live') ? 'animate-pulse' : ''} />
              </button>
              <span className={`absolute -bottom-4 left-1/2 transform -translate-x-1/2 text-[10px] font-bold whitespace-nowrap ${isActive('/live') ? 'text-brand-secondary' : 'text-slate-400'}`}>
                Match Center
              </span>
            </div>

            <NavItem path="/bookings" icon={Calendar} label="Bookings" />
            <NavItem path="/profile" icon={User} label="Profile" />
        </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { Layout } from '../components/Layout';
import { GoogleGenAI } from "@google/genai";
import { MY_TEAMS, TEAM_LEADERBOARD } from '../constants';
import { Sparkles, Zap, MapPin, Trophy, TrendingUp, TrendingDown, Swords, ShieldAlert, Loader2, Info, BrainCircuit, User, Star, Wallet, CheckCircle } from 'lucide-react';

interface SuggestedMatch {
  id: string;
  opponent: typeof TEAM_LEADERBOARD[0];
  matchScore: number; // 0-100 compatibility
  distance: string;
  winRate: number;
  lossRate: number;
  reason?: string;
}

interface SuggestedPlayer {
    id: string;
    name: string;
    role: string;
    rating: number; // 0-5
    reviews: number;
    distance: string;
    fee: number;
    avatar: string;
    matchFit: number; // 0-100
}

const MOCK_PLAYERS: SuggestedPlayer[] = [
    { id: 'p1', name: 'David O.', role: 'Striker', rating: 4.9, reviews: 42, distance: '0.8 km', fee: 10000, avatar: 'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?w=100&h=100&fit=crop', matchFit: 95 },
    { id: 'p2', name: 'Sarah K.', role: 'Midfielder', rating: 4.7, reviews: 28, distance: '1.2 km', fee: 10000, avatar: 'https://images.unsplash.com/photo-1438761681033-6461ffad8d80?w=100&h=100&fit=crop', matchFit: 88 },
    { id: 'p3', name: 'Musa B.', role: 'Defender', rating: 4.5, reviews: 15, distance: '2.5 km', fee: 8000, avatar: 'https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?w=100&h=100&fit=crop', matchFit: 82 },
    { id: 'p4', name: 'John D.', role: 'Goalkeeper', rating: 4.8, reviews: 56, distance: '3.0 km', fee: 0, avatar: 'https://images.unsplash.com/photo-1599566150163-29194dcaad36?w=100&h=100&fit=crop', matchFit: 92 },
];

export const MatchCenter: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'teams' | 'players'>('teams');
  const [isScanning, setIsScanning] = useState(false);

  // Team State
  const [matches, setMatches] = useState<SuggestedMatch[]>([]);

  // Player State
  const [players, setPlayers] = useState<SuggestedPlayer[]>([]);

  const [aiAnalysis, setAiAnalysis] = useState<string>("");

  const myTeam = MY_TEAMS[0];

  // Helper to calculate win/loss rates
  const getStats = (wins: number, totalGames: number = 20) => {
    const winRate = Math.round((wins / totalGames) * 100);
    const lossRate = Math.round(((totalGames - wins) / totalGames) * 100); 
    return { winRate, lossRate };
  };

  const handleScan = async () => {
    setIsScanning(true);
    setMatches([]);
    setPlayers([]);
    setAiAnalysis("");

    // Simulate Network/Processing Delay
    setTimeout(async () => {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      if (activeTab === 'teams') {
          // --- TEAM MATCHING LOGIC ---
          const myStats = getStats(myTeam.wins, 24);

          const suggestions: SuggestedMatch[] = TEAM_LEADERBOARD
            .filter(t => t.name !== myTeam.name)
            .map(opponent => {
              const oppStats = getStats(opponent.wins, 24); 
              const skillDiff = Math.abs(myStats.winRate - oppStats.winRate);
              const skillScore = Math.max(0, 100 - (skillDiff * 2)); 
              const distanceVal = Math.floor(Math.random() * 15) + 1; 
              const distanceScore = Math.max(0, 100 - (distanceVal * 5));
              const totalScore = Math.round((skillScore * 0.7) + (distanceScore * 0.3));

              return {
                id: opponent.id,
                opponent,
                matchScore: totalScore,
                distance: `${distanceVal} km`,
                winRate: oppStats.winRate,
                lossRate: oppStats.lossRate
              };
            })
            .sort((a, b) => b.matchScore - a.matchScore)
            .slice(0, 3);

          setMatches(suggestions);

          try {
            if (suggestions.length > 0) {
                const topMatch = suggestions[0];
                const prompt = `
                    Act as an elite football match analyst. Provide a strategic reasoning for why a match between "${myTeam.name}" and "${topMatch.opponent.name}" is the perfect matchup.
                    Data:
                    - My Team Win Rate: ${myStats.winRate}%
                    - Opponent Win Rate: ${topMatch.winRate}%
                    - Proximity: ${topMatch.distance}
                    - Compatibility Score: ${topMatch.matchScore}%

                    Output: 2 concise sentences explaining the "Reasoning". Reference the win rates and proximity. Use emojis.
                `;
                const response = await ai.models.generateContent({
                    model: 'gemini-3-flash-preview',
                    contents: prompt
                });
                setAiAnalysis(response.text || "Match data analyzed. Ready for kickoff!");
            }
          } catch (error) {
            setAiAnalysis("Top rival identified based on skill level and location.");
          }

      } else {
          // --- PLAYER SEARCH LOGIC ---
          // Filter randomly for demo
          const suggestions = MOCK_PLAYERS.sort((a, b) => b.rating - a.rating); 
          setPlayers(suggestions);

          try {
            if (suggestions.length > 0) {
                const topPlayer = suggestions[0];
                const prompt = `
                    Act as a football scout. Analyze this player profile:
                    - Name: ${topPlayer.name}
                    - Role: ${topPlayer.role}
                    - Rating: ${topPlayer.rating} / 5 stars (${topPlayer.reviews} reviews)
                    - Distance: ${topPlayer.distance}

                    Write a short recommendation (2 sentences) on why they are a great addition to the squad right now. Focus on their high rating/reliability. Mention split payment is available.
                `;
                const response = await ai.models.generateContent({
                    model: 'gemini-3-flash-preview',
                    contents: prompt
                });
                setAiAnalysis(response.text || "Player scanned. High rating confirmed.");
            }
          } catch (error) {
             setAiAnalysis("Top rated player found nearby. Highly recommended based on community reviews.");
          }
      }

      setIsScanning(false);
    }, 2000);
  };

  return (
    <Layout>
        <div className="p-5 pt-8 bg-brand-dark min-h-screen text-white pb-24">
            {/* Header */}
            <div className="flex items-center justify-between mb-6">
                <div>
                    <h1 className="text-2xl font-bold flex items-center">
                        <Sparkles className="mr-2 text-brand-secondary" /> Match Center
                    </h1>
                    <p className="text-slate-400 text-xs mt-1">AI-powered matchmaking</p>
                </div>
                <div className="bg-slate-800 p-2 rounded-xl border border-slate-700">
                    <img src={myTeam.logo} className="w-8 h-8 rounded-lg object-cover" />
                </div>
            </div>

            {/* Toggle Switch */}
            <div className="flex bg-slate-800 p-1 rounded-xl mb-6 border border-slate-700">
                <button 
                    onClick={() => { setActiveTab('teams'); setMatches([]); setPlayers([]); setAiAnalysis(""); }}
                    className={`flex-1 py-3 rounded-lg text-sm font-bold flex items-center justify-center transition-all ${activeTab === 'teams' ? 'bg-slate-700 text-white shadow-sm' : 'text-slate-500 hover:text-slate-300'}`}
                >
                    <Swords size={16} className="mr-2" /> Find Teams
                </button>
                <button 
                    onClick={() => { setActiveTab('players'); setMatches([]); setPlayers([]); setAiAnalysis(""); }}
                    className={`flex-1 py-3 rounded-lg text-sm font-bold flex items-center justify-center transition-all ${activeTab === 'players' ? 'bg-slate-700 text-white shadow-sm' : 'text-slate-500 hover:text-slate-300'}`}
                >
                    <User size={16} className="mr-2" /> Find Players
                </button>
            </div>

            {/* Radar / Scan UI */}
            <div className="relative mb-8">
                <div className="bg-gradient-to-b from-slate-800 to-slate-900 rounded-3xl p-8 border border-slate-700 shadow-xl overflow-hidden text-center relative min-h-[250px] flex flex-col justify-center">

                    {/* Background Grid Animation */}
                    <div className="absolute inset-0 opacity-10" 
                         style={{ backgroundImage: 'radial-gradient(circle, #8b5cf6 1px, transparent 1px)', backgroundSize: '20px 20px' }}>
                    </div>

                    {!isScanning && matches.length === 0 && players.length === 0 && (
                        <div className="relative z-10 animate-fadeIn">
                            <div className="w-24 h-24 bg-brand-secondary/10 rounded-full flex items-center justify-center mx-auto mb-4 border-2 border-brand-secondary/30 relative">
                                {activeTab === 'teams' ? <Swords size={40} className="text-brand-secondary" /> : <User size={40} className="text-brand-secondary" />}
                                <div className="absolute inset-0 rounded-full border border-brand-secondary/50 animate-ping"></div>
                            </div>
                            <h2 className="text-xl font-bold mb-2">{activeTab === 'teams' ? 'Challenge a Rival' : 'Recruit a Player'}</h2>
                            <p className="text-slate-400 text-sm mb-6 max-w-xs mx-auto">
                                {activeTab === 'teams' 
                                    ? `Our AI analyzes win rates and location to find the perfect rival for ${myTeam.name}.`
                                    : "Scan for high-rated free agents nearby to complete your squad. Split payments available."}
                            </p>
                            <button 
                                onClick={handleScan}
                                className="bg-brand-secondary hover:bg-emerald-500 text-white font-bold py-4 px-8 rounded-xl shadow-lg shadow-emerald-500/20 transition-transform active:scale-95 flex items-center mx-auto"
                            >
                                <Zap size={20} className="mr-2 fill-current" /> {activeTab === 'teams' ? 'Scan Teams' : 'Scan Players'}
                            </button>
                        </div>
                    )}

                    {isScanning && (
                        <div className="relative z-10 flex flex-col items-center">
                            <Loader2 size={48} className="text-brand-secondary animate-spin mb-4" />
                            <h3 className="text-lg font-bold animate-pulse">
                                {activeTab === 'teams' ? 'Scanning Local Leagues...' : 'Scouting Nearby Players...'}
                            </h3>
                            <p className="text-slate-400 text-xs mt-2">Comparing stats & reviews</p>
                        </div>
                    )}

                    {/* AI Analysis Result */}
                    {!isScanning && (matches.length > 0 || players.length > 0) && (
                        <div className="relative z-10 text-left animate-fadeIn mt-2">
                            <div className="flex items-start space-x-3 bg-brand-primary/10 border border-brand-primary/20 p-4 rounded-xl">
                                <Sparkles className="text-brand-primary flex-shrink-0 mt-0.5" size={18} />
                                <div>
                                    <h3 className="text-brand-primary font-bold text-xs uppercase mb-1 flex items-center">
                                        {activeTab === 'teams' ? 'Match Reasoning' : 'Scouting Report'} <BrainCircuit size={12} className="ml-1" />
                                    </h3>
                                    <p className="text-slate-200 text-sm font-medium leading-relaxed">
                                        {aiAnalysis || "Analyzing..."}
                                    </p>
                                </div>
                            </div>
                        </div>
                    )}
                </div>
            </div>

            {/* Results List */}
            {!isScanning && (matches.length > 0 || players.length > 0) && (
                <div className="space-y-6 animate-slideUp">
                    <div className="flex justify-between items-end px-1">
                        <h3 className="font-bold text-lg text-white">
                            {activeTab === 'teams' ? 'Proposed Matches' : 'Available Players'}
                        </h3>
                        <span className="text-xs text-brand-secondary font-bold bg-brand-secondary/10 px-2 py-1 rounded-lg">
                            {activeTab === 'teams' ? matches.length : players.length} Found
                        </span>
                    </div>

                    {/* TEAM CARDS */}
                    {activeTab === 'teams' && matches.map((match, index) => (
                        <div key={match.id} className="bg-slate-800 rounded-3xl p-5 border border-slate-700 relative overflow-hidden group">
                            <div className="absolute top-0 right-0 bg-slate-700 pl-4 pb-2 pt-2 pr-4 rounded-bl-3xl border-b border-l border-slate-600">
                                <span className={`text-sm font-bold ${index === 0 ? 'text-brand-secondary' : 'text-slate-300'}`}>
                                    {match.matchScore}% Match
                                </span>
                            </div>

                            <div className="flex items-center mb-6">
                                <img src={match.opponent.logo} className="w-16 h-16 rounded-xl object-cover border-2 border-slate-600 mr-4" />
                                <div>
                                    <h4 className="text-xl font-bold text-white mb-1">{match.opponent.name}</h4>
                                    <div className="flex items-center text-xs text-slate-400 font-medium">
                                        <MapPin size={12} className="mr-1 text-slate-500" />
                                        {match.distance} away
                                    </div>
                                </div>
                            </div>

                            <div className="grid grid-cols-2 gap-4 mb-6">
                                <div>
                                    <div className="flex justify-between text-xs mb-1.5">
                                        <span className="text-emerald-400 font-bold flex items-center"><TrendingUp size={12} className="mr-1"/> Win Rate</span>
                                        <span className="text-white font-bold">{match.winRate}%</span>
                                    </div>
                                    <div className="h-2 bg-slate-900 rounded-full overflow-hidden">
                                        <div style={{ width: `${match.winRate}%` }} className="h-full bg-emerald-500 rounded-full"></div>
                                    </div>
                                </div>
                                <div>
                                    <div className="flex justify-between text-xs mb-1.5">
                                        <span className="text-red-400 font-bold flex items-center"><TrendingDown size={12} className="mr-1"/> Loss Rate</span>
                                        <span className="text-white font-bold">{match.lossRate}%</span>
                                    </div>
                                    <div className="h-2 bg-slate-900 rounded-full overflow-hidden">
                                        <div style={{ width: `${match.lossRate}%` }} className="h-full bg-red-500 rounded-full"></div>
                                    </div>
                                </div>
                            </div>

                            <div className="flex gap-3">
                                <button className="flex-1 bg-white text-slate-900 font-bold py-3 rounded-xl text-sm hover:bg-slate-200 transition-colors">
                                    View Profile
                                </button>
                                <button className="flex-1 bg-brand-secondary text-white font-bold py-3 rounded-xl text-sm shadow-lg shadow-emerald-900/20 hover:bg-emerald-600 transition-colors flex items-center justify-center">
                                    <Swords size={16} className="mr-2" /> Challenge
                                </button>
                            </div>
                        </div>
                    ))}

                    {/* PLAYER CARDS */}
                    {activeTab === 'players' && players.map((player, index) => (
                        <div key={player.id} className="bg-slate-800 rounded-3xl p-5 border border-slate-700 relative overflow-hidden group">
                             {/* Ranking Badge */}
