export const MatchCenter: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'teams' | 'pickup'>('teams');
  const [isScanning, setIsScanning] = useState(false);

  // Team State
  const [matches, setMatches] = useState<SuggestedMatch[]>([]);

  // Pickup State
  const [generatedTeams, setGeneratedTeams] = useState<{teamA: Player[], teamB: Player[]} | null>(null);

  const [aiAnalysis, setAiAnalysis] = useState<string>("");

  const myTeam = MY_TEAMS[0];

  // Helper to calculate win/loss rates
  const getStats = (wins: number, totalGames: number = 20) => {
    const winRate = Math.round((wins / totalGames) * 100);
    const lossRate = Math.round(((totalGames - wins) / totalGames) * 100); 
    return { winRate, lossRate };
  };

  const handleScan = async () => {
    setIsScanning(true);
    setMatches([]);
    setGeneratedTeams(null);
    setAiAnalysis("");

    // Simulate Network/Processing Delay
    setTimeout(async () => {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      if (activeTab === 'teams') {
          // --- EXISTING TEAM MATCHING LOGIC ---
          const myStats = getStats(myTeam.wins, 24);

          const suggestions: SuggestedMatch[] = TEAM_LEADERBOARD
            .filter(t => t.name !== myTeam.name)
            .map(opponent => {
              const oppStats = getStats(opponent.wins, 24); 
              const skillDiff = Math.abs(myStats.winRate - oppStats.winRate);
              const skillScore = Math.max(0, 100 - (skillDiff * 2)); 
              const distanceVal = Math.floor(Math.random() * 15) + 1; 
              const distanceScore = Math.max(0, 100 - (distanceVal * 5));
              const totalScore = Math.round((skillScore * 0.7) + (distanceScore * 0.3));

              return {
                id: opponent.id,
                opponent,
                matchScore: totalScore,
                distance: `${distanceVal} km`,
                winRate: oppStats.winRate,
                lossRate: oppStats.lossRate
              };
            })
            .sort((a, b) => b.matchScore - a.matchScore)
            .slice(0, 3);

          setMatches(suggestions);

          try {
            if (suggestions.length > 0) {
                const topMatch = suggestions[0];
                const prompt = `
                    Act as an elite football match analyst. Provide a strategic reasoning for why a match between "${myTeam.name}" and "${topMatch.opponent.name}" is the perfect matchup.
                    Data:
                    - My Team Win Rate: ${myStats.winRate}%
                    - Opponent Win Rate: ${topMatch.winRate}%
                    - Proximity: ${topMatch.distance}

                    Output: 2 concise sentences explaining the "Reasoning". Reference the win rates. Use emojis.
                `;
                const response = await ai.models.generateContent({
                    model: 'gemini-3-flash-preview',
                    contents: prompt
                });
                setAiAnalysis(response.text || "Match data analyzed. Ready for kickoff!");
            }
          } catch (error) {
            setAiAnalysis("Top rival identified based on skill level and location.");
          }

      } else {
          // --- PICKUP MATCH GENERATOR (SPLIT TEAMS) ---

          // 1. Sort by rating descending
          const sortedPlayers = [...WAITING_PLAYERS].sort((a, b) => b.rating - a.rating);

          // 2. Snake Draft Logic to Balance
          const teamA: Player[] = [];
          const teamB: Player[] = [];

          sortedPlayers.forEach((player, index) => {
              // Pattern: A, B, B, A, A, B...
              if (index % 4 === 0 || index % 4 === 3) {
                  teamA.push(player);
              } else {
                  teamB.push(player);
              }
          });

          setGeneratedTeams({ teamA, teamB });

          // 3. AI Analysis of the Split
          try {
            const avgA = (teamA.reduce((acc, p) => acc + p.rating, 0) / teamA.length).toFixed(1);
            const avgB = (teamB.reduce((acc, p) => acc + p.rating, 0) / teamB.length).toFixed(1);

            const prompt = `
                Act as a football coach organizing a pickup game.
                I have split ${sortedPlayers.length} players into two teams.
                Team A Average Rating: ${avgA} / 5
                Team B Average Rating: ${avgB} / 5

                Key Players Team A: ${teamA[0].name} (${teamA[0].role})
                Key Players Team B: ${teamB[0].name} (${teamB[0].role})

                Write a 2-sentence "Match Preview" hyping up this balanced game. Mention the clash between the key players. Mention the split-cost.
            `;
            const response = await ai.models.generateContent({
                model: 'gemini-3-flash-preview',
                contents: prompt
            });
            setAiAnalysis(response.text || "Teams balanced based on player ratings. Game on!");
          } catch (error) {
             setAiAnalysis("Squads generated based on performance data. Balanced & competitive.");
          }
      }

      setIsScanning(false);
    }, 2000);
  };

  const calculateTotalRating = (players: Player[]) => {
      const avg = players.reduce((acc, p) => acc + p.rating, 0) / players.length;
      return avg.toFixed(1);
  };

  return (
    <Layout>
        <div className="p-5 pt-8 bg-brand-dark min-h-screen text-white pb-24">
            {/* Header */}
            <div className="flex items-center justify-between mb-6">
                <div>
                    <h1 className="text-2xl font-bold flex items-center">
                        <Sparkles className="mr-2 text-brand-secondary" /> Match Center
                    </h1>
                    <p className="text-slate-400 text-xs mt-1">AI-powered matchmaking</p>
                </div>
                <div className="bg-slate-800 p-2 rounded-xl border border-slate-700">
                    <img src={myTeam.logo} className="w-8 h-8 rounded-lg object-cover" />
                </div>
            </div>

            {/* Toggle Switch */}
            <div className="flex bg-slate-800 p-1 rounded-xl mb-6 border border-slate-700">
                <button 
                    onClick={() => { setActiveTab('teams'); setMatches([]); setGeneratedTeams(null); setAiAnalysis(""); }}
                    className={`flex-1 py-3 rounded-lg text-sm font-bold flex items-center justify-center transition-all ${activeTab === 'teams' ? 'bg-slate-700 text-white shadow-sm' : 'text-slate-500 hover:text-slate-300'}`}
                >
                    <Swords size={16} className="mr-2" /> Find Teams
                </button>
                <button 
                    onClick={() => { setActiveTab('pickup'); setMatches([]); setGeneratedTeams(null); setAiAnalysis(""); }}
                    className={`flex-1 py-3 rounded-lg text-sm font-bold flex items-center justify-center transition-all ${activeTab === 'pickup' ? 'bg-slate-700 text-white shadow-sm' : 'text-slate-500 hover:text-slate-300'}`}
                >
                    <Shuffle size={16} className="mr-2" /> Pickup Match
                </button>
            </div>

            {/* Radar / Scan UI */}
            <div className="relative mb-8">
                <div className="bg-gradient-to-b from-slate-800 to-slate-900 rounded-3xl p-8 border border-slate-700 shadow-xl overflow-hidden text-center relative min-h-[220px] flex flex-col justify-center">

                    {/* Background Grid Animation */}
                    <div className="absolute inset-0 opacity-10" 
                         style={{ backgroundImage: 'radial-gradient(circle, #8b5cf6 1px, transparent 1px)', backgroundSize: '20px 20px' }}>
                    </div>

                    {!isScanning && matches.length === 0 && !generatedTeams && (
                        <div className="relative z-10 animate-fadeIn">
                            <div className="w-20 h-20 bg-brand-secondary/10 rounded-full flex items-center justify-center mx-auto mb-4 border-2 border-brand-secondary/30 relative">
                                {activeTab === 'teams' ? <Swords size={32} className="text-brand-secondary" /> : <Users size={32} className="text-brand-secondary" />}
                                <div className="absolute inset-0 rounded-full border border-brand-secondary/50 animate-ping"></div>
                            </div>
                            <h2 className="text-xl font-bold mb-2">{activeTab === 'teams' ? 'Challenge a Rival' : 'Lobby: 10 Players Waiting'}</h2>
                            <p className="text-slate-400 text-sm mb-6 max-w-xs mx-auto">
                                {activeTab === 'teams' 
                                    ? `Our AI analyzes win rates and location to find the perfect rival for ${myTeam.name}.`
                                    : "Auto-generate two balanced teams from free agents nearby using AI rating analysis."}
                            </p>
                            <button 
                                onClick={handleScan}
                                className="bg-brand-secondary hover:bg-emerald-500 text-white font-bold py-4 px-8 rounded-xl shadow-lg shadow-emerald-500/20 transition-transform active:scale-95 flex items-center mx-auto"
                            >
                                <Zap size={20} className="mr-2 fill-current" /> {activeTab === 'teams' ? 'Scan Teams' : 'Auto-Balance Teams'}
                            </button>
                        </div>
                    )}

                    {isScanning && (
                        <div className="relative z-10 flex flex-col items-center">
                            <Loader2 size={48} className="text-brand-secondary animate-spin mb-4" />
                            <h3 className="text-lg font-bold animate-pulse">
                                {activeTab === 'teams' ? 'Scanning Local Leagues...' : 'Balancing Squads...'}
                            </h3>
                            <p className="text-slate-400 text-xs mt-2">Analyzing player stats & reviews</p>
                        </div>
                    )}

                    {/* AI Analysis Result */}
                    {!isScanning && (matches.length > 0 || generatedTeams) && (
                        <div className="relative z-10 text-left animate-fadeIn mt-2">
                            <div className="flex items-start space-x-3 bg-brand-primary/10 border border-brand-primary/20 p-4 rounded-xl">
                                <Sparkles className="text-brand-primary flex-shrink-0 mt-0.5" size={18} />
                                <div>
                                    <h3 className="text-brand-primary font-bold text-xs uppercase mb-1 flex items-center">
                                        {activeTab === 'teams' ? 'Match Reasoning' : 'AI Match Preview'} <BrainCircuit size={12} className="ml-1" />
                                    </h3>
                                    <p className="text-slate-200 text-sm font-medium leading-relaxed">
                                        {aiAnalysis || "Analyzing..."}
                                    </p>
                                </div>
                            </div>
                        </div>
                    )}
                </div>
            </div>

            {/* Results List */}
            {!isScanning && (matches.length > 0 || generatedTeams) && (
                <div className="space-y-6 animate-slideUp">

                    {/* TEAM MATCHES LIST */}
                    {activeTab === 'teams' && matches.map((match, index) => (
                        <div key={match.id} className="bg-slate-800 rounded-3xl p-5 border border-slate-700 relative overflow-hidden group">
                            <div className="absolute top-0 right-0 bg-slate-700 pl-4 pb-2 pt-2 pr-4 rounded-bl-3xl border-b border-l border-slate-600">
                                <span className={`text-sm font-bold ${index === 0 ? 'text-brand-secondary' : 'text-slate-300'}`}>
                                    {match.matchScore}% Match
                                </span>
                            </div>

                            <div className="flex items-center mb-6">
                                <img src={match.opponent.logo} className="w-16 h-16 rounded-xl object-cover border-2 border-slate-600 mr-4" />
                                <div>
                                    <h4 className="text-xl font-bold text-white mb-1">{match.opponent.name}</h4>
                                    <div className="flex items-center text-xs text-slate-400 font-medium">
                                        <MapPin size={12} className="mr-1 text-slate-500" />
                                        {match.distance} away
                                    </div>
                                </div>
                            </div>

                            <div className="grid grid-cols-2 gap-4 mb-6">
                                <div>
                                    <div className="flex justify-between text-xs mb-1.5">
                                        <span className="text-emerald-400 font-bold flex items-center"><TrendingUp size={12} className="mr-1"/> Win Rate</span>
                                        <span className="text-white font-bold">{match.winRate}%</span>
                                    </div>
                                    <div className="h-2 bg-slate-900 rounded-full overflow-hidden">
                                        <div style={{ width: `${match.winRate}%` }} className="h-full bg-emerald-500 rounded-full"></div>
                                    </div>
                                </div>
                                <div>
                                    <div className="flex justify-between text-xs mb-1.5">
                                        <span className="text-red-400 font-bold flex items-center"><TrendingDown size={12} className="mr-1"/> Loss Rate</span>
                                        <span className="text-white font-bold">{match.lossRate}%</span>
                                    </div>
                                    <div className="h-2 bg-slate-900 rounded-full overflow-hidden">
                                        <div style={{ width: `${match.lossRate}%` }} className="h-full bg-red-500 rounded-full"></div>
                                    </div>
                                </div>
                            </div>

                            <div className="flex gap-3">
                                <button className="flex-1 bg-white text-slate-900 font-bold py-3 rounded-xl text-sm hover:bg-slate-200 transition-colors">
                                    View Profile
                                </button>
                                <button className="flex-1 bg-brand-secondary text-white font-bold py-3 rounded-xl text-sm shadow-lg shadow-emerald-900/20 hover:bg-emerald-600 transition-colors flex items-center justify-center">
                                    <Swords size={16} className="mr-2" /> Challenge
                                </button>
                            </div>
                        </div>
                    ))}

                    {/* PICKUP TEAMS GENERATOR UI */}
                    {activeTab === 'pickup' && generatedTeams && (
                        <div className="animate-slideUp">
                             {/* Versus Header */}
                             <div className="flex items-center justify-center mb-6">
                                 <div className="bg-orange-500/20 text-orange-500 font-black text-xl px-4 py-2 rounded-xl border border-orange-500/30 tracking-widest">
                                     TEAM A <span className="text-white mx-2 font-light">VS</span> TEAM B
                                 </div>
                             </div>

                             <div className="grid grid-cols-2 gap-4">
                                 {/* TEAM A */}
                                 <div className="bg-slate-800 rounded-3xl p-4 border border-slate-700">
                                     <div className="flex justify-between items-center mb-4 border-b border-slate-700 pb-3">
                                         <h3 className="font-bold text-white">Bibs (A)</h3>
                                         <div className="flex items-center text-yellow-400 text-xs font-bold">
                                             <Star size={10} className="fill-current mr-1" />
                                             {calculateTotalRating(generatedTeams.teamA)}
                                         </div>
                                     </div>
                                     <div className="space-y-3">
                                         {generatedTeams.teamA.map((p) => (
                                             <div key={p.id} className="flex items-center">
                                                 <img src={p.avatar} className="w-8 h-8 rounded-full border border-slate-600 mr-2" />
                                                 <div className="overflow-hidden">
                                                     <p className="text-xs font-bold text-white truncate">{p.name}</p>
                                                     <p className="text-[10px] text-slate-400 truncate">{p.role} • <span className="text-yellow-500">{p.rating}</span></p>
                                                 </div>
                                             </div>
                                         ))}
                                     </div>
                                 </div>

                                 {/* TEAM B */}
                                 <div className="bg-slate-800 rounded-3xl p-4 border border-slate-700">
                                     <div className="flex justify-between items-center mb-4 border-b border-slate-700 pb-3">
                                         <h3 className="font-bold text-white">Non-Bibs (B)</h3>
                                         <div className="flex items-center text-yellow-400 text-xs font-bold">
                                             <Star size={10} className="fill-current mr-1" />
                                             {calculateTotalRating(generatedTeams.teamB)}
                                         </div>
                                     </div>
                                     <div className="space-y-3">
                                         {generatedTeams.teamB.map((p) => (
                                             <div key={p.id} className="flex items-center">
                                                 <img src={p.avatar} className="w-8 h-8 rounded-full border border-slate-600 mr-2" />
                                                 <div className="overflow-hidden">
                                                     <p className="text-xs font-bold text-white truncate">{p.name}</p>
                                                     <p className="text-[10px] text-slate-400 truncate">{p.role} • <span className="text-yellow-500">{p.rating}</span></p>
                                                 </div>
                                             </div>
                                         ))}
                                     </div>
                                 </div>
                             </div>

                             {/* Payment Info */}
                             <div className="mt-6 bg-slate-900 rounded-xl p-4 flex justify-between items-center border border-slate-800">
                                 <div className="flex items-center">
                                     <Wallet className="text-brand-secondary mr-3" size={24} />
                                     <div>
                                         <p className="text-white font-bold text-sm">Split Payment Active</p>
                                         <p className="text-slate-500 text-xs">Total: UGX 100,000 (10k / player)</p>
                                     </div>
                                 </div>
                                 <button className="bg-white text-slate-900 px-4 py-2 rounded-lg text-xs font-bold">
                                     Edit
                                 </button>
                             </div>

                             <button className="w-full mt-4 bg-brand-secondary text-white font-bold py-4 rounded-xl shadow-lg shadow-emerald-500/20 hover:bg-emerald-600 flex items-center justify-center">
                                 Book Venue & Invite All <ArrowRight size={18} className="ml-2" />
                             </button>

                             <button 
                                onClick={handleScan}
                                className="w-full mt-3 py-3 text-slate-500 font-bold text-xs hover:text-white"
                             >
                                 Reshuffle Teams
                             </button>
                        </div>
                    )}
                </div>
            )}
        </div>
    </Layout>
  );
};

