    { id: 'p1', name: 'David O.', role: 'Striker', rating: 4.9, reviews: 42, avatar: 'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?w=100&h=100&fit=crop' },
    { id: 'p2', name: 'Sarah K.', role: 'Midfielder', rating: 4.7, reviews: 28, avatar: 'https://images.unsplash.com/photo-1438761681033-6461ffad8d80?w=100&h=100&fit=crop' },
    { id: 'p3', name: 'Musa B.', role: 'Defender', rating: 4.5, reviews: 15, avatar: 'https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?w=100&h=100&fit=crop' },
    { id: 'p4', name: 'John D.', role: 'GK', rating: 4.8, reviews: 56, avatar: 'https://images.unsplash.com/photo-1599566150163-29194dcaad36?w=100&h=100&fit=crop' },
    { id: 'p5', name: 'Alex R.', role: 'Winger', rating: 4.2, reviews: 12, avatar: 'https://images.unsplash.com/photo-1570295999919-56ceb5ecca61?w=100&h=100&fit=crop' },
    { id: 'p6', name: 'Chris P.', role: 'Defender', rating: 4.3, reviews: 20, avatar: 'https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?w=100&h=100&fit=crop' },
    { id: 'p7', name: 'Sam M.', role: 'Midfielder', rating: 4.6, reviews: 34, avatar: 'https://images.unsplash.com/photo-1527980965255-d3b416303d12?w=100&h=100&fit=crop' },
    { id: 'p8', name: 'Lisa T.', role: 'Striker', rating: 4.4, reviews: 18, avatar: 'https://images.unsplash.com/photo-1544005313-94ddf0286df2?w=100&h=100&fit=crop' },
    { id: 'p9', name: 'Mike L.', role: 'Defender', rating: 4.1, reviews: 9, avatar: 'https://images.unsplash.com/photo-1599566150163-29194dcaad36?w=100&h=100&fit=crop' },
    { id: 'p10', name: 'You', role: 'Midfielder', rating: 4.5, reviews: 0, avatar: 'https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?w=100&h=100&fit=crop' },
];

export const MatchCenter: React.FC = () => {
  const navigate = useNavigate();
  const { turfs, bookings } = useBooking(); // Access real availability
  const [activeTab, setActiveTab] = useState<'teams' | 'pickup'>('teams');
  const [isScanning, setIsScanning] = useState(false);
  const [statusMessage, setStatusMessage] = useState("");

  // State
  const [matches, setMatches] = useState<SuggestedMatch[]>([]);
  const [generatedTeams, setGeneratedTeams] = useState<{teamA: Player[], teamB: Player[], venue: Turf, timeSlot: string, costPerPerson: number} | null>(null);
  const [aiAnalysis, setAiAnalysis] = useState<string>("");
  const [fallbackTriggered, setFallbackTriggered] = useState(false);

  const myTeam = MY_TEAMS[0];

  // Helper: Find first available slot for a turf today/tomorrow
  const findNextAvailableSlot = (turf: Turf): string | null => {
      const today = new Date().toISOString().split('T')[0];
      const start = parseInt(turf.openingHour.split(':')[0]);
      const end = parseInt(turf.closingHour.split(':')[0]);

      // Simple logic: Find first hour that isn't in bookings for today
      for (let i = start; i < end; i++) {
          const timeCheck = `${i.toString().padStart(2, '0')}:00`;
          const isBooked = bookings.some(b => b.turfId === turf.id && b.date === today && b.time === timeCheck && b.status !== 'CANCELLED');
          if (!isBooked) return timeCheck;
      }
      return null;
  };

  const calculateWinRate = (wins: number, totalGames: number = 24) => Math.round((wins / totalGames) * 100);

  const handleScan = async () => {
    setIsScanning(true);
    setMatches([]);
    setGeneratedTeams(null);
    setAiAnalysis("");
    setFallbackTriggered(false);
    setStatusMessage(activeTab === 'teams' ? "Analyzing League Data..." : "Scouting Area...");

    // Simulate AI Processing time
    setTimeout(async () => {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      if (activeTab === 'teams') {
          // --- TEAM MATCHING LOGIC ---
          setStatusMessage("Checking Venue Availability...");

          const myWinRate = calculateWinRate(myTeam.wins);

          const validMatches: SuggestedMatch[] = [];

          // Iterate through rivals to find matches that HAVE available venues
          for (const opponent of TEAM_LEADERBOARD) {
              if (opponent.name === myTeam.name) continue;

              // Find a random venue for this pairing (simulating proximity)
              // In a real app, we'd calculate lat/long distance
              const randomTurfIndex = Math.floor(Math.random() * turfs.length);
              const potentialVenue = turfs[randomTurfIndex];

              // CRITICAL: Check Availability
              const openSlot = findNextAvailableSlot(potentialVenue);

              if (openSlot) {
                  const oppWinRate = calculateWinRate(opponent.wins);
                  const skillDiff = Math.abs(myWinRate - oppWinRate);
                  // Score: High compatibility if skill is close (low diff)
                  const matchScore = Math.max(0, 100 - (skillDiff * 3)); 

                  // Only suggest high quality matches
                  if (matchScore > 60) {
                      validMatches.push({
                          id: opponent.id,
                          opponent,
                          matchScore,
                          distance: potentialVenue.distance, // Use actual turf distance
                          winRate: oppWinRate,
                          lossRate: 100 - oppWinRate,
                          venue: potentialVenue,
                          timeSlot: openSlot,
                          splitPrice: Math.ceil(potentialVenue.pricePerHour / 2) // Assuming 2 teams split
                      });
                  }
              }
          }

          // Sort by score
          validMatches.sort((a, b) => b.matchScore - a.matchScore);
          const topMatches = validMatches.slice(0, 2);

          // FALLBACK: If no suitable teams found, switch to Pickup
          if (topMatches.length === 0) {
              setFallbackTriggered(true);
              setActiveTab('pickup');
              setStatusMessage("No teams available. Switching to Pickup Mode...");
              // Recursively call scan for pickup after a slight delay
              setTimeout(() => handleScan(), 1500);
              return;
          }

          setMatches(topMatches);

          // Generate AI Hype
          try {
              const top = topMatches[0];
              const prompt = `
                Generate a 2-sentence match card hype text for a football game.
                Home: ${myTeam.name} (Win Rate: ${myWinRate}%)
                Away: ${top.opponent.name} (Win Rate: ${top.winRate}%)
                Venue: ${top.venue.name} at ${top.timeSlot} today.
                Context: The venue is available.
                Tone: Exciting, Competitive.
              `;
              const result = await ai.models.generateContent({ model: 'gemini-3-flash-preview', contents: prompt });
              setAiAnalysis(result.text || "Match found!");
          } catch (e) {
              setAiAnalysis("Perfect match found based on skill level and venue availability.");
          }

      } else {
          // --- PICKUP MATCH LOGIC (SNAKE DRAFT) ---
          setStatusMessage("Drafting Players & Balancing Squads...");

          // 1. Find a Venue First
          const availableVenues = turfs.filter(t => findNextAvailableSlot(t) !== null);

          // FALLBACK: If no venues, pick a random one but warn
          const venue = availableVenues.length > 0 
              ? availableVenues[Math.floor(Math.random() * availableVenues.length)]
              : turfs[0];

          const timeSlot = findNextAvailableSlot(venue) || "Next Open Slot";

          // 2. Snake Draft
          const sortedPlayers = [...WAITING_PLAYERS].sort((a, b) => b.rating - a.rating);
          const teamA: Player[] = [];
          const teamB: Player[] = [];

          sortedPlayers.forEach((player, index) => {
              if (index % 4 === 0 || index % 4 === 3) teamA.push(player);
              else teamB.push(player);
          });

          const totalPlayers = teamA.length + teamB.length;
          const costPerPerson = Math.ceil(venue.pricePerHour / totalPlayers);

          setGeneratedTeams({ teamA, teamB, venue, timeSlot, costPerPerson });

          // Generate AI Hype
          try {
              const avgA = (teamA.reduce((a,b)=>a+b.rating,0)/teamA.length).toFixed(1);
              const avgB = (teamB.reduce((a,b)=>a+b.rating,0)/teamB.length).toFixed(1);
              const prompt = `
                Act as a football commentator.
                A pickup game is set at ${venue.name} for ${timeSlot}.
                Team A Avg Rating: ${avgA}. Team B Avg Rating: ${avgB}.
                Price per person: ${costPerPerson} UGX.
                Write 2 sentences convincing players to accept the invite. Mention the balanced squads.
              `;
              const result = await ai.models.generateContent({ model: 'gemini-3-flash-preview', contents: prompt });
              setAiAnalysis(result.text || "Squads balanced. Venue secured. Game on!");
          } catch (e) {
              setAiAnalysis("Balanced squads generated. Venue available.");
          }
      }

      setIsScanning(false);
    }, 2000);
  };

  const calculateTotalRating = (players: Player[]) => {
      const avg = players.reduce((acc, p) => acc + p.rating, 0) / players.length;
      return avg.toFixed(1);
  };

  return (
    <Layout>
        <div className="p-5 pt-8 bg-brand-dark min-h-screen text-white pb-24">
            {/* Header */}
            <div className="flex items-center justify-between mb-6">
                <div>
                    <h1 className="text-2xl font-bold flex items-center">
                        <Sparkles className="mr-2 text-brand-secondary" /> Match Center
                    </h1>
                    <p className="text-slate-400 text-xs mt-1">AI-powered Matchmaking & Logistics</p>
                </div>
                <div className="bg-slate-800 p-2 rounded-xl border border-slate-700">
                    <img src={myTeam.logo} className="w-8 h-8 rounded-lg object-cover" />
                </div>
            </div>

            {/* Fallback Alert */}
            {fallbackTriggered && (
                <div className="bg-orange-500/10 border border-orange-500/50 rounded-xl p-4 mb-6 flex items-start animate-slideUp">
                    <AlertTriangle className="text-orange-500 mr-3 flex-shrink-0" size={20} />
                    <div>
                        <h3 className="font-bold text-orange-500 text-sm">No Active Teams Found</h3>
                        <p className="text-slate-400 text-xs mt-1">
                            We couldn't find a compatible team nearby with an open slot. 
                            <span className="text-white font-bold"> Switched to Pickup Mode</span> to build a squad from free agents.
                        </p>
                    </div>
                </div>
            )}

            {/* Toggle Switch */}
            <div className="flex bg-slate-800 p-1 rounded-xl mb-6 border border-slate-700">
                <button 
                    onClick={() => { setActiveTab('teams'); setMatches([]); setGeneratedTeams(null); setAiAnalysis(""); setFallbackTriggered(false); }}
                    className={`flex-1 py-3 rounded-lg text-sm font-bold flex items-center justify-center transition-all ${activeTab === 'teams' ? 'bg-slate-700 text-white shadow-sm' : 'text-slate-500 hover:text-slate-300'}`}
                >
                    <Swords size={16} className="mr-2" /> Find Teams
                </button>
                <button 
                    onClick={() => { setActiveTab('pickup'); setMatches([]); setGeneratedTeams(null); setAiAnalysis(""); setFallbackTriggered(false); }}
                    className={`flex-1 py-3 rounded-lg text-sm font-bold flex items-center justify-center transition-all ${activeTab === 'pickup' ? 'bg-slate-700 text-white shadow-sm' : 'text-slate-500 hover:text-slate-300'}`}
                >
                    <Shuffle size={16} className="mr-2" /> Pickup Match
                </button>
            </div>

            {/* Radar / Scan UI */}
            <div className="relative mb-8">
                <div className="bg-gradient-to-b from-slate-800 to-slate-900 rounded-3xl p-8 border border-slate-700 shadow-xl overflow-hidden text-center relative min-h-[240px] flex flex-col justify-center transition-all duration-500">

                    {/* Background Grid Animation */}
                    <div className="absolute inset-0 opacity-10" 
                         style={{ backgroundImage: 'radial-gradient(circle, #8b5cf6 1px, transparent 1px)', backgroundSize: '20px 20px' }}>
                    </div>

                    {!isScanning && matches.length === 0 && !generatedTeams && (
                        <div className="relative z-10 animate-fadeIn">
                            <div className="w-20 h-20 bg-brand-secondary/10 rounded-full flex items-center justify-center mx-auto mb-4 border-2 border-brand-secondary/30 relative">
                                {activeTab === 'teams' ? <Swords size={32} className="text-brand-secondary" /> : <Users size={32} className="text-brand-secondary" />}
                                <div className="absolute inset-0 rounded-full border border-brand-secondary/50 animate-ping"></div>
                            </div>
                            <h2 className="text-xl font-bold mb-2">{activeTab === 'teams' ? 'Challenge a Rival' : 'Lobby: 10 Players Waiting'}</h2>
                            <p className="text-slate-400 text-sm mb-6 max-w-xs mx-auto">
                                {activeTab === 'teams' 
                                    ? `AI will check ${turfs.length} venues for availability and pair you with a skill-matched rival.`
                                    : "Auto-draft players into balanced teams and find a venue with open slots instantly."}
                            </p>
                            <button 
                                onClick={handleScan}
                                className="bg-brand-secondary hover:bg-emerald-500 text-white font-bold py-4 px-8 rounded-xl shadow-lg shadow-emerald-500/20 transition-transform active:scale-95 flex items-center mx-auto"
                            >
                                <Zap size={20} className="mr-2 fill-current" /> {activeTab === 'teams' ? 'Scan League' : 'Auto-Balance'}
                            </button>
                        </div>
                    )}

                    {isScanning && (
                        <div className="relative z-10 flex flex-col items-center">
                            <Loader2 size={48} className="text-brand-secondary animate-spin mb-4" />
                            <h3 className="text-lg font-bold animate-pulse">
                                {statusMessage}
                            </h3>
                            <div className="mt-4 flex space-x-2">
                                <span className="w-2 h-2 bg-slate-500 rounded-full animate-bounce" style={{animationDelay: '0ms'}}></span>
                                <span className="w-2 h-2 bg-slate-500 rounded-full animate-bounce" style={{animationDelay: '150ms'}}></span>
                                <span className="w-2 h-2 bg-slate-500 rounded-full animate-bounce" style={{animationDelay: '300ms'}}></span>
                            </div>
                        </div>
                    )}

                    {/* AI Analysis Result */}
                    {!isScanning && (matches.length > 0 || generatedTeams) && (
                        <div className="relative z-10 text-left animate-fadeIn mt-2">
                            <div className="flex items-start space-x-3 bg-brand-primary/10 border border-brand-primary/20 p-4 rounded-xl backdrop-blur-md">
                                <Sparkles className="text-brand-primary flex-shrink-0 mt-0.5" size={18} />
                                <div>
                                    <h3 className="text-brand-primary font-bold text-xs uppercase mb-1 flex items-center">
                                        {activeTab === 'teams' ? 'Match Preview' : 'Scouting Report'} <BrainCircuit size={12} className="ml-1" />
                                    </h3>
                                    <p className="text-slate-200 text-sm font-medium leading-relaxed">
                                        {aiAnalysis || "Analyzing..."}
                                    </p>
                                </div>
                            </div>
                        </div>
                    )}
                </div>
            </div>

            {/* Results List */}
            {!isScanning && (matches.length > 0 || generatedTeams) && (
                <div className="space-y-6 animate-slideUp">

                    {/* TEAM MATCHES LIST */}
                    {activeTab === 'teams' && matches.map((match, index) => (
                        <div key={match.id} className="bg-slate-800 rounded-3xl p-5 border border-slate-700 relative overflow-hidden group hover:border-brand-secondary transition-colors">
                            <div className="absolute top-0 right-0 bg-slate-700 pl-4 pb-2 pt-2 pr-4 rounded-bl-3xl border-b border-l border-slate-600">
                                <span className={`text-sm font-bold ${index === 0 ? 'text-brand-secondary' : 'text-slate-300'}`}>
                                    {match.matchScore}% Compatibility
                                </span>
                            </div>

                            <div className="flex items-center mb-6">
                                <img src={match.opponent.logo} className="w-16 h-16 rounded-xl object-cover border-2 border-slate-600 mr-4" />
                                <div>
                                    <h4 className="text-xl font-bold text-white mb-1">{match.opponent.name}</h4>
                                    <div className="flex items-center text-xs text-slate-400 font-medium">
                                        <MapPin size={12} className="mr-1 text-slate-500" />
                                        {match.distance} • {match.venue.name}
                                    </div>
                                </div>
                            </div>

                            <div className="grid grid-cols-2 gap-4 mb-6">
                                <div className="bg-slate-900/50 p-3 rounded-xl border border-slate-700">
                                    <div className="text-xs text-slate-400 uppercase font-bold mb-1">Time Slot</div>
                                    <div className="text-white font-bold flex items-center">
                                        <Clock size={14} className="mr-2 text-brand-secondary" /> {match.timeSlot}
                                    </div>
                                </div>
                                <div className="bg-slate-900/50 p-3 rounded-xl border border-slate-700">
                                    <div className="text-xs text-slate-400 uppercase font-bold mb-1">Split Cost</div>
                                    <div className="text-white font-bold flex items-center">
                                        <Wallet size={14} className="mr-2 text-brand-secondary" /> {match.splitPrice.toLocaleString()} ea
                                    </div>
                                </div>
                            </div>

                            <div className="grid grid-cols-2 gap-4 mb-6">
                                <div>
                                    <div className="flex justify-between text-xs mb-1.5">
                                        <span className="text-emerald-400 font-bold flex items-center"><TrendingUp size={12} className="mr-1"/> Win Rate</span>
                                        <span className="text-white font-bold">{match.winRate}%</span>
                                    </div>
                                    <div className="h-1.5 bg-slate-900 rounded-full overflow-hidden">
                                        <div style={{ width: `${match.winRate}%` }} className="h-full bg-emerald-500 rounded-full"></div>
                                    </div>
                                </div>
                                <div>
                                    <div className="flex justify-between text-xs mb-1.5">
                                        <span className="text-red-400 font-bold flex items-center"><TrendingDown size={12} className="mr-1"/> Loss Rate</span>
                                        <span className="text-white font-bold">{match.lossRate}%</span>
                                    </div>
                                    <div className="h-1.5 bg-slate-900 rounded-full overflow-hidden">
                                        <div style={{ width: `${match.lossRate}%` }} className="h-full bg-red-500 rounded-full"></div>
                                    </div>
                                </div>
                            </div>

                            <button onClick={() => navigate(`/turf/${match.venue.id}`)} className="w-full bg-brand-secondary text-white font-bold py-3 rounded-xl text-sm shadow-lg shadow-emerald-900/20 hover:bg-emerald-600 transition-colors flex items-center justify-center">
                                <CheckCircle size={16} className="mr-2" /> Book {match.venue.name} @ {match.timeSlot}
                            </button>
                        </div>
                    ))}

                    {/* PICKUP TEAMS GENERATOR UI */}
                    {activeTab === 'pickup' && generatedTeams && (
                        <div className="animate-slideUp">
                             {/* Versus Header */}
                             <div className="flex items-center justify-center mb-6">
                                 <div className="bg-orange-500/20 text-orange-500 font-black text-xl px-4 py-2 rounded-xl border border-orange-500/30 tracking-widest">
