                                     </div>
                                     <div className="space-y-3">
                                         {generatedTeams.teamA.map((p) => (
                                             <div key={p.id} className="flex items-center">
                                                 <img src={p.avatar} className="w-8 h-8 rounded-full border border-slate-600 mr-2" />
                                                 <div className="overflow-hidden">
                                                     <p className="text-xs font-bold text-white truncate">{p.name}</p>
                                                     <p className="text-[10px] text-slate-400 truncate">{p.role} • <span className="text-yellow-500">{p.rating}</span></p>
                                                 </div>
                                             </div>
                                         ))}
                                     </div>
                                 </div>

                                 {/* TEAM B */}
                                 <div className="bg-slate-800 rounded-3xl p-4 border border-slate-700">
                                     <div className="flex justify-between items-center mb-4 border-b border-slate-700 pb-3">
                                         <h3 className="font-bold text-white">Non-Bibs (B)</h3>
                                         <div className="flex items-center text-yellow-400 text-xs font-bold">
                                             <Star size={10} className="fill-current mr-1" />
                                             {calculateTotalRating(generatedTeams.teamB)}
                                         </div>
                                     </div>
                                     <div className="space-y-3">
                                         {generatedTeams.teamB.map((p) => (
                                             <div key={p.id} className="flex items-center">
                                                 <img src={p.avatar} className="w-8 h-8 rounded-full border border-slate-600 mr-2" />
                                                 <div className="overflow-hidden">
                                                     <p className="text-xs font-bold text-white truncate">{p.name}</p>
                                                     <p className="text-[10px] text-slate-400 truncate">{p.role} • <span className="text-yellow-500">{p.rating}</span></p>
                                                 </div>
                                             </div>
                                         ))}
                                     </div>
                                 </div>
                             </div>

                             {/* Logistics Card */}
                             <div className="mt-6 bg-slate-800 rounded-2xl p-5 border border-slate-700">
                                 <h4 className="text-white font-bold mb-4 flex items-center">
                                     <Clock className="text-brand-secondary mr-2" /> Match Logistics
                                 </h4>
                                 <div className="grid grid-cols-2 gap-4 text-sm">
                                     <div>
                                         <p className="text-slate-500 text-xs uppercase font-bold">Venue</p>
                                         <p className="text-white font-bold truncate">{generatedTeams.venue.name}</p>
                                     </div>
                                     <div>
                                         <p className="text-slate-500 text-xs uppercase font-bold">Time</p>
                                         <p className="text-white font-bold">{generatedTeams.timeSlot}</p>
                                     </div>
                                     <div>
                                         <p className="text-slate-500 text-xs uppercase font-bold">Split Cost</p>
                                         <p className="text-white font-bold">UGX {generatedTeams.costPerPerson.toLocaleString()}</p>
                                     </div>
                                     <div>
                                         <p className="text-slate-500 text-xs uppercase font-bold">Status</p>
                                         <p className="text-brand-secondary font-bold">Available</p>
                                     </div>
                                 </div>
                             </div>

                             <button 
                                onClick={() => navigate(`/turf/${generatedTeams.venue.id}`)} 
                                className="w-full mt-4 bg-brand-secondary text-white font-bold py-4 rounded-xl shadow-lg shadow-emerald-500/20 hover:bg-emerald-600 flex items-center justify-center"
                             >
                                 Confirm Booking & Invite Players <ArrowRight size={18} className="ml-2" />
                             </button>

                             <button 
                                onClick={handleScan}
                                className="w-full mt-3 py-3 text-slate-500 font-bold text-xs hover:text-white"
                             >
                                 Reshuffle Teams
                             </button>
                        </div>
                    )}
                </div>
            )}
        </div>
    </Layout>
  );
};

import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Layout } from '../components/Layout';
import { GoogleGenAI } from "@google/genai";
import { MY_TEAMS, TEAM_LEADERBOARD } from '../constants';
import { useBooking } from '../context/BookingContext';
import { Turf } from '../types';
import { Sparkles, Zap, MapPin, TrendingUp, TrendingDown, Swords, Loader2, BrainCircuit, User, Star, Wallet, CheckCircle, Users, Shuffle, ArrowRight, Clock, AlertTriangle, Calendar, Shield, Activity } from 'lucide-react';

interface SuggestedMatch {
  id: string;
  opponent: typeof TEAM_LEADERBOARD[0];
  matchScore: number;
  distance: string;
  winRate: number;
  lossRate: number;
  venue: Turf;
  timeSlot: string;
  splitPrice: number;
}

interface Player {
    id: string;
    name: string;
    role: string; // 'GK' | 'Defender' | 'Midfielder' | 'Striker' | 'Winger'
    rating: number;
    reviews: number;
    avatar: string;
}

// Pool of players waiting for a game - Expanded for 6v6 balance
const WAITING_PLAYERS: Player[] = [
    { id: 'p1', name: 'David O.', role: 'Striker', rating: 4.9, reviews: 42, avatar: 'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?w=100&h=100&fit=crop' },
