      const maxP = newMatch.format === '5-a-side' ? 10 : newMatch.format === '7-a-side' ? 14 : 22;
      const totalCost = selectedTurf.pricePerHour * newMatch.duration;
      const costPerPerson = newMatch.paymentMode === 'Split' ? Math.ceil(totalCost / maxP) : 0;

      // 1. Create Booking
      const bookingId = Math.random().toString(36).substr(2, 9).toUpperCase();
      addBooking({
          id: bookingId,
          turfId: selectedTurf.id,
          turfName: selectedTurf.name,
          userName: 'You (Organizer)',
          date: newMatch.date,
          time: newMatch.time,
          duration: newMatch.duration,
          status: 'CONFIRMED',
          price: totalCost,
          createdAt: new Date().toISOString()
      });

      // 2. Generate AI Title/Desc
      let aiTitle = `${newMatch.type} Match at ${selectedTurf.name}`;
      let aiDesc = "Join us for a great game!";

      try {
          const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
          const prompt = `
            Generate a short, exciting title (max 5 words) and a 1-sentence description for a football match.
            Type: ${newMatch.type}. Format: ${newMatch.format}. Venue: ${selectedTurf.name}.
            Roles needed: ${newMatch.roles.join(', ')}.
          `;
          const result = await ai.models.generateContent({ model: 'gemini-3-flash-preview', contents: prompt });
          const text = result.text || "";
          const parts = text.split('\n').filter(line => line.trim() !== '');
          if (parts.length >= 2) {
              aiTitle = parts[0].replace('Title:', '').trim().replace(/"/g, '');
              aiDesc = parts[1].replace('Description:', '').trim();
          }
      } catch (e) {
          console.error("AI Error", e);
      }

      // 3. Add to Community Feed
      const newCommunityMatch: CommunityMatch = {
          id: Date.now().toString(),
          title: aiTitle,
          description: aiDesc,
          organizer: 'You',
          organizerAvatar: 'https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?w=100&h=100&fit=crop',
