                                          </button>
                                      ))}
                                  </div>
                              </div>
                              <div>
                                  <label className="text-xs font-bold text-slate-500 uppercase mb-2 block">Format</label>
                                  <div className="grid grid-cols-3 gap-2">
                                      {['5-a-side', '7-a-side', '11-a-side'].map(fmt => (
                                          <button 
                                            key={fmt}
                                            onClick={() => setNewMatch({...newMatch, format: fmt})}
                                            className={`py-3 rounded-xl text-sm font-bold border ${newMatch.format === fmt ? 'bg-brand-secondary border-brand-secondary text-white' : 'border-slate-200 dark:border-slate-700 text-slate-500 dark:text-slate-300'}`}
                                          >
                                              {fmt}
                                          </button>
                                      ))}
                                  </div>
                              </div>
                              <div>
                                  <label className="text-xs font-bold text-slate-500 uppercase mb-2 block">Duration</label>
                                  <div className="flex bg-slate-100 dark:bg-slate-800 p-1 rounded-xl">
                                      {[1, 1.5, 2].map(d => (
                                          <button 
                                              key={d}
                                              onClick={() => setNewMatch({...newMatch, duration: d})}
                                              className={`flex-1 py-2 rounded-lg text-sm font-bold transition-all ${newMatch.duration === d ? 'bg-white dark:bg-slate-700 text-slate-900 dark:text-white shadow-sm' : 'text-slate-500'}`}
                                          >
                                              {d}h
                                          </button>
                                      ))}
                                  </div>
                              </div>
                              <div>
                                  <label className="text-xs font-bold text-slate-500 uppercase mb-2 block">Roles Needed</label>
                                  <div className="flex flex-wrap gap-2">
                                      {['GK', 'Defender', 'Midfielder', 'Striker'].map(role => (
                                          <button
                                              key={role}
                                              onClick={() => {
                                                  const roles = newMatch.roles.includes(role) 
                                                    ? newMatch.roles.filter(r => r !== role)
                                                    : [...newMatch.roles, role];
                                                  setNewMatch({...newMatch, roles});
                                              }}
                                              className={`px-3 py-1.5 rounded-lg text-xs font-bold border ${newMatch.roles.includes(role) ? 'bg-brand-secondary/20 border-brand-secondary text-brand-secondary' : 'border-slate-200 dark:border-slate-700 text-slate-500'}`}
                                          >
                                              {role}
                                          </button>
                                      ))}
                                  </div>
                              </div>
                          </div>
                      )}

                      {createStep === 1 && (
                          <div className="space-y-4 animate-slideUp">
                               <div>
                                  <label className="text-xs font-bold text-slate-500 uppercase mb-2 block">Date</label>
                                  <input 
