                                    value={newMatch.date}
                                    onChange={(e) => setNewMatch({...newMatch, date: e.target.value})}
                                    className="w-full bg-slate-100 dark:bg-slate-800 border-none rounded-xl p-3 text-slate-900 dark:text-white font-bold outline-none focus:ring-2 focus:ring-brand-secondary"
