                                            onClick={() => setNewMatch({...newMatch, venueId: turf.id, time: ''})}
                                            className={`p-3 rounded-xl border flex justify-between items-center cursor-pointer transition-all ${newMatch.venueId === turf.id ? 'border-brand-secondary bg-brand-secondary/10' : 'border-slate-200 dark:border-slate-700 hover:border-slate-400'}`}
                                           >
                                               <div>
                                                   <p className="font-bold text-sm text-slate-900 dark:text-white">{turf.name}</p>
