                                          </button>
                                      ))}
                                  </div>
                                  <p className="text-xs text-slate-400 mt-2 text-center">
                                      {newMatch.paymentMode === 'Split' 
                                        ? `Est. UGX ${(selectedTurf ? Math.ceil((selectedTurf.pricePerHour * newMatch.duration) / 10) : 0).toLocaleString()} per person`
                                        : `Total UGX ${(selectedTurf ? selectedTurf.pricePerHour * newMatch.duration : 0).toLocaleString()}`
                                      }
