                      <button 
                        onClick={() => createStep === 2 ? handleCreateSubmit() : setCreateStep(createStep + 1)}
                        disabled={createStep === 1 && (!newMatch.venueId || !newMatch.time)}
                        className={`px-8 py-3 bg-brand-secondary text-white rounded-xl font-bold shadow-lg flex items-center ml-auto ${createStep === 1 && (!newMatch.venueId || !newMatch.time) ? 'opacity-50' : 'hover:bg-emerald-600'}`}
