  const handleScan = async () => {
    setIsScanning(true);
    setMatches([]);
    setGeneratedTeams(null);
    setAiAnalysis("");
    setFallbackTriggered(false);
    setStatusMessage(activeTab === 'teams' ? "Analyzing League Data..." : "Drafting Players by Position...");

    // Simulate AI Processing time
    setTimeout(async () => {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      if (activeTab === 'teams') {
          // --- TEAM MATCHING LOGIC ---
          setStatusMessage("Checking Venue Availability...");

          const myWinRate = calculateWinRate(myTeam.wins);
          const validMatches: SuggestedMatch[] = [];

          for (const opponent of TEAM_LEADERBOARD) {
              if (opponent.name === myTeam.name) continue;
              const randomTurfIndex = Math.floor(Math.random() * turfs.length);
              const potentialVenue = turfs[randomTurfIndex];
              const openSlot = findNextAvailableSlot(potentialVenue);

              if (openSlot) {
                  const oppWinRate = calculateWinRate(opponent.wins);
                  const skillDiff = Math.abs(myWinRate - oppWinRate);
                  const matchScore = Math.max(0, 100 - (skillDiff * 3)); 

                  if (matchScore > 60) {
                      validMatches.push({
                          id: opponent.id,
                          opponent,
                          matchScore,
                          distance: potentialVenue.distance,
                          winRate: oppWinRate,
                          lossRate: 100 - oppWinRate,
                          venue: potentialVenue,
                          timeSlot: openSlot,
                          splitPrice: Math.ceil(potentialVenue.pricePerHour / 2) 
                      });
                  }
              }
          }

          validMatches.sort((a, b) => b.matchScore - a.matchScore);
          const topMatches = validMatches.slice(0, 2);

          if (topMatches.length === 0) {
              setFallbackTriggered(true);
              setActiveTab('pickup');
              setStatusMessage("No teams available. Switching to Pickup Mode...");
              setTimeout(() => handleScan(), 1500);
              return;
          }

          setMatches(topMatches);

          try {
              const top = topMatches[0];
              const prompt = `
                Generate a 2-sentence match card hype text.
                Home: ${myTeam.name} (Win Rate: ${myWinRate}%) vs ${top.opponent.name} (Win Rate: ${top.winRate}%).
                Venue: ${top.venue.name} at ${top.timeSlot}.
                Tone: Exciting, Competitive.
              `;
              const result = await ai.models.generateContent({ model: 'gemini-3-flash-preview', contents: prompt });
              setAiAnalysis(result.text || "Match found!");
          } catch (e) {
              setAiAnalysis("Perfect match found based on skill level and venue availability.");
          }

      } else if (activeTab === 'pickup') {
          // --- PICKUP MATCH LOGIC (POSITIONAL BALANCING) ---
          setStatusMessage("Balancing Squads (GK, DEF, MID, FWD)...");

          const availableVenues = turfs.filter(t => findNextAvailableSlot(t) !== null);
          const venue = availableVenues.length > 0 
              ? availableVenues[Math.floor(Math.random() * availableVenues.length)]
              : turfs[0];
          const timeSlot = findNextAvailableSlot(venue) || "Next Open Slot";

          const teamA: Player[] = [];
          const teamB: Player[] = [];

          const goalkeepers = WAITING_PLAYERS.filter(p => p.role === 'GK').sort((a,b) => b.rating - a.rating);
          const defenders = WAITING_PLAYERS.filter(p => p.role === 'Defender').sort((a,b) => b.rating - a.rating);
          const midfielders = WAITING_PLAYERS.filter(p => ['Midfielder', 'Winger'].includes(p.role)).sort((a,b) => b.rating - a.rating);
          const strikers = WAITING_PLAYERS.filter(p => p.role === 'Striker').sort((a,b) => b.rating - a.rating);

          const distribute = (pool: Player[]) => {
            pool.forEach(p => {
                if (teamA.length < teamB.length) teamA.push(p);
                else if (teamB.length < teamA.length) teamB.push(p);
                else {
                    const rateA = teamA.reduce((acc, curr) => acc + curr.rating, 0);
                    const rateB = teamB.reduce((acc, curr) => acc + curr.rating, 0);
                    if (rateA <= rateB) teamA.push(p);
                    else teamB.push(p);
                }
            });
          };

          distribute(goalkeepers);
          distribute(defenders);
          distribute(midfielders);
          distribute(strikers);

          const totalPlayers = teamA.length + teamB.length;
          const costPerPerson = Math.ceil(venue.pricePerHour / totalPlayers);

          setGeneratedTeams({ teamA, teamB, venue, timeSlot, costPerPerson });

          try {
              const avgA = (teamA.reduce((a,b)=>a+b.rating,0)/teamA.length).toFixed(1);
              const avgB = (teamB.reduce((a,b)=>a+b.rating,0)/teamB.length).toFixed(1);
              const prompt = `
                Act as a football analyst. Pickup game at ${venue.name}.
                Team A (Avg ${avgA}) vs Team B (Avg ${avgB}).
                Write 2 sentences praising the tactical balance (GK, Def, Mid, Fwd).
              `;
              const result = await ai.models.generateContent({ model: 'gemini-3-flash-preview', contents: prompt });
              setAiAnalysis(result.text || "Squads balanced tactically. GKs and Defenders locked in. Game on!");
          } catch (e) {
              setAiAnalysis("Balanced squads generated. Positional requirements met.");
          }
      }

      setIsScanning(false);
    }, 2000);
  };

