    { id: 'p1', name: 'David O.', role: 'Striker', rating: 4.9, avatar: 'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?w=100&h=100&fit=crop' },
    { id: 'p4', name: 'John D.', role: 'GK', rating: 4.8, avatar: 'https://images.unsplash.com/photo-1599566150163-29194dcaad36?w=100&h=100&fit=crop' },
    { id: 'p12', name: 'Simon P.', role: 'GK', rating: 4.5, avatar: 'https://images.unsplash.com/photo-1566492031773-4f4e44671857?w=100&h=100&fit=crop' },
    { id: 'p3', name: 'Musa B.', role: 'Defender', rating: 4.5, avatar: 'https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?w=100&h=100&fit=crop' },
    { id: 'p6', name: 'Chris P.', role: 'Defender', rating: 4.3, avatar: 'https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?w=100&h=100&fit=crop' },
    { id: 'p9', name: 'Mike L.', role: 'Defender', rating: 4.1, avatar: 'https://images.unsplash.com/photo-1522075469751-3a6694fb2f61?w=100&h=100&fit=crop' },
    { id: 'p11', name: 'Tom H.', role: 'Defender', rating: 4.4, avatar: 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=100&h=100&fit=crop' },
    { id: 'p2', name: 'Sarah K.', role: 'Midfielder', rating: 4.7, avatar: 'https://images.unsplash.com/photo-1438761681033-6461ffad8d80?w=100&h=100&fit=crop' },
    { id: 'p7', name: 'Sam M.', role: 'Midfielder', rating: 4.6, avatar: 'https://images.unsplash.com/photo-1527980965255-d3b416303d12?w=100&h=100&fit=crop' },
    { id: 'p5', name: 'Alex R.', role: 'Winger', rating: 4.2, avatar: 'https://images.unsplash.com/photo-1570295999919-56ceb5ecca61?w=100&h=100&fit=crop' },
    { id: 'p8', name: 'Lisa T.', role: 'Striker', rating: 4.4, avatar: 'https://images.unsplash.com/photo-1544005313-94ddf0286df2?w=100&h=100&fit=crop' },
    { id: 'p10', name: 'You', role: 'Midfielder', rating: 4.5, avatar: 'https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?w=100&h=100&fit=crop' },
];

export const MatchCenter: React.FC = () => {
  const navigate = useNavigate();
  const { turfs, bookings, addBooking } = useBooking(); 
  const { addXP } = useUser();

  // Tabs: 'rivals' = Team Matching, 'open' = Pickup/Community Combined
  const [activeTab, setActiveTab] = useState<'rivals' | 'open'>('rivals');

  // UI States
  const [isScanning, setIsScanning] = useState(false);
  const [statusMessage, setStatusMessage] = useState("");
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [createStep, setCreateStep] = useState(0); 
  const [aiAnalysis, setAiAnalysis] = useState<string>("");
  const [fallbackTriggered, setFallbackTriggered] = useState(false);

  // Data States
  const [matches, setMatches] = useState<SuggestedMatch[]>([]);
  const [generatedLobby, setGeneratedLobby] = useState<{teamA: Player[], teamB: Player[], venue: Turf, timeSlot: string, costPerPerson: number} | null>(null);

  const [communityMatches, setCommunityMatches] = useState<CommunityMatch[]>([
      {
          id: 'cm1',
          title: 'Sunday Morning Sweat',
          description: 'Casual game to start the day. Beginners welcome!',
          organizer: 'Coach Mike',
          organizerAvatar: 'https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?w=100&h=100&fit=crop',
          venue: turfs[0],
          date: '2025-01-20',
          time: '08:00',
          format: '5-a-side',
          joined: 7,
          maxPlayers: 10,
          costPerPerson: 5000,
          rolesNeeded: ['GK', 'Defender'],
          type: 'Friendly'
      },
      {
          id: 'cm2',
          title: 'Competitive 7v7',
          description: 'High intensity match. Bring your A-game.',
          organizer: 'Sarah K.',
          organizerAvatar: 'https://images.unsplash.com/photo-1438761681033-6461ffad8d80?w=100&h=100&fit=crop',
          venue: turfs[2],
          date: '2025-01-20',
          time: '19:00',
          format: '7-a-side',
          joined: 12,
          maxPlayers: 14,
          costPerPerson: 8000,
          rolesNeeded: ['Striker'],
          type: 'Competitive'
      }
  ]);

  // Create Match Form State
  const [newMatch, setNewMatch] = useState({
      type: 'Friendly',
      format: '5-a-side',
      duration: 1,
      venueId: '',
      date: new Date().toISOString().split('T')[0],
      time: '',
      paymentMode: 'Split',
      roles: [] as string[],
  });

  const myTeam = MY_TEAMS[0];

  // --- HELPERS ---
  const findNextAvailableSlot = (turf: Turf): string | null => {
      const today = new Date().toISOString().split('T')[0];
      const start = parseInt(turf.openingHour.split(':')[0]);
      const end = parseInt(turf.closingHour.split(':')[0]);

      for (let i = start; i < end; i++) {
          const timeCheck = `${i.toString().padStart(2, '0')}:00`;
          const isBooked = bookings.some(b => b.turfId === turf.id && b.date === today && b.time === timeCheck && b.status !== 'CANCELLED');
          if (!isBooked) return timeCheck;
      }
      return null;
  };

  const calculateWinRate = (wins: number, totalGames: number = 24) => Math.round((wins / totalGames) * 100);
  const calculateTotalRating = (players: Player[]) => (players.reduce((acc, p) => acc + p.rating, 0) / players.length).toFixed(1);

  // --- ACTION: JOIN MATCH ---
  const handleJoinMatch = (matchId: string) => {
      setCommunityMatches(prev => prev.map(m => {
          if (m.id === matchId && m.joined < m.maxPlayers) {
              addXP(50); // Join Bonus
              return { ...m, joined: m.joined + 1 };
          }
          return m;
      }));
  };

  // --- ACTION: GENERATE LOBBY (AI PICKUP) ---
  const handleGenerateLobby = async () => {
    setIsScanning(true);
    setGeneratedLobby(null);
    setAiAnalysis("");
    setStatusMessage("Drafting Balanced Squads...");

    setTimeout(async () => {
        const availableVenues = turfs.filter(t => findNextAvailableSlot(t) !== null);
        const venue = availableVenues.length > 0 
            ? availableVenues[Math.floor(Math.random() * availableVenues.length)] 
            : turfs[0];
        const timeSlot = findNextAvailableSlot(venue) || "Next Open Slot";

        const teamA: Player[] = [];
        const teamB: Player[] = [];

        // Logic to balance by role
        const pool = [...WAITING_PLAYERS];
        const roles = ['GK', 'Defender', 'Midfielder', 'Striker'];

        roles.forEach(role => {
            const rolePlayers = pool.filter(p => p.role === role || (role === 'Midfielder' && p.role === 'Winger')).sort((a,b) => b.rating - a.rating);
            rolePlayers.forEach(p => {
                if(teamA.length <= teamB.length) teamA.push(p);
                else teamB.push(p);
            });
        });

        const totalPlayers = teamA.length + teamB.length;
        const costPerPerson = Math.ceil(venue.pricePerHour / totalPlayers);

        setGeneratedLobby({ teamA, teamB, venue, timeSlot, costPerPerson });
        setIsScanning(false);
        setAiAnalysis("AI has balanced the lobby. 1 GK and 4 Defenders per side.");
    }, 1500);
  };

  // --- ACTION: CREATE MATCH SUBMIT ---
  const handleCreateSubmit = async () => {
      setIsScanning(true);
      setShowCreateModal(false);
      setStatusMessage("Finalizing Logistics & AI Hype...");

      const selectedTurf = turfs.find(t => t.id === newMatch.venueId) || turfs[0];
      const maxP = newMatch.format === '5-a-side' ? 10 : 14;
      const totalCost = selectedTurf.pricePerHour * newMatch.duration;
      const costPerPerson = newMatch.paymentMode === 'Split' ? Math.ceil(totalCost / maxP) : 0;

      // 1. Create System Booking
      const bookingId = Math.random().toString(36).substr(2, 9).toUpperCase();
      addBooking({
          id: bookingId,
          turfId: selectedTurf.id,
          turfName: selectedTurf.name,
          userName: 'You (Organizer)',
          date: newMatch.date,
          time: newMatch.time,
          duration: newMatch.duration,
          status: 'CONFIRMED',
          price: totalCost,
          createdAt: new Date().toISOString()
      });

      // 2. AI Gen Title
      let aiTitle = `${newMatch.type} at ${selectedTurf.name}`;
      let aiDesc = "Join us!";
      try {
          const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
          const prompt = `Generate a 3-4 word exciting title and 1 sentence description for a ${newMatch.type} football match at ${selectedTurf.name}.`;
          const result = await ai.models.generateContent({ model: 'gemini-3-flash-preview', contents: prompt });
          const text = result.text || "";
          const lines = text.split('\n').filter(l => l);
          if (lines.length > 0) aiTitle = lines[0].replace(/"/g, '');
          if (lines.length > 1) aiDesc = lines[1];
      } catch (e) { console.error(e); }

      const newCommunityMatch: CommunityMatch = {
          id: bookingId,
          title: aiTitle,
          description: aiDesc,
          organizer: 'You',
          organizerAvatar: 'https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?w=100&h=100&fit=crop',
          venue: selectedTurf,
          date: newMatch.date,
          time: newMatch.time,
          format: newMatch.format,
          joined: 1,
          maxPlayers: maxP,
          costPerPerson: costPerPerson,
          rolesNeeded: newMatch.roles,
          type: newMatch.type as any
      };

      setTimeout(() => {
          setCommunityMatches([newCommunityMatch, ...communityMatches]);
          setIsScanning(false);
          addXP(200); 
      }, 1500);
  };

  // --- ACTION: RIVALS SCAN ---
  const handleRivalScan = async () => {
      setIsScanning(true);
      setMatches([]);
      setStatusMessage("Analyzing League Data...");

      setTimeout(async () => {
        const myWinRate = calculateWinRate(myTeam.wins);
        const validMatches: SuggestedMatch[] = [];

        for (const opponent of TEAM_LEADERBOARD) {
            if (opponent.name === myTeam.name) continue;
            const randomTurfIndex = Math.floor(Math.random() * turfs.length);
            const potentialVenue = turfs[randomTurfIndex];
            const openSlot = findNextAvailableSlot(potentialVenue);

            if (openSlot) {
                const oppWinRate = calculateWinRate(opponent.wins);
                const skillDiff = Math.abs(myWinRate - oppWinRate);
                const matchScore = Math.max(0, 100 - (skillDiff * 3)); 

                if (matchScore > 60) {
                    validMatches.push({
                        id: opponent.id,
                        opponent,
                        matchScore,
                        distance: potentialVenue.distance,
                        winRate: oppWinRate,
                        lossRate: 100 - oppWinRate,
                        venue: potentialVenue,
                        timeSlot: openSlot,
                        splitPrice: Math.ceil(potentialVenue.pricePerHour / 2) 
                    });
                }
            }
        }
        validMatches.sort((a, b) => b.matchScore - a.matchScore);
        const topMatches = validMatches.slice(0, 2);

        if (topMatches.length === 0) setFallbackTriggered(true);
        else setMatches(topMatches);

        setIsScanning(false);
      }, 2000);
  };

  // --- RENDER HELPERS ---
  const CreateMatchWizard = () => {
    const selectedTurf = turfs.find(t => t.id === newMatch.venueId);

    // Get Time Slots for selected venue
    const availableSlots = selectedTurf ? ['09:00', '10:00', '16:00', '17:00', '18:00', '19:00', '20:00'].filter(t => {
         return !bookings.some(b => b.turfId === selectedTurf.id && b.date === newMatch.date && b.time === t && b.status !== 'CANCELLED');
    }) : [];

    return (
        <div className="fixed inset-0 z-50 flex items-end sm:items-center justify-center bg-black/80 backdrop-blur-sm animate-fadeIn p-4">
            <div className="bg-white dark:bg-brand-surface w-full max-w-md rounded-3xl overflow-hidden shadow-2xl flex flex-col max-h-[85vh]">
                <div className="bg-slate-50 dark:bg-slate-800 p-5 border-b border-slate-200 dark:border-slate-700 flex justify-between items-center">
                    <h3 className="font-bold text-slate-900 dark:text-white text-lg">Create Match</h3>
                    <button onClick={() => setShowCreateModal(false)}><X className="text-slate-400" /></button>
                </div>

                <div className="p-6 overflow-y-auto flex-1">
                    {createStep === 0 && (
                        <div className="space-y-4 animate-slideUp">
                            <div>
                                <label className="text-xs font-bold text-slate-500 uppercase mb-2 block">Match Type</label>
                                <div className="grid grid-cols-3 gap-2">
                                    {['Friendly', 'Competitive', 'Pickup'].map(type => (
                                        <button key={type} onClick={() => setNewMatch({...newMatch, type})} className={`py-3 rounded-xl text-sm font-bold border ${newMatch.type === type ? 'bg-brand-secondary border-brand-secondary text-white' : 'border-slate-200 dark:border-slate-700 text-slate-500 dark:text-slate-300'}`}>{type}</button>
                                    ))}
                                </div>
                            </div>
                            <div>
                                <label className="text-xs font-bold text-slate-500 uppercase mb-2 block">Format</label>
                                <div className="grid grid-cols-3 gap-2">
                                    {['5-a-side', '7-a-side', '11-a-side'].map(fmt => (
                                        <button key={fmt} onClick={() => setNewMatch({...newMatch, format: fmt})} className={`py-3 rounded-xl text-sm font-bold border ${newMatch.format === fmt ? 'bg-brand-secondary border-brand-secondary text-white' : 'border-slate-200 dark:border-slate-700 text-slate-500 dark:text-slate-300'}`}>{fmt}</button>
                                    ))}
                                </div>
                            </div>
                            <div>
                                <label className="text-xs font-bold text-slate-500 uppercase mb-2 block">Roles Needed</label>
                                <div className="flex flex-wrap gap-2">
                                    {['GK', 'Defender', 'Midfielder', 'Striker'].map(role => (
                                        <button key={role} onClick={() => {
                                            const roles = newMatch.roles.includes(role) ? newMatch.roles.filter(r => r !== role) : [...newMatch.roles, role];
                                            setNewMatch({...newMatch, roles});
                                        }} className={`px-3 py-1.5 rounded-lg text-xs font-bold border ${newMatch.roles.includes(role) ? 'bg-brand-secondary/20 border-brand-secondary text-brand-secondary' : 'border-slate-200 dark:border-slate-700 text-slate-500'}`}>{role}</button>
                                    ))}
                                </div>
                            </div>
                        </div>
                    )}
                    {createStep === 1 && (
                        <div className="space-y-4 animate-slideUp">
                             <div>
                                <label className="text-xs font-bold text-slate-500 uppercase mb-2 block">Date</label>
                                <input type="date" value={newMatch.date} onChange={(e) => setNewMatch({...newMatch, date: e.target.value})} className="w-full bg-slate-100 dark:bg-slate-800 border-none rounded-xl p-3 text-slate-900 dark:text-white font-bold outline-none" />
                             </div>
                             <div>
                                 <label className="text-xs font-bold text-slate-500 uppercase mb-2 block">Select Venue</label>
                                 <div className="space-y-2 max-h-40 overflow-y-auto pr-2">
                                     {turfs.map(turf => (
                                         <div key={turf.id} onClick={() => setNewMatch({...newMatch, venueId: turf.id, time: ''})} className={`p-3 rounded-xl border flex justify-between items-center cursor-pointer ${newMatch.venueId === turf.id ? 'border-brand-secondary bg-brand-secondary/10' : 'border-slate-200 dark:border-slate-700'}`}>
                                             <div><p className="font-bold text-sm text-slate-900 dark:text-white">{turf.name}</p></div>
                                             <span className="text-xs font-bold text-brand-secondary">UGX {turf.pricePerHour.toLocaleString()}</span>
                                         </div>
                                     ))}
                                 </div>
                             </div>
                             {newMatch.venueId && (
                                 <div>
                                     <label className="text-xs font-bold text-slate-500 uppercase mb-2 block">Available Slots</label>
                                     <div className="grid grid-cols-4 gap-2">
                                         {availableSlots.length > 0 ? availableSlots.map(t => (
                                             <button key={t} onClick={() => setNewMatch({...newMatch, time: t})} className={`py-2 rounded-lg text-xs font-bold border ${newMatch.time === t ? 'bg-brand-secondary border-brand-secondary text-white' : 'border-slate-200 dark:border-slate-700 text-slate-500'}`}>{t}</button>
                                         )) : <p className="text-xs text-red-500 col-span-4">No slots available for this date.</p>}
                                     </div>
                                 </div>
                             )}
                        </div>
                    )}
                    {createStep === 2 && (
                        <div className="space-y-4 animate-slideUp">
                            <div className="bg-slate-100 dark:bg-slate-800 p-4 rounded-xl border border-slate-200 dark:border-slate-700">
                                <h4 className="font-bold text-slate-900 dark:text-white mb-4">Summary</h4>
                                <div className="space-y-2 text-sm">
                                    <div className="flex justify-between"><span className="text-slate-500">Match</span><span className="font-bold text-slate-900 dark:text-white">{newMatch.type} • {newMatch.format}</span></div>
                                    <div className="flex justify-between"><span className="text-slate-500">Venue</span><span className="font-bold text-slate-900 dark:text-white">{selectedTurf?.name}</span></div>
                                    <div className="flex justify-between"><span className="text-slate-500">Time</span><span className="font-bold text-slate-900 dark:text-white">{newMatch.date} @ {newMatch.time}</span></div>
                                </div>
                            </div>
                            <div>
                                <label className="text-xs font-bold text-slate-500 uppercase mb-2 block">Payment</label>
                                <div className="flex bg-slate-100 dark:bg-slate-800 p-1 rounded-xl">
                                    {['Split', 'Single'].map(mode => (
                                        <button key={mode} onClick={() => setNewMatch({...newMatch, paymentMode: mode})} className={`flex-1 py-2 rounded-lg text-sm font-bold transition-all ${newMatch.paymentMode === mode ? 'bg-white dark:bg-slate-700 text-slate-900 dark:text-white shadow-sm' : 'text-slate-500'}`}>{mode}</button>
                                    ))}
                                </div>
                                <p className="text-xs text-slate-400 mt-2 text-center">
                                    {newMatch.paymentMode === 'Split' ? `Est. UGX ${(selectedTurf ? Math.ceil((selectedTurf.pricePerHour * newMatch.duration) / 10) : 0).toLocaleString()} per person` : `Total UGX ${(selectedTurf ? selectedTurf.pricePerHour * newMatch.duration : 0).toLocaleString()}`}
                                </p>
                            </div>
                        </div>
                    )}
                </div>
                <div className="p-5 border-t border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-800 flex justify-between">
                    {createStep > 0 && <button onClick={() => setCreateStep(createStep - 1)} className="px-6 py-3 rounded-xl font-bold text-slate-500 hover:bg-slate-200 dark:hover:bg-slate-700">Back</button>}
                    <button onClick={() => createStep === 2 ? handleCreateSubmit() : setCreateStep(createStep + 1)} disabled={createStep === 1 && (!newMatch.venueId || !newMatch.time)} className={`px-8 py-3 bg-brand-secondary text-white rounded-xl font-bold shadow-lg flex items-center ml-auto ${createStep === 1 && (!newMatch.venueId || !newMatch.time) ? 'opacity-50' : 'hover:bg-emerald-600'}`}>
                        {createStep === 2 ? 'Create Match' : 'Next'} <ArrowRight size={18} className="ml-2" />
                    </button>
                </div>
            </div>
        </div>
    );
  };

  return (
    <Layout>
        {showCreateModal && <CreateMatchWizard />}
        <div className="p-5 pt-8 bg-brand-dark min-h-screen text-white pb-24">

            {/* Top Header */}
            <div className="flex items-center justify-between mb-6">
                <div>
                    <h1 className="text-2xl font-bold flex items-center">
                        <Sparkles className="mr-2 text-brand-secondary" /> Match Center
                    </h1>
                    <p className="text-slate-400 text-xs mt-1">AI-powered Matchmaking & Logistics</p>
                </div>
                <div className="bg-slate-800 p-2 rounded-xl border border-slate-700">
                    <img src={myTeam.logo} className="w-8 h-8 rounded-lg object-cover" />
                </div>
            </div>

            {/* Fallback Warning */}
            {fallbackTriggered && (
                <div className="bg-orange-500/10 border border-orange-500/50 rounded-xl p-4 mb-6 flex items-start animate-slideUp">
                    <AlertTriangle className="text-orange-500 mr-3 flex-shrink-0" size={20} />
                    <div>
                        <h3 className="font-bold text-orange-500 text-sm">No Active Teams Found</h3>
                        <p className="text-slate-400 text-xs mt-1">Try the "Open Play" tab to find individual games.</p>
                    </div>
                </div>
            )}

            {/* Main Tabs */}
            <div className="flex bg-slate-800 p-1 rounded-xl mb-6 border border-slate-700">
                <button 
                    onClick={() => { setActiveTab('rivals'); setMatches([]); }}
                    className={`flex-1 py-3 rounded-lg text-sm font-bold flex items-center justify-center transition-all ${activeTab === 'rivals' ? 'bg-slate-700 text-white shadow-sm' : 'text-slate-500 hover:text-slate-300'}`}
                >
                    <Swords size={16} className="mr-2" /> Rivals (Teams)
                </button>
                <button 
                    onClick={() => { setActiveTab('open'); setIsScanning(false); }}
                    className={`flex-1 py-3 rounded-lg text-sm font-bold flex items-center justify-center transition-all ${activeTab === 'open' ? 'bg-slate-700 text-white shadow-sm' : 'text-slate-500 hover:text-slate-300'}`}
                >
                    <Shuffle size={16} className="mr-2" /> Open Play
                </button>
            </div>

            {/* SCANNING OVERLAY */}
            {isScanning && (
                <div className="bg-slate-800/50 rounded-3xl p-8 border border-slate-700 text-center mb-8 flex flex-col items-center animate-pulse">
                    <Loader2 size={48} className="text-brand-secondary animate-spin mb-4" />
                    <h3 className="text-lg font-bold">{statusMessage}</h3>
                </div>
            )}

            {/* --- TAB 1: RIVALS --- */}
            {activeTab === 'rivals' && !isScanning && (
                <div className="animate-slideUp">
                    {matches.length === 0 ? (
                        <div className="bg-gradient-to-b from-slate-800 to-slate-900 rounded-3xl p-8 border border-slate-700 text-center relative overflow-hidden">
                             <div className="absolute inset-0 opacity-10" style={{ backgroundImage: 'radial-gradient(circle, #8b5cf6 1px, transparent 1px)', backgroundSize: '20px 20px' }}></div>
                             <Swords size={48} className="text-brand-secondary mx-auto mb-4" />
                             <h2 className="text-xl font-bold mb-2">Challenge a Team</h2>
                             <p className="text-slate-400 text-sm mb-6 max-w-xs mx-auto">AI will check venues and find a skill-matched opponent.</p>
                             <button onClick={handleRivalScan} className="bg-brand-secondary hover:bg-emerald-500 text-white font-bold py-4 px-8 rounded-xl shadow-lg transition-transform active:scale-95 flex items-center mx-auto">
                                <Zap size={20} className="mr-2 fill-current" /> Scan League
                            </button>
                        </div>
                    ) : (
                        <div className="space-y-6">
                            {/* Matches List */}
                            {matches.map((match, index) => (
                                <div key={match.id} className="bg-slate-800 rounded-3xl p-5 border border-slate-700 relative overflow-hidden group hover:border-brand-secondary transition-colors">
                                    <div className="absolute top-0 right-0 bg-slate-700 pl-4 pb-2 pt-2 pr-4 rounded-bl-3xl border-b border-l border-slate-600">
                                        <span className={`text-sm font-bold ${index === 0 ? 'text-brand-secondary' : 'text-slate-300'}`}>{match.matchScore}% Match</span>
                                    </div>
                                    <div className="flex items-center mb-6">
                                        <img src={match.opponent.logo} className="w-16 h-16 rounded-xl object-cover border-2 border-slate-600 mr-4" />
                                        <div>
                                            <h4 className="text-xl font-bold text-white mb-1">{match.opponent.name}</h4>
                                            <div className="flex items-center text-xs text-slate-400 font-medium">
                                                <MapPin size={12} className="mr-1 text-slate-500" /> {match.distance} • {match.venue.name}
