                                        </div>
                                    </div>
                                    <button onClick={() => navigate(`/turf/${match.venue.id}`)} className="w-full bg-brand-secondary text-white font-bold py-3 rounded-xl text-sm shadow-lg hover:bg-emerald-600 transition-colors flex items-center justify-center">
                                        <CheckCircle size={16} className="mr-2" /> Book {match.venue.name} @ {match.timeSlot}
                                    </button>
                                </div>
                            ))}
                        </div>
                    )}
                </div>
            )}

            {/* --- TAB 2: OPEN PLAY (Merged Pickup & Community) --- */}
            {activeTab === 'open' && !isScanning && (
                <div className="animate-slideUp">
                    {/* Action Buttons */}
                    <div className="grid grid-cols-2 gap-4 mb-6">
                        <button 
                            onClick={() => setShowCreateModal(true)}
                            className="bg-gradient-to-br from-brand-secondary to-emerald-700 p-4 rounded-2xl shadow-lg flex flex-col items-center justify-center group active:scale-[0.98] transition-all"
                        >
                            <div className="w-10 h-10 bg-white/20 rounded-full flex items-center justify-center mb-2 group-hover:bg-white/30">
                                <Plus size={24} className="text-white" />
                            </div>
                            <h3 className="font-bold text-sm">Create Match</h3>
                            <p className="text-[10px] text-emerald-100 opacity-80">Be the organizer</p>
                        </button>

                        <button 
                            onClick={handleGenerateLobby}
                            className="bg-slate-800 border border-slate-700 p-4 rounded-2xl flex flex-col items-center justify-center group active:scale-[0.98] transition-all hover:border-brand-secondary"
                        >
                            <div className="w-10 h-10 bg-slate-700 rounded-full flex items-center justify-center mb-2 group-hover:bg-slate-600 text-brand-secondary">
                                <BrainCircuit size={24} />
                            </div>
                            <h3 className="font-bold text-sm text-white">AI Lobby</h3>
                            <p className="text-[10px] text-slate-400">Quick auto-balance</p>
                        </button>
                    </div>

                    {/* AI Generated Lobby (Draft Card) */}
                    {generatedLobby && (
                        <div className="mb-8 animate-slideUp">
                             <div className="bg-slate-800 rounded-3xl p-1 border border-brand-secondary/50 shadow-xl shadow-brand-secondary/10">
                                <div className="bg-slate-900/50 rounded-[22px] p-5">
                                    <div className="flex items-center justify-between mb-4">
                                        <span className="text-brand-secondary text-xs font-bold uppercase tracking-wider flex items-center">
                                            <Sparkles size={12} className="mr-1" /> AI Drafted
                                        </span>
                                        <button onClick={() => setGeneratedLobby(null)}><X size={16} className="text-slate-500" /></button>
                                    </div>

                                    {/* Teams Visual */}
                                    <div className="flex justify-between items-center mb-6 px-2">
                                        <div className="text-center">
                                            <div className="text-2xl font-black text-white mb-1">{calculateTotalRating(generatedLobby.teamA)}</div>
                                            <div className="text-[10px] text-slate-400 uppercase">Team A</div>
                                        </div>
                                        <div className="text-slate-600 font-black text-lg">VS</div>
                                        <div className="text-center">
                                            <div className="text-2xl font-black text-white mb-1">{calculateTotalRating(generatedLobby.teamB)}</div>
                                            <div className="text-[10px] text-slate-400 uppercase">Team B</div>
                                        </div>
                                    </div>

                                    {/* Analysis */}
                                    <div className="bg-brand-secondary/10 p-3 rounded-xl mb-4 border border-brand-secondary/20">
                                        <p className="text-xs text-brand-secondary font-medium leading-relaxed">
                                            "{aiAnalysis}"
                                        </p>
                                    </div>

                                    {/* Logistics */}
                                    <div className="flex items-center justify-between text-sm text-slate-300 mb-4 bg-slate-800 p-3 rounded-xl">
                                        <div className="flex items-center"><MapPin size={12} className="mr-1"/> {generatedLobby.venue.name}</div>
                                        <div className="font-bold">UGX {generatedLobby.costPerPerson.toLocaleString()}</div>
                                    </div>

                                    <button 
                                        onClick={() => {
                                            // Convert to real community match
                                            handleCreateSubmit(); // Reuse logic but skip wizard
                                            setGeneratedLobby(null);
                                        }}
                                        className="w-full bg-white text-slate-900 font-bold py-3 rounded-xl hover:bg-slate-200"
                                    >
                                        Finalize & Book Match
                                    </button>
                                </div>
                             </div>
                        </div>
                    )}

                    {/* Community Feed */}
                    <div className="flex justify-between items-center mb-4">
                        <h3 className="font-bold text-white">Join a Game</h3>
                        <span className="text-xs text-slate-500">{communityMatches.length} active</span>
                    </div>

                    <div className="space-y-4">
                        {communityMatches.map(match => (
                            <div key={match.id} className="bg-slate-800 rounded-2xl p-5 border border-slate-700 relative overflow-hidden">
                                <div className="flex justify-between items-start mb-4">
                                    <div className="flex items-center">
                                        <img src={match.organizerAvatar} className="w-10 h-10 rounded-full border-2 border-slate-600 mr-3" />
                                        <div>
                                            <h4 className="font-bold text-white leading-tight">{match.title}</h4>
                                            <p className="text-xs text-slate-400">by {match.organizer}</p>
                                        </div>
                                    </div>
                                    <span className={`text-[10px] font-bold px-2 py-1 rounded-lg uppercase ${match.type === 'Competitive' ? 'bg-red-500/20 text-red-500' : 'bg-blue-500/20 text-blue-400'}`}>
                                        {match.type}
                                    </span>
                                </div>

                                <p className="text-sm text-slate-300 mb-4 bg-slate-900/50 p-3 rounded-xl italic">"{match.description}"</p>

                                <div className="grid grid-cols-2 gap-y-2 gap-x-4 text-sm mb-4">
                                    <div className="flex items-center text-slate-400"><Calendar size={14} className="mr-2 text-brand-secondary" /> {match.date}</div>
                                    <div className="flex items-center text-slate-400"><Clock size={14} className="mr-2 text-brand-secondary" /> {match.time}</div>
                                    <div className="flex items-center text-slate-400"><MapPin size={14} className="mr-2 text-brand-secondary" /> {match.venue.name}</div>
                                    <div className="flex items-center text-slate-400"><Wallet size={14} className="mr-2 text-brand-secondary" /> {match.costPerPerson > 0 ? `UGX ${match.costPerPerson.toLocaleString()}` : 'Free'}</div>
                                </div>

                                <div className="flex items-center justify-between pt-4 border-t border-slate-700">
                                    <div className="flex items-center space-x-2">
                                        <div className="flex -space-x-2">
                                            {[...Array(Math.min(3, match.joined))].map((_, i) => (
                                                <div key={i} className="w-8 h-8 rounded-full bg-slate-600 border-2 border-slate-800 flex items-center justify-center text-xs font-bold text-slate-300"><User size={12} /></div>
                                            ))}
                                        </div>
                                        <span className="text-xs text-slate-400">{match.joined}/{match.maxPlayers}</span>
                                    </div>
                                    <button 
                                        onClick={() => handleJoinMatch(match.id)}
                                        disabled={match.joined >= match.maxPlayers}
                                        className={`px-6 py-2 rounded-xl font-bold text-sm transition-colors ${match.joined >= match.maxPlayers ? 'bg-slate-700 text-slate-500' : 'bg-white text-slate-900 hover:bg-slate-200'}`}
                                    >
                                        {match.joined >= match.maxPlayers ? 'Full' : 'Join'}
                                    </button>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            )}
        </div>
    </Layout>
  );
};

