    const availableSlots = selectedTurf ? ['09:00', '10:00', '16:00', '17:00', '18:00', '19:00', '20:00'].filter(t => {
         return !bookings.some(b => b.turfId === selectedTurf.id && b.date === newMatch.date && b.time === t && b.status !== 'CANCELLED');
