                                    <p className="font-bold text-slate-900 dark:text-white flex items-center"><Calendar size={14} className="mr-2 text-brand-secondary" /> {newMatch.date}</p>
                                </div>
                                <div>
                                    <p className="text-slate-400 text-xs mb-1">Time</p>
                                    <p className="font-bold text-slate-900 dark:text-white flex items-center"><Clock size={14} className="mr-2 text-brand-secondary" /> {newMatch.time}</p>
                                </div>
                                <div>
                                    <p className="text-slate-400 text-xs mb-1">Format</p>
                                    <p className="font-bold text-slate-900 dark:text-white">{newMatch.format}</p>
                                </div>
                                <div>
                                    <p className="text-slate-400 text-xs mb-1">Type</p>
                                    <p className="font-bold text-slate-900 dark:text-white">{newMatch.type}</p>
                                </div>
                            </div>
