export const MatchCenter: React.FC = () => {
  const navigate = useNavigate();
  const { turfs, bookings, addBooking } = useBooking(); 
  const { addXP, stats } = useUser();

  // Tabs
  const [activeTab, setActiveTab] = useState<'rivals' | 'open'>('rivals');

  // UI States
  const [isScanning, setIsScanning] = useState(false);
  const [statusMessage, setStatusMessage] = useState("");

  // Create Match Full Page State
  const [isCreating, setIsCreating] = useState(false);
  const [createStep, setCreateStep] = useState(0); 

  // Create Match Local State
  const [turfSearchQuery, setTurfSearchQuery] = useState("");
  const [newMatch, setNewMatch] = useState({
      type: 'Friendly',
      format: '5-a-side',
      duration: 1, // Hours
      venueId: '',
      date: new Date().toISOString().split('T')[0],
      time: '',
      paymentMode: 'Split',
      roles: [] as string[],
      notes: ''
  });

  const [fallbackTriggered, setFallbackTriggered] = useState(false);

  // Data States
  const [matches, setMatches] = useState<SuggestedMatch[]>([]);

  const [communityMatches, setCommunityMatches] = useState<CommunityMatch[]>([
      {
          id: 'cm1',
          title: 'Sunday Morning Sweat',
          description: 'Casual game to start the day. Beginners welcome!',
          organizer: 'Coach Mike',
          organizerAvatar: 'https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?w=100&h=100&fit=crop',
          venue: turfs[0],
          date: '2025-01-20',
          time: '08:00',
          format: '5-a-side',
          joined: 7,
          maxPlayers: 10,
          costPerPerson: 5000,
          rolesNeeded: ['GK', 'Defender'],
          type: 'Friendly'
      },
      {
          id: 'cm2',
          title: 'Competitive 7v7',
          description: 'High intensity match. Bring your A-game.',
          organizer: 'Sarah K.',
          organizerAvatar: 'https://images.unsplash.com/photo-1438761681033-6461ffad8d80?w=100&h=100&fit=crop',
          venue: turfs[2],
          date: '2025-01-20',
          time: '19:00',
          format: '7-a-side',
          joined: 12,
          maxPlayers: 14,
          costPerPerson: 8000,
          rolesNeeded: ['Striker'],
          type: 'Competitive'
      }
  ]);

  const myTeam = MY_TEAMS[0];

  // --- HELPERS ---

  // Filter Turfs for Search
  const filteredTurfs = useMemo(() => {
      if (!turfSearchQuery) return turfs;
      return turfs.filter(t => 
          t.name.toLowerCase().includes(turfSearchQuery.toLowerCase()) ||
          t.location.toLowerCase().includes(turfSearchQuery.toLowerCase())
      );
  }, [turfs, turfSearchQuery]);

  // Dynamic Time Slots based on Venue Hours + Duration Availability
  const getAvailableSlots = (turfId: string, date: string, duration: number) => {
      const turf = turfs.find(t => t.id === turfId);
      if (!turf) return [];

      const startHour = parseInt(turf.openingHour.split(':')[0]);
      const endHour = parseInt(turf.closingHour.split(':')[0]);
      const slots = [];

      // Check if date is blocked
      if (turf.blockedDates.includes(date)) return [];

      for (let i = startHour; i <= endHour - duration; i++) {
          const time = `${i.toString().padStart(2, '0')}:00`;

          // Check if ANY hour in the duration is booked
          let isBlocked = false;
          for (let d = 0; d < duration; d++) {
             const checkTime = `${(i + d).toString().padStart(2, '0')}:00`;
             const booked = bookings.some(b => 
                b.turfId === turfId && 
                b.date === date && 
                b.time === checkTime &&
                b.status !== 'CANCELLED'
             );
             if (booked) isBlocked = true;
          }

          if (!isBlocked) slots.push(time);
      }
      return slots;
  };

  const findNextAvailableSlot = (turf: Turf): string | null => {
      const today = new Date().toISOString().split('T')[0];
      const slots = getAvailableSlots(turf.id, today, 1);
      return slots.length > 0 ? slots[0] : null;
  };

  const calculateWinRate = (wins: number, totalGames: number = 24) => Math.round((wins / totalGames) * 100);

  // --- ACTIONS ---

  const handleJoinMatch = (matchId: string) => {
      setCommunityMatches(prev => prev.map(m => {
          if (m.id === matchId && m.joined < m.maxPlayers) {
              addXP(50); // Join Bonus
              return { ...m, joined: m.joined + 1 };
          }
          return m;
      }));
  };

  const handleCreateSubmit = async () => {
      setIsScanning(true); 

      const selectedTurf = turfs.find(t => t.id === newMatch.venueId) || turfs[0];
      const maxP = newMatch.format === '5-a-side' ? 10 : newMatch.format === '7-a-side' ? 14 : 22;
      const totalCost = selectedTurf.pricePerHour * newMatch.duration;
      const costPerPerson = newMatch.paymentMode === 'Split' ? Math.ceil(totalCost / maxP) : 0;

      // 1. Create System Booking
      const bookingId = Math.random().toString(36).substr(2, 9).toUpperCase();
      addBooking({
          id: bookingId,
          turfId: selectedTurf.id,
          turfName: selectedTurf.name,
          userName: 'You (Organizer)',
          date: newMatch.date,
          time: newMatch.time,
          duration: newMatch.duration,
          status: 'CONFIRMED',
          price: totalCost,
          createdAt: new Date().toISOString()
      });

      // 2. AI Gen Title (using provided notes if available)
      let aiTitle = `${newMatch.type} at ${selectedTurf.name}`;
      let aiDesc = newMatch.notes || "Join us for a great game!";

      if (!newMatch.notes) {
          try {
              const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
              const prompt = `Generate a 3-4 word exciting title and 1 sentence description for a ${newMatch.type} football match at ${selectedTurf.name}.`;
              const result = await ai.models.generateContent({ model: 'gemini-3-flash-preview', contents: prompt });
              const text = result.text || "";
              const lines = text.split('\n').filter(l => l);
              if (lines.length > 0) aiTitle = lines[0].replace(/"/g, '');
              if (lines.length > 1) aiDesc = lines[1];
          } catch (e) { console.error(e); }
      }

      const newCommunityMatch: CommunityMatch = {
          id: bookingId,
          title: aiTitle,
          description: aiDesc,
          organizer: 'You',
          organizerAvatar: 'https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?w=100&h=100&fit=crop',
          venue: selectedTurf,
          date: newMatch.date,
          time: newMatch.time,
          format: newMatch.format,
          joined: 1,
          maxPlayers: maxP,
          costPerPerson: costPerPerson,
          rolesNeeded: newMatch.roles,
          type: newMatch.type as any
      };

      setTimeout(() => {
          setCommunityMatches([newCommunityMatch, ...communityMatches]);
          setIsScanning(false);
          addXP(200);
          setIsCreating(false); 
          setActiveTab('open');
          // Reset Form
          setNewMatch({ ...newMatch, time: '', venueId: '', notes: '', roles: [] });
          setCreateStep(0);
      }, 2000);
  };

  const handleRivalScan = async () => {
      setIsScanning(true);
      setMatches([]);
      setStatusMessage("Analyzing League Data...");

      setTimeout(async () => {
        const myWinRate = calculateWinRate(myTeam.wins);
        const validMatches: SuggestedMatch[] = [];

        for (const opponent of TEAM_LEADERBOARD) {
            if (opponent.name === myTeam.name) continue;
            const randomTurfIndex = Math.floor(Math.random() * turfs.length);
            const potentialVenue = turfs[randomTurfIndex];
            const openSlot = findNextAvailableSlot(potentialVenue);

            if (openSlot) {
                const oppWinRate = calculateWinRate(opponent.wins);
                const skillDiff = Math.abs(myWinRate - oppWinRate);
                const matchScore = Math.max(0, 100 - (skillDiff * 3)); 

                if (matchScore > 60) {
                    validMatches.push({
                        id: opponent.id,
                        opponent,
                        matchScore,
                        distance: potentialVenue.distance,
                        winRate: oppWinRate,
                        lossRate: 100 - oppWinRate,
                        venue: potentialVenue,
                        timeSlot: openSlot,
                        splitPrice: Math.ceil(potentialVenue.pricePerHour / 2) 
                    });
                }
            }
        }
        validMatches.sort((a, b) => b.matchScore - a.matchScore);
        const topMatches = validMatches.slice(0, 2);

        if (topMatches.length === 0) setFallbackTriggered(true);
        else setMatches(topMatches);

        setIsScanning(false);
      }, 2000);
  };

  // --- SUB-RENDER: CREATE MATCH PAGE ---
  const renderCreateMatchPage = () => {
    const selectedTurf = turfs.find(t => t.id === newMatch.venueId);

    // Get Available Time Slots dynamically
    const availableSlots = selectedTurf 
        ? getAvailableSlots(selectedTurf.id, newMatch.date, newMatch.duration)
        : [];

    const totalCost = selectedTurf ? selectedTurf.pricePerHour * newMatch.duration : 0;
    const maxPlayers = newMatch.format === '5-a-side' ? 10 : newMatch.format === '7-a-side' ? 14 : 22;

    if (isScanning) {
        return (
            <div className="flex flex-col items-center justify-center min-h-[80vh] bg-slate-50 dark:bg-brand-dark p-5">
                <div className="relative">
                    <div className="w-24 h-24 rounded-full border-4 border-slate-200 dark:border-slate-700 animate-spin border-t-brand-secondary"></div>
                    <div className="absolute inset-0 flex items-center justify-center">
                        <Sparkles className="text-brand-secondary animate-pulse" size={32} />
                    </div>
                </div>
                <h2 className="mt-8 text-2xl font-bold text-slate-900 dark:text-white">Organizing Match...</h2>
                <p className="text-slate-500 dark:text-slate-400 mt-2 text-center max-w-xs">
                    Booking {selectedTurf?.name}, generating invites, and balancing teams.
                </p>
            </div>
        )
    }

    return (
        <div className="min-h-screen bg-slate-50 dark:bg-brand-dark pb-32 animate-fadeIn">
            {/* Header */}
            <div className="sticky top-0 z-30 bg-white/80 dark:bg-brand-dark/80 backdrop-blur-md border-b border-slate-200 dark:border-slate-800 p-4 flex items-center justify-between">
                <button 
                    onClick={() => {
                        if(createStep > 0) setCreateStep(createStep - 1);
                        else setIsCreating(false);
                    }}
                    className="p-2 rounded-full hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors"
                >
                    <ArrowLeft className="text-slate-900 dark:text-white" />
                </button>
                <div className="flex flex-col items-center">
                    <h2 className="text-slate-900 dark:text-white font-bold">Create Match</h2>
                    <div className="flex space-x-1 mt-1">
                        {[0, 1, 2].map(s => (
                            <div key={s} className={`w-2 h-2 rounded-full transition-colors ${s === createStep ? 'bg-brand-secondary' : 'bg-slate-300 dark:bg-slate-700'}`} />
                        ))}
                    </div>
                </div>
                <div className="w-10" />
            </div>

            <div className="p-5 max-w-2xl mx-auto">
                {createStep === 0 && (
                    <div className="space-y-8 animate-slideUp">
                        {/* Match Type */}
                        <div>
                            <h3 className="text-xl font-bold text-slate-900 dark:text-white mb-4">What kind of match?</h3>
                            <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
                                {['Friendly', 'Competitive', 'Pickup'].map(type => (
                                    <button 
                                        key={type}
                                        onClick={() => setNewMatch({...newMatch, type})}
                                        className={`p-6 rounded-2xl border-2 text-left transition-all relative overflow-hidden group ${
                                            newMatch.type === type 
                                            ? 'border-brand-secondary bg-brand-secondary/5' 
                                            : 'border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 hover:border-brand-secondary/50'
                                        }`}
                                    >
                                        <div className={`w-12 h-12 rounded-full flex items-center justify-center mb-4 ${newMatch.type === type ? 'bg-brand-secondary text-white' : 'bg-slate-100 dark:bg-slate-700 text-slate-500'}`}>
                                            {type === 'Friendly' && <Users size={24} />}
                                            {type === 'Competitive' && <Trophy size={24} />}
                                            {type === 'Pickup' && <Shuffle size={24} />}
                                        </div>
                                        <h4 className="font-bold text-slate-900 dark:text-white text-lg">{type}</h4>
                                        <p className="text-xs text-slate-500 mt-1">
                                            {type === 'Friendly' ? 'Casual play with friends' : type === 'Competitive' ? 'Ranked match for XP' : 'Open to everyone'}
                                        </p>
                                        {newMatch.type === type && <div className="absolute top-4 right-4 text-brand-secondary"><CheckCircle size={20} /></div>}
                                    </button>
                                ))}
                            </div>
                        </div>

                        {/* Format */}
                        <div>
                            <h3 className="text-lg font-bold text-slate-900 dark:text-white mb-4">Format</h3>
                            <div className="flex gap-3 overflow-x-auto pb-2 scrollbar-hide">
                                {['5-a-side', '7-a-side', '11-a-side'].map(fmt => (
                                    <button 
                                        key={fmt}
                                        onClick={() => setNewMatch({...newMatch, format: fmt})}
                                        className={`px-6 py-3 rounded-xl font-bold border transition-all whitespace-nowrap ${
                                            newMatch.format === fmt 
                                            ? 'bg-brand-secondary text-white border-brand-secondary shadow-lg' 
                                            : 'bg-white dark:bg-slate-800 text-slate-500 border-slate-200 dark:border-slate-700'
                                        }`}
                                    >
                                        {fmt}
                                    </button>
                                ))}
                            </div>
                        </div>

                        {/* Roles */}
                        <div>
                            <h3 className="text-lg font-bold text-slate-900 dark:text-white mb-4">Positions Needed</h3>
                            <div className="flex flex-wrap gap-3">
                                {['GK', 'Defender', 'Midfielder', 'Striker'].map(role => (
                                    <button
                                        key={role}
                                        onClick={() => {
                                            const roles = newMatch.roles.includes(role) 
                                            ? newMatch.roles.filter(r => r !== role)
                                            : [...newMatch.roles, role];
                                            setNewMatch({...newMatch, roles});
                                        }}
                                        className={`px-4 py-2 rounded-full text-sm font-bold border flex items-center transition-all ${
                                            newMatch.roles.includes(role) 
                                            ? 'bg-brand-secondary/10 border-brand-secondary text-brand-secondary' 
                                            : 'border-slate-200 dark:border-slate-700 text-slate-500'
                                        }`}
                                    >
                                        {newMatch.roles.includes(role) ? <Plus size={14} className="mr-1 rotate-45" /> : <Plus size={14} className="mr-1" />}
                                        {role}
                                    </button>
                                ))}
                            </div>
                        </div>
                    </div>
                )}

                {createStep === 1 && (
                    <div className="space-y-8 animate-slideUp">
                        {/* Date & Duration */}
                        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                            <div>
                                <label className="text-xs font-bold text-slate-500 uppercase mb-2 block">Date</label>
                                <div className="relative">
                                    <Calendar className="absolute left-4 top-4 text-slate-400" size={20} />
                                    <input 
                                        type="date" 
                                        value={newMatch.date}
                                        onChange={(e) => setNewMatch({...newMatch, date: e.target.value, time: ''})}
                                        className="w-full bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl p-4 pl-12 text-lg font-bold text-slate-900 dark:text-white focus:ring-2 focus:ring-brand-secondary outline-none"
                                    />
                                </div>
                            </div>
                            <div>
                                <label className="text-xs font-bold text-slate-500 uppercase mb-2 block">Duration</label>
                                <div className="flex gap-2">
                                    {[1, 1.5, 2].map(d => (
                                        <button 
                                            key={d}
                                            onClick={() => setNewMatch({...newMatch, duration: d, time: ''})} // Reset time on duration change
                                            className={`flex-1 py-4 rounded-2xl font-bold border transition-all ${
                                                newMatch.duration === d 
                                                ? 'bg-brand-secondary border-brand-secondary text-white' 
                                                : 'bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-700 text-slate-500'
                                            }`}
                                        >
                                            {d}h
                                        </button>
                                    ))}
                                </div>
                            </div>
                        </div>

                        {/* Turf Selection with Search */}
                        <div>
                            <div className="flex justify-between items-center mb-4">
                                <h3 className="text-lg font-bold text-slate-900 dark:text-white">Select Venue</h3>
                                {/* Search Bar */}
                                <div className="relative w-1/2">
                                    <input 
                                        type="text" 
                                        placeholder="Search turf..." 
                                        value={turfSearchQuery}
                                        onChange={(e) => setTurfSearchQuery(e.target.value)}
                                        className="w-full bg-slate-100 dark:bg-slate-800 border-none rounded-lg py-2 pl-8 pr-3 text-xs text-slate-900 dark:text-white focus:ring-1 focus:ring-brand-secondary outline-none"
                                    />
                                    <Search className="absolute left-2.5 top-2.5 text-slate-400" size={12} />
                                </div>
                            </div>

                            <div className="space-y-4 max-h-[300px] overflow-y-auto pr-1">
                                {filteredTurfs.map(turf => (
                                    <div 
                                        key={turf.id}
                                        onClick={() => setNewMatch({...newMatch, venueId: turf.id, time: ''})}
                                        className={`flex rounded-2xl border cursor-pointer overflow-hidden transition-all ${
                                            newMatch.venueId === turf.id 
                                            ? 'border-brand-secondary ring-2 ring-brand-secondary/30 bg-brand-secondary/5' 
                                            : 'border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800'
                                        }`}
                                    >
                                        <div className="w-24 h-24 sm:w-32 sm:h-auto bg-slate-200">
                                            <img src={turf.image} className="w-full h-full object-cover" />
                                        </div>
                                        <div className="p-4 flex-1 flex flex-col justify-center">
                                            <div className="flex justify-between items-start mb-1">
                                                <h4 className="font-bold text-slate-900 dark:text-white">{turf.name}</h4>
                                                {newMatch.venueId === turf.id && <CheckCircle size={20} className="text-brand-secondary" />}
                                            </div>
                                            <p className="text-xs text-slate-500 mb-2">{turf.location}</p>
                                            <div className="flex items-center space-x-3 text-xs">
                                                <span className="font-bold text-brand-secondary">UGX {turf.pricePerHour.toLocaleString()}/hr</span>
                                                <span className="flex items-center text-slate-400"><Star size={12} className="mr-1 fill-current text-yellow-400" /> {turf.rating}</span>
                                            </div>
                                        </div>
                                    </div>
                                ))}
                                {filteredTurfs.length === 0 && (
                                    <p className="text-center text-sm text-slate-400 py-4">No venues found matching "{turfSearchQuery}"</p>
                                )}
                            </div>
                        </div>

                        {/* Time Slots */}
                        {newMatch.venueId && (
                            <div className="animate-fadeIn">
                                <h3 className="text-lg font-bold text-slate-900 dark:text-white mb-4">Available Slots ({newMatch.duration}h)</h3>
                                <div className="grid grid-cols-3 sm:grid-cols-4 gap-3">
                                    {availableSlots.length > 0 ? availableSlots.map(t => (
                                        <button
                                            key={t}
                                            onClick={() => setNewMatch({...newMatch, time: t})}
                                            className={`py-3 rounded-xl text-sm font-bold border transition-all ${
                                                newMatch.time === t 
                                                ? 'bg-brand-secondary border-brand-secondary text-white shadow-md' 
                                                : 'bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-700 text-slate-600 dark:text-slate-300'
                                            }`}
                                        >
                                            {t}
                                        </button>
                                    )) : (
                                        <div className="col-span-full p-4 bg-red-500/10 border border-red-500/20 rounded-xl text-red-500 text-sm flex items-center justify-center">
                                            <AlertTriangle size={16} className="mr-2" /> No slots available for this duration.
                                        </div>
                                    )}
                                </div>
                            </div>
                        )}
                    </div>
                )}

                {createStep === 2 && (
                    <div className="space-y-6 animate-slideUp">
                        {/* Summary Card */}
                        <div className="bg-white dark:bg-slate-800 rounded-3xl p-6 border border-slate-200 dark:border-slate-700 shadow-xl relative overflow-hidden">
                            <div className="absolute top-0 right-0 w-32 h-32 bg-brand-secondary/10 rounded-full -mr-16 -mt-16 blur-2xl"></div>

                            <h3 className="text-slate-500 text-xs font-bold uppercase tracking-widest mb-6">Match Summary</h3>

                            <div className="flex items-start mb-6">
                                <div className="w-16 h-16 rounded-2xl overflow-hidden mr-4 border border-slate-200 dark:border-slate-700">
                                    <img src={selectedTurf?.image} className="w-full h-full object-cover" />
                                </div>
                                <div>
                                    <h2 className="text-xl font-bold text-slate-900 dark:text-white mb-1">{selectedTurf?.name}</h2>
                                    <p className="text-slate-500 text-sm flex items-center"><MapPin size={12} className="mr-1" /> {selectedTurf?.location}</p>
                                </div>
                            </div>

                            <div className="grid grid-cols-2 gap-y-4 gap-x-8 text-sm border-t border-slate-100 dark:border-slate-700 pt-6">
                                <div>
                                    <p className="text-slate-400 text-xs mb-1">Date</p>
                                    <p className="font-bold text-slate-900 dark:text-white flex items-center"><Calendar size={14} className="mr-2 text-brand-secondary" /> {newMatch.date}</p>
                                </div>
                                <div>
                                    <p className="text-slate-400 text-xs mb-1">Time</p>
                                    <p className="font-bold text-slate-900 dark:text-white flex items-center"><Clock size={14} className="mr-2 text-brand-secondary" /> {newMatch.time} ({newMatch.duration}h)</p>
                                </div>
                                <div>
                                    <p className="text-slate-400 text-xs mb-1">Format</p>
                                    <p className="font-bold text-slate-900 dark:text-white">{newMatch.format}</p>
                                </div>
                                <div>
                                    <p className="text-slate-400 text-xs mb-1">Type</p>
                                    <p className="font-bold text-slate-900 dark:text-white">{newMatch.type}</p>
                                </div>
                            </div>
                        </div>

                        {/* Match Notes */}
                         <div>
                             <label className="text-xs font-bold text-slate-500 uppercase mb-2 block">Match Notes / Instructions</label>
                             <textarea 
                                value={newMatch.notes}
                                onChange={(e) => setNewMatch({...newMatch, notes: e.target.value})}
                                placeholder="e.g. Bring white bibs, cash for parking..."
                                className="w-full bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl p-3 text-sm text-slate-900 dark:text-white focus:ring-2 focus:ring-brand-secondary outline-none h-20 resize-none"
                             />
                        </div>

                        {/* Payment Section */}
                        <div className="bg-slate-50 dark:bg-slate-900 rounded-3xl p-6 border border-slate-200 dark:border-slate-700">
                            <h3 className="text-slate-900 dark:text-white font-bold mb-4 flex items-center">
                                <CreditCard className="mr-2" size={20} /> Payment
                            </h3>

                            <div className="flex bg-white dark:bg-slate-800 p-1 rounded-xl mb-4 border border-slate-200 dark:border-slate-700">
                                {['Split', 'Single'].map(mode => (
                                    <button 
                                        key={mode}
                                        onClick={() => setNewMatch({...newMatch, paymentMode: mode})}
                                        className={`flex-1 py-3 rounded-lg text-sm font-bold transition-all ${
                                            newMatch.paymentMode === mode 
                                            ? 'bg-brand-secondary text-white shadow-sm' 
                                            : 'text-slate-500 dark:text-slate-400'
                                        }`}
                                    >
                                        {mode} Payment
                                    </button>
                                ))}
                            </div>

                            <div className="flex justify-between items-center p-4 bg-white dark:bg-slate-800 rounded-xl border border-slate-200 dark:border-slate-700">
                                <div>
                                    <p className="text-xs text-slate-400 mb-1">
                                        {newMatch.paymentMode === 'Split' ? `Cost per person (/${maxPlayers})` : 'Total Cost'}
                                    </p>
                                    <p className="text-xl font-bold text-slate-900 dark:text-white">
                                        UGX {(newMatch.paymentMode === 'Split' ? Math.ceil(totalCost / maxPlayers) : totalCost).toLocaleString()}
                                    </p>
                                </div>
                                <Info size={20} className="text-slate-400" />
                            </div>

                            {newMatch.paymentMode === 'Split' && (
                                <p className="text-xs text-center text-slate-400 mt-4">
                                    You will be charged for your share now. Teammates pay when they join.
                                </p>
                            )}
                        </div>
                    </div>
                )}
            </div>

            {/* Floating Footer Action */}
            <div className="fixed bottom-0 left-0 w-full bg-white dark:bg-brand-surface border-t border-slate-200 dark:border-slate-700 p-5 z-40 safe-area-bottom">
                 <button 
                    onClick={() => createStep === 2 ? handleCreateSubmit() : setCreateStep(createStep + 1)}
                    disabled={createStep === 1 && (!newMatch.venueId || !newMatch.time)}
                    className="w-full bg-brand-secondary text-white py-4 rounded-xl font-bold text-lg shadow-lg hover:bg-emerald-600 disabled:opacity-50 disabled:scale-100 transition-all active:scale-[0.98] flex items-center justify-center"
                 >
                     {createStep === 2 ? 'Confirm & Create Match' : 'Continue'}
                     {createStep !== 2 && <ArrowRight size={20} className="ml-2" />}
                 </button>
            </div>
        </div>
    );
  };

  return (
    <Layout>
        {isCreating ? renderCreateMatchPage() : (
            <div className="p-5 pt-8 bg-brand-dark min-h-screen text-white pb-24">

                {/* Top Header */}
                <div className="flex items-center justify-between mb-6">
                    <div>
                        <h1 className="text-2xl font-bold flex items-center">
                            <Sparkles className="mr-2 text-brand-secondary" /> Match Center
                        </h1>
                        <p className="text-slate-400 text-xs mt-1">AI-powered Matchmaking & Logistics</p>
                    </div>
                    <div className="bg-slate-800 p-2 rounded-xl border border-slate-700">
                        <img src={myTeam.logo} className="w-8 h-8 rounded-lg object-cover" />
                    </div>
                </div>

                {/* Fallback Warning */}
                {fallbackTriggered && (
                    <div className="bg-orange-500/10 border border-orange-500/50 rounded-xl p-4 mb-6 flex items-start animate-slideUp">
                        <AlertTriangle className="text-orange-500 mr-3 flex-shrink-0" size={20} />
                        <div>
                            <h3 className="font-bold text-orange-500 text-sm">No Active Teams Found</h3>
                            <p className="text-slate-400 text-xs mt-1">Try the "Open Play" tab to find individual games.</p>
                        </div>
                    </div>
                )}

                {/* Main Tabs */}
                <div className="flex bg-slate-800 p-1 rounded-xl mb-6 border border-slate-700">
                    <button 
                        onClick={() => { setActiveTab('rivals'); setMatches([]); }}
                        className={`flex-1 py-3 rounded-lg text-sm font-bold flex items-center justify-center transition-all ${activeTab === 'rivals' ? 'bg-slate-700 text-white shadow-sm' : 'text-slate-500 hover:text-slate-300'}`}
                    >
                        <Swords size={16} className="mr-2" /> Rivals (Teams)
                    </button>
                    <button 
                        onClick={() => { setActiveTab('open'); setIsScanning(false); }}
                        className={`flex-1 py-3 rounded-lg text-sm font-bold flex items-center justify-center transition-all ${activeTab === 'open' ? 'bg-slate-700 text-white shadow-sm' : 'text-slate-500 hover:text-slate-300'}`}
                    >
                        <Shuffle size={16} className="mr-2" /> Open Play
                    </button>
                </div>

                {/* SCANNING OVERLAY */}
                {isScanning && !isCreating && (
                    <div className="bg-slate-800/50 rounded-3xl p-8 border border-slate-700 text-center mb-8 flex flex-col items-center animate-pulse">
                        <Loader2 size={48} className="text-brand-secondary animate-spin mb-4" />
                        <h3 className="text-lg font-bold">{statusMessage}</h3>
                    </div>
                )}

                {/* --- TAB 1: RIVALS --- */}
                {activeTab === 'rivals' && !isScanning && (
                    <div className="animate-slideUp">
                        {matches.length === 0 ? (
                            <div className="bg-gradient-to-b from-slate-800 to-slate-900 rounded-3xl p-8 border border-slate-700 text-center relative overflow-hidden">
                                <div className="absolute inset-0 opacity-10" style={{ backgroundImage: 'radial-gradient(circle, #8b5cf6 1px, transparent 1px)', backgroundSize: '20px 20px' }}></div>
                                <Swords size={48} className="text-brand-secondary mx-auto mb-4" />
                                <h2 className="text-xl font-bold mb-2">Challenge a Team</h2>
                                <p className="text-slate-400 text-sm mb-6 max-w-xs mx-auto">AI will check venues and find a skill-matched opponent.</p>
                                <button onClick={handleRivalScan} className="bg-brand-secondary hover:bg-emerald-500 text-white font-bold py-4 px-8 rounded-xl shadow-lg transition-transform active:scale-95 flex items-center mx-auto">
                                    <Zap size={20} className="mr-2 fill-current" /> Scan League
                                </button>
                            </div>
                        ) : (
                            <div className="space-y-6">
                                {/* Matches List */}
                                {matches.map((match, index) => (
                                    <div key={match.id} className="bg-slate-800 rounded-3xl p-5 border border-slate-700 relative overflow-hidden group hover:border-brand-secondary transition-colors">
                                        <div className="absolute top-0 right-0 bg-slate-700 pl-4 pb-2 pt-2 pr-4 rounded-bl-3xl border-b border-l border-slate-600">
                                            <span className={`text-sm font-bold ${index === 0 ? 'text-brand-secondary' : 'text-slate-300'}`}>{match.matchScore}% Match</span>
                                        </div>
                                        <div className="flex items-center mb-6">
                                            <img src={match.opponent.logo} className="w-16 h-16 rounded-xl object-cover border-2 border-slate-600 mr-4" />
                                            <div>
                                                <h4 className="text-xl font-bold text-white mb-1">{match.opponent.name}</h4>
                                                <div className="flex items-center text-xs text-slate-400 font-medium">
                                                    <MapPin size={12} className="mr-1 text-slate-500" /> {match.distance} • {match.venue.name}
                                                </div>
                                            </div>
                                        </div>
                                        <button onClick={() => navigate(`/turf/${match.venue.id}`)} className="w-full bg-brand-secondary text-white font-bold py-3 rounded-xl text-sm shadow-lg hover:bg-emerald-600 transition-colors flex items-center justify-center">
                                            <CheckCircle size={16} className="mr-2" /> Book {match.venue.name} @ {match.timeSlot}
                                        </button>
                                    </div>
                                ))}
                            </div>
                        )}
                    </div>
                )}

                {/* --- TAB 2: OPEN PLAY (Merged Pickup & Community) --- */}
                {activeTab === 'open' && !isScanning && (
                    <div className="animate-slideUp">

                        {/* Stats Dashboard */}
                        <div className="bg-gradient-to-br from-slate-800 to-slate-900 rounded-3xl p-6 border border-slate-700 mb-6 relative overflow-hidden shadow-lg">
                            <div className="absolute top-0 right-0 p-4 opacity-5">
                                <Trophy size={100} className="text-white" />
                            </div>

                            <div className="relative z-10 flex justify-between items-start mb-6">
                                <div>
                                    <div className="flex items-center space-x-2 mb-1">
                                        <span className="bg-brand-secondary/20 text-brand-secondary text-[10px] font-bold px-2 py-0.5 rounded-full flex items-center">
                                            <Zap size={10} className="mr-1 fill-current" /> LEVEL {stats.level}
                                        </span>
                                        <span className="text-slate-400 text-xs font-medium">Midfielder</span>
                                    </div>
                                    <h2 className="text-3xl font-black text-white italic tracking-tight">RANK #{stats.rank}</h2>
                                </div>

                                <div className="w-12 h-12 rounded-full border-2 border-slate-600 overflow-hidden bg-slate-800">
                                    <img src="https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?w=100&h=100&fit=crop" className="w-full h-full object-cover" />
                                </div>
                            </div>

                            <div className="relative z-10 grid grid-cols-3 gap-3">
                                <div className="bg-slate-950/30 rounded-xl p-3 border border-white/5 backdrop-blur-sm">
                                    <p className="text-slate-400 text-[10px] uppercase font-bold mb-1">Matches</p>
                                    <p className="text-white font-bold text-xl">{stats.totalGames}</p>
                                </div>
                                <div className="bg-slate-950/30 rounded-xl p-3 border border-white/5 backdrop-blur-sm">
                                    <p className="text-slate-400 text-[10px] uppercase font-bold mb-1">Win Rate</p>
                                    <p className="text-emerald-400 font-bold text-xl">64%</p>
                                </div>
                                <div className="bg-slate-950/30 rounded-xl p-3 border border-white/5 backdrop-blur-sm">
                                    <p className="text-slate-400 text-[10px] uppercase font-bold mb-1">Form</p>
                                    <div className="flex items-center space-x-0.5 h-7">
                                        <div className="w-1.5 h-4 bg-emerald-500 rounded-full"></div>
                                        <div className="w-1.5 h-6 bg-emerald-500 rounded-full"></div>
                                        <div className="w-1.5 h-3 bg-red-500 rounded-full opacity-50"></div>
                                        <div className="w-1.5 h-5 bg-emerald-500 rounded-full"></div>
                                    </div>
                                </div>
                            </div>
                        </div>

                        {/* Create Match Action */}
                        <button 
                            onClick={() => {
                                setCreateStep(0);
                                setIsCreating(true);
                            }}
                            className="w-full bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 p-4 rounded-2xl shadow-sm mb-8 flex items-center justify-between group active:scale-[0.98] transition-all hover:border-brand-secondary"
                        >
                            <div className="flex items-center">
                                <div className="w-12 h-12 bg-gradient-to-tr from-brand-secondary to-emerald-600 rounded-full flex items-center justify-center mr-4 shadow-lg shadow-emerald-500/30 group-hover:scale-110 transition-transform">
                                    <Plus size={24} className="text-white" />
                                </div>
                                <div className="text-left">
                                    <h3 className="font-bold text-slate-900 dark:text-white text-lg">Create a Match</h3>
                                    <p className="text-slate-500 dark:text-slate-400 text-xs">Organize a game, earn 200 XP</p>
                                </div>
                            </div>
                            <div className="bg-slate-100 dark:bg-slate-700 p-2 rounded-full">
                                <ArrowRight className="text-slate-400 dark:text-slate-300" size={20} />
                            </div>
                        </button>

                        {/* Community Feed */}
                        <div className="flex justify-between items-center mb-4">
                            <h3 className="font-bold text-white">Join a Game</h3>
                            <span className="text-xs text-slate-500">{communityMatches.length} active</span>
                        </div>

                        <div className="space-y-4">
                            {communityMatches.map(match => (
                                <div key={match.id} className="bg-slate-800 rounded-2xl p-5 border border-slate-700 relative overflow-hidden">
                                    <div className="flex justify-between items-start mb-4">
                                        <div className="flex items-center">
                                            <img src={match.organizerAvatar} className="w-10 h-10 rounded-full border-2 border-slate-600 mr-3" />
                                            <div>
                                                <h4 className="font-bold text-white leading-tight">{match.title}</h4>
                                                <p className="text-xs text-slate-400">by {match.organizer}</p>
                                            </div>
                                        </div>
                                        <span className={`text-[10px] font-bold px-2 py-1 rounded-lg uppercase ${match.type === 'Competitive' ? 'bg-red-500/20 text-red-500' : 'bg-blue-500/20 text-blue-400'}`}>
                                            {match.type}
                                        </span>
                                    </div>

                                    <p className="text-sm text-slate-300 mb-4 bg-slate-900/50 p-3 rounded-xl italic">"{match.description}"</p>

                                    <div className="grid grid-cols-2 gap-y-2 gap-x-4 text-sm mb-4">
                                        <div className="flex items-center text-slate-400"><Calendar size={14} className="mr-2 text-brand-secondary" /> {match.date}</div>
                                        <div className="flex items-center text-slate-400"><Clock size={14} className="mr-2 text-brand-secondary" /> {match.time}</div>
                                        <div className="flex items-center text-slate-400"><MapPin size={14} className="mr-2 text-brand-secondary" /> {match.venue.name}</div>
                                        <div className="flex items-center text-slate-400"><Wallet size={14} className="mr-2 text-brand-secondary" /> {match.costPerPerson > 0 ? `UGX ${match.costPerPerson.toLocaleString()}` : 'Free'}</div>
                                    </div>

                                    <div className="flex items-center justify-between pt-4 border-t border-slate-700">
                                        <div className="flex items-center space-x-2">
                                            <div className="flex -space-x-2">
                                                {[...Array(Math.min(3, match.joined))].map((_, i) => (
                                                    <div key={i} className="w-8 h-8 rounded-full bg-slate-600 border-2 border-slate-800 flex items-center justify-center text-xs font-bold text-slate-300"><User size={12} /></div>
                                                ))}
                                            </div>
                                            <span className="text-xs text-slate-400">{match.joined}/{match.maxPlayers}</span>
                                        </div>
                                        <button 
                                            onClick={() => handleJoinMatch(match.id)}
                                            disabled={match.joined >= match.maxPlayers}
                                            className={`px-6 py-2 rounded-xl font-bold text-sm transition-colors ${match.joined >= match.maxPlayers ? 'bg-slate-700 text-slate-500' : 'bg-white text-slate-900 hover:bg-slate-200'}`}
                                        >
                                            {match.joined >= match.maxPlayers ? 'Full' : 'Join'}
                                        </button>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>
                )}
            </div>
        )}
    </Layout>
  );
};

import React, { useState, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import { Layout } from '../components/Layout';
import { GoogleGenAI } from "@google/genai";
import { MY_TEAMS, TEAM_LEADERBOARD } from '../constants';
import { useBooking } from '../context/BookingContext';
import { useUser } from '../context/UserContext';
