import { Sparkles, Zap, MapPin, TrendingUp, TrendingDown, Swords, Loader2, User, Star, Wallet, CheckCircle, Users, Shuffle, ArrowRight, ArrowLeft, Clock, AlertTriangle, Calendar, Shield, Plus, Trophy, X, Search, Info, CreditCard, ChevronRight, Filter } from 'lucide-react';

// --- TYPES ---
interface SuggestedMatch {
  id: string;
  opponent: typeof TEAM_LEADERBOARD[0];
  matchScore: number;
  distance: string;
  winRate: number;
  lossRate: number;
  venue: Turf;
  timeSlot: string;
  splitPrice: number;
}

interface Player {
    id: string;
    name: string;
    role: string;
    rating: number;
    avatar: string;
}

interface CommunityMatch {
    id: string;
    title: string;
    description: string;
    organizer: string;
    organizerAvatar: string;
    venue: Turf;
    date: string;
    time: string;
    format: string;
    joined: number;
    maxPlayers: number;
    costPerPerson: number;
    rolesNeeded: string[];
    type: 'Friendly' | 'Competitive' | 'Pickup';
    isAiGenerated?: boolean;
}

