    { id: 'p1', name: 'David O.', role: 'Striker', rating: 4.9, avatar: 'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?w=100&h=100&fit=crop' },
    { id: 'p4', name: 'John D.', role: 'GK', rating: 4.8, avatar: 'https://images.unsplash.com/photo-1599566150163-29194dcaad36?w=100&h=100&fit=crop' },
    { id: 'p12', name: 'Simon P.', role: 'GK', rating: 4.5, avatar: 'https://images.unsplash.com/photo-1566492031773-4f4e44671857?w=100&h=100&fit=crop' },
    { id: 'p3', name: 'Musa B.', role: 'Defender', rating: 4.5, avatar: 'https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?w=100&h=100&fit=crop' },
    { id: 'p6', name: 'Chris P.', role: 'Defender', rating: 4.3, avatar: 'https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?w=100&h=100&fit=crop' },
    { id: 'p9', name: 'Mike L.', role: 'Defender', rating: 4.1, avatar: 'https://images.unsplash.com/photo-1522075469751-3a6694fb2f61?w=100&h=100&fit=crop' },
    { id: 'p11', name: 'Tom H.', role: 'Defender', rating: 4.4, avatar: 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=100&h=100&fit=crop' },
    { id: 'p2', name: 'Sarah K.', role: 'Midfielder', rating: 4.7, avatar: 'https://images.unsplash.com/photo-1438761681033-6461ffad8d80?w=100&h=100&fit=crop' },
    { id: 'p7', name: 'Sam M.', role: 'Midfielder', rating: 4.6, avatar: 'https://images.unsplash.com/photo-1527980965255-d3b416303d12?w=100&h=100&fit=crop' },
    { id: 'p5', name: 'Alex R.', role: 'Winger', rating: 4.2, avatar: 'https://images.unsplash.com/photo-1570295999919-56ceb5ecca61?w=100&h=100&fit=crop' },
    { id: 'p8', name: 'Lisa T.', role: 'Striker', rating: 4.4, avatar: 'https://images.unsplash.com/photo-1544005313-94ddf0286df2?w=100&h=100&fit=crop' },
    { id: 'p10', name: 'You', role: 'Midfielder', rating: 4.5, avatar: 'https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?w=100&h=100&fit=crop' },
];

export const MatchCenter: React.FC = () => {
  const navigate = useNavigate();
  const { turfs, bookings, addBooking } = useBooking(); 
  const { addXP, stats } = useUser();

  // Tabs
  const [activeTab, setActiveTab] = useState<'rivals' | 'open'>('rivals');

  // UI States
  const [isScanning, setIsScanning] = useState(false);
  const [statusMessage, setStatusMessage] = useState("");

  // Create Match Full Page State
  const [isCreating, setIsCreating] = useState(false);
  const [createStep, setCreateStep] = useState(0); 

  // Create Match Local State
  const [turfSearchQuery, setTurfSearchQuery] = useState("");
  const [newMatch, setNewMatch] = useState({
      type: 'Friendly',
      format: '5-a-side',
      duration: 1, // Hours
      venueId: '',
      date: new Date().toISOString().split('T')[0],
      time: '',
      paymentMode: 'Split',
      roles: [] as string[],
      notes: ''
  });

  const [fallbackTriggered, setFallbackTriggered] = useState(false);

  // Data States
  const [matches, setMatches] = useState<SuggestedMatch[]>([]);

  const [communityMatches, setCommunityMatches] = useState<CommunityMatch[]>([
      {
          id: 'cm1',
          title: 'Sunday Morning Sweat',
          description: 'Casual game to start the day. Beginners welcome!',
          organizer: 'Coach Mike',
          organizerAvatar: 'https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?w=100&h=100&fit=crop',
          venue: turfs[0],
          date: '2025-01-20',
          time: '08:00',
          format: '5-a-side',
          joined: 7,
          maxPlayers: 10,
          costPerPerson: 5000,
          rolesNeeded: ['GK', 'Defender'],
          type: 'Friendly'
      },
      {
          id: 'cm2',
          title: 'Competitive 7v7',
          description: 'High intensity match. Bring your A-game.',
          organizer: 'Sarah K.',
          organizerAvatar: 'https://images.unsplash.com/photo-1438761681033-6461ffad8d80?w=100&h=100&fit=crop',
          venue: turfs[2],
          date: '2025-01-20',
          time: '19:00',
          format: '7-a-side',
          joined: 12,
          maxPlayers: 14,
          costPerPerson: 8000,
          rolesNeeded: ['Striker'],
          type: 'Competitive'
      }
  ]);

  const myTeam = MY_TEAMS[0];

  // --- HELPERS ---

  // Filter Turfs for Search
  const filteredTurfs = useMemo(() => {
      if (!turfSearchQuery) return turfs;
      return turfs.filter(t => 
          t.name.toLowerCase().includes(turfSearchQuery.toLowerCase()) ||
          t.location.toLowerCase().includes(turfSearchQuery.toLowerCase())
      );
  }, [turfs, turfSearchQuery]);

  // Dynamic Time Slots based on Venue Hours + Duration Availability
  const getAvailableSlots = (turfId: string, date: string, duration: number) => {
      const turf = turfs.find(t => t.id === turfId);
      if (!turf) return [];

      const startHour = parseInt(turf.openingHour.split(':')[0]);
      const endHour = parseInt(turf.closingHour.split(':')[0]);
      const slots = [];

      // Check if date is blocked
      if (turf.blockedDates.includes(date)) return [];

      for (let i = startHour; i <= endHour - duration; i++) {
          const time = `${i.toString().padStart(2, '0')}:00`;

          // Check if ANY hour in the duration is booked
          let isBlocked = false;
          for (let d = 0; d < duration; d++) {
             const checkTime = `${(i + d).toString().padStart(2, '0')}:00`;
             const booked = bookings.some(b => 
                b.turfId === turfId && 
                b.date === date && 
                b.time === checkTime &&
                b.status !== 'CANCELLED'
             );
             if (booked) isBlocked = true;
          }

          if (!isBlocked) slots.push(time);
      }
      return slots;
  };

  const findNextAvailableSlot = (turf: Turf): string | null => {
      const today = new Date().toISOString().split('T')[0];
      const slots = getAvailableSlots(turf.id, today, 1);
      return slots.length > 0 ? slots[0] : null;
  };

  const calculateWinRate = (wins: number, totalGames: number = 24) => Math.round((wins / totalGames) * 100);

  // --- ACTIONS ---

  const handleJoinMatch = (matchId: string) => {
      setCommunityMatches(prev => prev.map(m => {
          if (m.id === matchId && m.joined < m.maxPlayers) {
              addXP(50); // Join Bonus
              return { ...m, joined: m.joined + 1 };
          }
          return m;
      }));
  };

  const handleCreateSubmit = async () => {
      setIsScanning(true); 

      const selectedTurf = turfs.find(t => t.id === newMatch.venueId) || turfs[0];
      const maxP = newMatch.format === '5-a-side' ? 10 : newMatch.format === '7-a-side' ? 14 : 22;
      const totalCost = selectedTurf.pricePerHour * newMatch.duration;
      const costPerPerson = newMatch.paymentMode === 'Split' ? Math.ceil(totalCost / maxP) : 0;

      // 1. Create System Booking
      const bookingId = Math.random().toString(36).substr(2, 9).toUpperCase();
      addBooking({
          id: bookingId,
          turfId: selectedTurf.id,
          turfName: selectedTurf.name,
          userName: 'You (Organizer)',
          date: newMatch.date,
          time: newMatch.time,
          duration: newMatch.duration,
          status: 'CONFIRMED',
          price: totalCost,
          createdAt: new Date().toISOString()
      });

      // 2. AI Gen Title (using provided notes if available)
      let aiTitle = `${newMatch.type} at ${selectedTurf.name}`;
      let aiDesc = newMatch.notes || "Join us for a great game!";

      if (!newMatch.notes) {
          try {
              const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
              const prompt = `Generate a 3-4 word exciting title and 1 sentence description for a ${newMatch.type} football match at ${selectedTurf.name}.`;
              const result = await ai.models.generateContent({ model: 'gemini-3-flash-preview', contents: prompt });
              const text = result.text || "";
              const lines = text.split('\n').filter(l => l);
              if (lines.length > 0) aiTitle = lines[0].replace(/"/g, '');
              if (lines.length > 1) aiDesc = lines[1];
          } catch (e) { console.error(e); }
      }

      const newCommunityMatch: CommunityMatch = {
          id: bookingId,
          title: aiTitle,
          description: aiDesc,
          organizer: 'You',
          organizerAvatar: 'https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?w=100&h=100&fit=crop',
          venue: selectedTurf,
          date: newMatch.date,
          time: newMatch.time,
          format: newMatch.format,
          joined: 1,
          maxPlayers: maxP,
          costPerPerson: costPerPerson,
          rolesNeeded: newMatch.roles,
          type: newMatch.type as any
      };

      setTimeout(() => {
          setCommunityMatches([newCommunityMatch, ...communityMatches]);
          setIsScanning(false);
          addXP(200);
          setIsCreating(false); 
          setActiveTab('open');
          // Reset Form
          setNewMatch({ ...newMatch, time: '', venueId: '', notes: '', roles: [] });
          setCreateStep(0);
      }, 2000);
  };

  const handleRivalScan = async () => {
      setIsScanning(true);
      setMatches([]);
      setStatusMessage("Analyzing League Data...");

      setTimeout(async () => {
        const myWinRate = calculateWinRate(myTeam.wins);
        const validMatches: SuggestedMatch[] = [];

        for (const opponent of TEAM_LEADERBOARD) {
            if (opponent.name === myTeam.name) continue;
            const randomTurfIndex = Math.floor(Math.random() * turfs.length);
            const potentialVenue = turfs[randomTurfIndex];
            const openSlot = findNextAvailableSlot(potentialVenue);

            if (openSlot) {
                const oppWinRate = calculateWinRate(opponent.wins);
                const skillDiff = Math.abs(myWinRate - oppWinRate);
                const matchScore = Math.max(0, 100 - (skillDiff * 3)); 

                if (matchScore > 60) {
                    validMatches.push({
                        id: opponent.id,
                        opponent,
                        matchScore,
                        distance: potentialVenue.distance,
                        winRate: oppWinRate,
                        lossRate: 100 - oppWinRate,
                        venue: potentialVenue,
                        timeSlot: openSlot,
                        splitPrice: Math.ceil(potentialVenue.pricePerHour / 2) 
                    });
                }
            }
        }
        validMatches.sort((a, b) => b.matchScore - a.matchScore);
        const topMatches = validMatches.slice(0, 2);

        if (topMatches.length === 0) setFallbackTriggered(true);
        else setMatches(topMatches);

        setIsScanning(false);
      }, 2000);
  };

  // --- SUB-RENDER: CREATE MATCH PAGE ---
  const renderCreateMatchPage = () => {
    const selectedTurf = turfs.find(t => t.id === newMatch.venueId);

    // Get Available Time Slots dynamically
    const availableSlots = selectedTurf 
        ? getAvailableSlots(selectedTurf.id, newMatch.date, newMatch.duration)
        : [];

    const totalCost = selectedTurf ? selectedTurf.pricePerHour * newMatch.duration : 0;
    const maxPlayers = newMatch.format === '5-a-side' ? 10 : newMatch.format === '7-a-side' ? 14 : 22;

    if (isScanning) {
        return (
            <div className="flex flex-col items-center justify-center min-h-[80vh] bg-slate-50 dark:bg-brand-dark p-5">
                <div className="relative">
                    <div className="w-24 h-24 rounded-full border-4 border-slate-200 dark:border-slate-700 animate-spin border-t-brand-secondary"></div>
                    <div className="absolute inset-0 flex items-center justify-center">
                        <Sparkles className="text-brand-secondary animate-pulse" size={32} />
                    </div>
                </div>
                <h2 className="mt-8 text-2xl font-bold text-slate-900 dark:text-white">Organizing Match...</h2>
                <p className="text-slate-500 dark:text-slate-400 mt-2 text-center max-w-xs">
                    Booking {selectedTurf?.name}, generating invites, and balancing teams.
                </p>
            </div>
        )
    }

    return (
        <div className="min-h-screen bg-slate-50 dark:bg-brand-dark animate-fadeIn">
            {/* Header */}
            <div className="sticky top-0 z-30 bg-white/80 dark:bg-brand-dark/80 backdrop-blur-md border-b border-slate-200 dark:border-slate-800 p-4 flex items-center justify-between">
                <button 
                    onClick={() => {
                        if(createStep > 0) setCreateStep(createStep - 1);
                        else setIsCreating(false);
                    }}
                    className="p-2 rounded-full hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors"
                >
                    <ArrowLeft className="text-slate-900 dark:text-white" />
                </button>
                <div className="flex flex-col items-center">
                    <h2 className="text-slate-900 dark:text-white font-bold">Create Match</h2>
                    <div className="flex space-x-1 mt-1">
                        {[0, 1, 2].map(s => (
                            <div key={s} className={`w-2 h-2 rounded-full transition-colors ${s === createStep ? 'bg-brand-secondary' : 'bg-slate-300 dark:bg-slate-700'}`} />
                        ))}
                    </div>
                </div>
                <div className="w-10" />
            </div>

            <div className="p-5 max-w-2xl mx-auto min-h-[calc(100vh-80px)] flex flex-col justify-between">
                <div>
                    {createStep === 0 && (
                        <div className="space-y-8 animate-slideUp">
                            {/* Match Type */}
                            <div>
                                <h3 className="text-xl font-bold text-slate-900 dark:text-white mb-4">What kind of match?</h3>
                                <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
                                    {['Friendly', 'Competitive', 'Pickup'].map(type => (
                                        <button 
                                            key={type}
                                            onClick={() => setNewMatch({...newMatch, type})}
                                            className={`p-6 rounded-2xl border-2 text-left transition-all relative overflow-hidden group ${
                                                newMatch.type === type 
                                                ? 'border-brand-secondary bg-brand-secondary/5' 
                                                : 'border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 hover:border-brand-secondary/50'
                                            }`}
                                        >
                                            <div className={`w-12 h-12 rounded-full flex items-center justify-center mb-4 ${newMatch.type === type ? 'bg-brand-secondary text-white' : 'bg-slate-100 dark:bg-slate-700 text-slate-500'}`}>
                                                {type === 'Friendly' && <Users size={24} />}
                                                {type === 'Competitive' && <Trophy size={24} />}
                                                {type === 'Pickup' && <Shuffle size={24} />}
                                            </div>
                                            <h4 className="font-bold text-slate-900 dark:text-white text-lg">{type}</h4>
                                            <p className="text-xs text-slate-500 mt-1">
                                                {type === 'Friendly' ? 'Casual play with friends' : type === 'Competitive' ? 'Ranked match for XP' : 'Open to everyone'}
                                            </p>
                                            {newMatch.type === type && <div className="absolute top-4 right-4 text-brand-secondary"><CheckCircle size={20} /></div>}
                                        </button>
                                    ))}
                                </div>
                            </div>

                            {/* Format */}
                            <div>
                                <h3 className="text-lg font-bold text-slate-900 dark:text-white mb-4">Format</h3>
                                <div className="flex gap-3 overflow-x-auto pb-2 scrollbar-hide">
                                    {['5-a-side', '7-a-side', '11-a-side'].map(fmt => (
                                        <button 
                                            key={fmt}
                                            onClick={() => setNewMatch({...newMatch, format: fmt})}
                                            className={`px-6 py-3 rounded-xl font-bold border transition-all whitespace-nowrap ${
                                                newMatch.format === fmt 
                                                ? 'bg-brand-secondary text-white border-brand-secondary shadow-lg' 
                                                : 'bg-white dark:bg-slate-800 text-slate-500 border-slate-200 dark:border-slate-700'
                                            }`}
                                        >
                                            {fmt}
                                        </button>
                                    ))}
                                </div>
                            </div>

                            {/* Roles */}
                            <div>
                                <h3 className="text-lg font-bold text-slate-900 dark:text-white mb-4">Positions Needed</h3>
                                <div className="flex flex-wrap gap-3">
                                    {['GK', 'Defender', 'Midfielder', 'Striker'].map(role => (
                                        <button
                                            key={role}
                                            onClick={() => {
                                                const roles = newMatch.roles.includes(role) 
                                                ? newMatch.roles.filter(r => r !== role)
                                                : [...newMatch.roles, role];
                                                setNewMatch({...newMatch, roles});
                                            }}
                                            className={`px-4 py-2 rounded-full text-sm font-bold border flex items-center transition-all ${
                                                newMatch.roles.includes(role) 
                                                ? 'bg-brand-secondary/10 border-brand-secondary text-brand-secondary' 
                                                : 'border-slate-200 dark:border-slate-700 text-slate-500'
                                            }`}
                                        >
                                            {newMatch.roles.includes(role) ? <Plus size={14} className="mr-1 rotate-45" /> : <Plus size={14} className="mr-1" />}
                                            {role}
                                        </button>
                                    ))}
                                </div>
                            </div>
                        </div>
                    )}

                    {createStep === 1 && (
                        <div className="space-y-8 animate-slideUp">
                            {/* Date & Duration */}
                            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                                <div>
                                    <label className="text-xs font-bold text-slate-500 uppercase mb-2 block">Date</label>
                                    <div className="relative">
                                        <Calendar className="absolute left-4 top-4 text-slate-400" size={20} />
                                        <input 
                                            type="date" 
                                            value={newMatch.date}
                                            onChange={(e) => setNewMatch({...newMatch, date: e.target.value, time: ''})}
                                            className="w-full bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-2xl p-4 pl-12 text-lg font-bold text-slate-900 dark:text-white focus:ring-2 focus:ring-brand-secondary outline-none"
                                        />
                                    </div>
                                </div>
                                <div>
                                    <label className="text-xs font-bold text-slate-500 uppercase mb-2 block">Duration</label>
                                    <div className="flex gap-2">
                                        {[1, 1.5, 2].map(d => (
                                            <button 
                                                key={d}
                                                onClick={() => setNewMatch({...newMatch, duration: d, time: ''})} // Reset time on duration change
                                                className={`flex-1 py-4 rounded-2xl font-bold border transition-all ${
                                                    newMatch.duration === d 
                                                    ? 'bg-brand-secondary border-brand-secondary text-white' 
                                                    : 'bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-700 text-slate-500'
                                                }`}
                                            >
                                                {d}h
                                            </button>
                                        ))}
                                    </div>
                                </div>
                            </div>

                            {/* Turf Selection with Search */}
                            <div>
                                <div className="flex justify-between items-center mb-4">
                                    <h3 className="text-lg font-bold text-slate-900 dark:text-white">Select Venue</h3>
                                    {/* Search Bar */}
                                    <div className="relative w-1/2">
                                        <input 
                                            type="text" 
                                            placeholder="Search turf..." 
                                            value={turfSearchQuery}
                                            onChange={(e) => setTurfSearchQuery(e.target.value)}
                                            className="w-full bg-slate-100 dark:bg-slate-800 border-none rounded-lg py-2 pl-8 pr-3 text-xs text-slate-900 dark:text-white focus:ring-1 focus:ring-brand-secondary outline-none"
                                        />
                                        <Search className="absolute left-2.5 top-2.5 text-slate-400" size={12} />
                                    </div>
                                </div>

                                <div className="space-y-4 max-h-[300px] overflow-y-auto pr-1">
                                    {filteredTurfs.map(turf => (
                                        <div 
                                            key={turf.id}
                                            onClick={() => setNewMatch({...newMatch, venueId: turf.id, time: ''})}
                                            className={`flex rounded-2xl border cursor-pointer overflow-hidden transition-all ${
                                                newMatch.venueId === turf.id 
                                                ? 'border-brand-secondary ring-2 ring-brand-secondary/30 bg-brand-secondary/5' 
                                                : 'border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800'
                                            }`}
                                        >
                                            <div className="w-24 h-24 sm:w-32 sm:h-auto bg-slate-200">
                                                <img src={turf.image} className="w-full h-full object-cover" />
                                            </div>
                                            <div className="p-4 flex-1 flex flex-col justify-center">
                                                <div className="flex justify-between items-start mb-1">
                                                    <h4 className="font-bold text-slate-900 dark:text-white">{turf.name}</h4>
                                                    {newMatch.venueId === turf.id && <CheckCircle size={20} className="text-brand-secondary" />}
                                                </div>
                                                <p className="text-xs text-slate-500 mb-2">{turf.location}</p>
                                                <div className="flex items-center space-x-3 text-xs">
                                                    <span className="font-bold text-brand-secondary">UGX {turf.pricePerHour.toLocaleString()}/hr</span>
                                                    <span className="flex items-center text-slate-400"><Star size={12} className="mr-1 fill-current text-yellow-400" /> {turf.rating}</span>
                                                </div>
                                            </div>
                                        </div>
                                    ))}
                                    {filteredTurfs.length === 0 && (
                                        <p className="text-center text-sm text-slate-400 py-4">No venues found matching "{turfSearchQuery}"</p>
                                    )}
                                </div>
                            </div>

                            {/* Time Slots */}
                            {newMatch.venueId && (
                                <div className="animate-fadeIn">
                                    <h3 className="text-lg font-bold text-slate-900 dark:text-white mb-4">Available Slots ({newMatch.duration}h)</h3>
                                    <div className="grid grid-cols-3 sm:grid-cols-4 gap-3">
                                        {availableSlots.length > 0 ? availableSlots.map(t => (
                                            <button
                                                key={t}
                                                onClick={() => setNewMatch({...newMatch, time: t})}
                                                className={`py-3 rounded-xl text-sm font-bold border transition-all ${
                                                    newMatch.time === t 
                                                    ? 'bg-brand-secondary border-brand-secondary text-white shadow-md' 
                                                    : 'bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-700 text-slate-600 dark:text-slate-300'
                                                }`}
                                            >
                                                {t}
                                            </button>
                                        )) : (
                                            <div className="col-span-full p-4 bg-red-500/10 border border-red-500/20 rounded-xl text-red-500 text-sm flex items-center justify-center">
