import { useBooking } from '../context/BookingContext';
import { useUser } from '../context/UserContext';

export const TurfDetail: React.FC = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const { turfs, bookings, addBooking } = useBooking();
  const { addXP } = useUser();

  const turf = turfs.find(t => t.id === id) || turfs[0];

  const [step, setStep] = useState<'details' | 'booking' | 'success'>('details');
  const [bookingId, setBookingId] = useState<string>('');

  // Calendar State
  const [currentMonth, setCurrentMonth] = useState(new Date());
  const [selectedDate, setSelectedDate] = useState<Date>(new Date());

  const [selectedTime, setSelectedTime] = useState<string | null>(null);
  const [duration, setDuration] = useState(1);
  const [splitPayment, setSplitPayment] = useState(false);

  // Derived State
  const totalPrice = turf.pricePerHour * duration;
  const splitPrice = Math.round(totalPrice / 5); // Mock 4 teammates + 1 user
  const dateStr = selectedDate.toISOString().split('T')[0];
  const isDateBlocked = turf.blockedDates.includes(dateStr);

  const getAmenityIcon = (amenity: string) => {
    const lower = amenity.toLowerCase();
    if (lower.includes('floodlight')) return <Zap size={18} className="text-yellow-400" />;
    if (lower.includes('bar')) return <Coffee size={18} className="text-amber-600" />;
    if (lower.includes('lounge')) return <Coffee size={18} className="text-orange-400" />;
    if (lower.includes('changing')) return <Shirt size={18} className="text-blue-400" />;
    if (lower.includes('shower')) return <Shirt size={18} className="text-cyan-400" />;
    if (lower.includes('parking')) return <Car size={18} className="text-slate-400" />;
    if (lower.includes('stand') || lower.includes('seat')) return <Users size={18} className="text-brand-secondary" />;
    if (lower.includes('aid')) return <HeartPulse size={18} className="text-red-500" />;
    if (lower.includes('shop')) return <ShoppingBag size={18} className="text-purple-400" />;
    if (lower.includes('turf')) return <Trophy size={18} className="text-emerald-400" />;
    return <CheckCircle size={18} className="text-slate-500" />;
  };

  // Generate Available Times based on Turf Operating Hours
  const generateTimeSlots = () => {
      const slots = [];
      const start = parseInt(turf.openingHour.split(':')[0]);
      const end = parseInt(turf.closingHour.split(':')[0]);

      for (let i = start; i < end; i++) {
          const time = `${i.toString().padStart(2, '0')}:00`;

          const isBooked = bookings.some(b => 
              b.turfId === turf.id && 
              b.date === dateStr && 
              b.time === time && 
              b.status !== 'CANCELLED'
          );

          slots.push({ time, isBooked });
      }
      return slots;
  };

  const timeSlots = generateTimeSlots();

  const handleBookingSubmit = () => {
      if (!selectedTime) return;

      const newId = Math.random().toString(36).substr(2, 9).toUpperCase();
      setBookingId(newId);

      addBooking({
          id: newId,
          turfId: turf.id,
          turfName: turf.name,
          userName: 'You', // In a real app, this comes from Auth
          date: dateStr,
          time: selectedTime,
          duration: duration,
          status: 'PENDING',
          price: totalPrice,
          createdAt: new Date().toISOString()
      });

      // Award XP for booking
      addXP(150);
      setStep('success');
  };

  // Calendar Helpers
  const daysInMonth = new Date(currentMonth.getFullYear(), currentMonth.getMonth() + 1, 0).getDate();
  const firstDayOfMonth = new Date(currentMonth.getFullYear(), currentMonth.getMonth(), 1).getDay();
  const prevMonth = () => setCurrentMonth(new Date(currentMonth.getFullYear(), currentMonth.getMonth() - 1, 1));
  const nextMonth = () => setCurrentMonth(new Date(currentMonth.getFullYear(), currentMonth.getMonth() + 1, 1));

  const isSelected = (day: number) => {
    return selectedDate.getDate() === day && 
           selectedDate.getMonth() === currentMonth.getMonth() && 
           selectedDate.getFullYear() === currentMonth.getFullYear();
  };

  if (step === 'success') {
      return (
          <div className="min-h-screen bg-slate-900 flex flex-col items-center justify-center p-6 text-center relative overflow-hidden">
              <div className="absolute inset-0 bg-brand-secondary/5" />

              <div className="bg-brand-secondary w-16 h-16 rounded-full flex items-center justify-center mb-4 shadow-[0_0_20px_rgba(16,185,129,0.5)] animate-bounce">
                  <CheckCircle size={32} className="text-white" />
              </div>

              <h1 className="text-2xl font-bold text-white mb-1">Booking Confirmed!</h1>
              <p className="text-slate-400 text-sm mb-6">Your slot has been reserved.</p>

              {/* Ticket / QR Card */}
              <div className="bg-white text-slate-900 w-full max-w-sm rounded-3xl overflow-hidden shadow-2xl relative mb-8">
                  {/* Top Part: Details */}
                  <div className="p-6 border-b border-dashed border-slate-300 relative">
                       {/* Punch holes for ticket effect */}
                       <div className="absolute bottom-0 left-0 transform -translate-x-1/2 translate-y-1/2 w-6 h-6 bg-slate-900 rounded-full"></div>
                       <div className="absolute bottom-0 right-0 transform translate-x-1/2 translate-y-1/2 w-6 h-6 bg-slate-900 rounded-full"></div>

                       <div className="text-center mb-4">
                           <h2 className="text-xl font-bold mb-1">{turf.name}</h2>
                           <p className="text-slate-500 text-xs flex items-center justify-center">
                               <MapPin size={10} className="mr-1" /> {turf.location}
                           </p>
                       </div>

                       <div className="grid grid-cols-2 gap-4 text-left">
                           <div>
