import React, { useState } from 'react';
import { useHistory, useLocation } from 'react-router-dom';
import { Calendar, Users, User, Home, Sparkles } from 'lucide-react';
import { AIChat } from './AIChat';

interface LayoutProps {
  children: React.ReactNode;
  isOwner?: boolean;
}

export const Layout: React.FC<LayoutProps> = ({ children, isOwner = false }) => {
  const history = useHistory();
  const location = useLocation();
  const [isChatOpen, setIsChatOpen] = useState(false);

  const isActive = (path: string) => location.pathname === path;

  // Standard Nav Item
  const NavItem = ({ path, icon: Icon, label }: { path: string, icon: any, label: string }) => (
    <button
      onClick={() => history.push(path)}
      className={`flex flex-col items-center justify-center w-full h-full py-2 transition-colors duration-300 group ${
        isActive(path) 
          ? 'text-brand-secondary' 
          : 'text-slate-400 hover:text-slate-600 dark:hover:text-slate-200'
      }`}
    >
      <Icon size={24} strokeWidth={isActive(path) ? 2.5 : 2} className={`mb-1 transition-transform group-active:scale-95 ${isActive(path) ? 'scale-110' : ''}`} />
      <span className="text-[10px] font-medium">{label}</span>
    </button>
  );

  return (
    <div className="flex flex-col h-screen bg-slate-50 dark:bg-brand-dark overflow-hidden transition-colors duration-300 font-sans relative">
      <main className="flex-1 overflow-y-auto pb-20 scrollbar-hide">
        {children}
      </main>

      {/* AI Assistant FAB (Only show if not on Match Center to avoid clutter, optional logic) */}
      {!isOwner && !isChatOpen && location.pathname !== '/live' && (
        <button
          onClick={() => setIsChatOpen(true)}
