export const Onboarding: React.FC = () => {
  const history = useHistory();
  const [step, setStep] = useState(0);

  const slides = [
    {
      title: "Discover Top Turfs",
      desc: "Find and book the best football turfs near you instantly.",
      icon: MapPin,
      color: "text-brand-secondary"
    },
    {
      title: "Book & Play",
      desc: "Seamless booking experience with split payments for your team.",
      icon: Calendar,
      color: "text-brand-primary"
    },
    {
      title: "Compete & Win",
      desc: "Join tournaments, track stats, and climb the leaderboards.",
      icon: Trophy,
      color: "text-yellow-500"
    }
  ];

  const handleNext = () => {
    if (step < slides.length - 1) {
      setStep(step + 1);
    } else {
      history.push('/auth');
    }
  };

  const CurrentIcon = slides[step].icon;

  return (
    <div className="h-screen w-full bg-slate-50 dark:bg-brand-dark flex flex-col justify-between p-8 relative overflow-hidden transition-colors duration-300">
      {/* Background Decorative Elements */}
      <div className="absolute top-[-20%] right-[-20%] w-[80vw] h-[80vw] bg-brand-primary/10 dark:bg-brand-primary/20 rounded-full blur-[100px]" />
      <div className="absolute bottom-[-10%] left-[-10%] w-[60vw] h-[60vw] bg-brand-secondary/10 dark:bg-brand-secondary/10 rounded-full blur-[80px]" />

      <div className="flex-1 flex flex-col justify-center items-center text-center z-10">
        <div className={`mb-8 p-6 rounded-3xl bg-white dark:bg-brand-surface border border-slate-200 dark:border-slate-700 shadow-xl ${slides[step].color} bg-opacity-50 backdrop-blur-md transition-colors`}>
          <CurrentIcon size={64} />
        </div>

        <h1 className="text-4xl font-bold text-slate-900 dark:text-white mb-4 leading-tight transition-colors">
          {slides[step].title}
        </h1>
        <p className="text-slate-500 dark:text-slate-400 text-lg max-w-xs mx-auto transition-colors">
          {slides[step].desc}
        </p>
      </div>

      <div className="z-10 w-full">
        <div className="flex justify-center space-x-2 mb-8">
          {slides.map((_, i) => (
            <div 
              key={i} 
              className={`h-2 rounded-full transition-all duration-300 ${i === step ? 'w-8 bg-brand-secondary' : 'w-2 bg-slate-300 dark:bg-slate-700'}`} 
            />
          ))}
        </div>

        <button 
          onClick={handleNext}
          className="w-full bg-brand-secondary hover:bg-emerald-400 text-white dark:text-brand-dark font-bold py-4 rounded-xl flex items-center justify-center transition-transform active:scale-95 shadow-lg"
        >
          {step === slides.length - 1 ? 'Get Started' : 'Next'}
          <ArrowRight className="ml-2" size={20} />
        </button>
      </div>
    </div>
  );
};

