                    </div>

                    <div className="px-2 pb-2">
                        <div className="flex justify-between items-start mb-2">
                            <div>
                                <h2 className="text-lg font-bold text-slate-900 dark:text-white mb-1">{featuredTurf.name}</h2>
                                <div className="flex items-center text-slate-500 dark:text-slate-400 text-xs font-medium">
                                    <MapPin size={14} className="mr-1 text-brand-secondary" />
                                    {featuredTurf.location}
                                </div>
                            </div>
                            <div className="flex flex-col items-end">
                                <div className="flex items-center text-slate-900 dark:text-white font-bold">
                                    <Star size={14} className="text-yellow-400 fill-current mr-1" />
                                    {featuredTurf.rating}
                                </div>
                                <span className="text-[10px] text-slate-400">(128 reviews)</span>
                            </div>
                        </div>

                        <div className="flex items-center justify-between mt-4 pt-4 border-t border-slate-100 dark:border-slate-700">
                            <div className="text-slate-500 dark:text-slate-400 text-xs font-medium">
                                <span className="text-brand-secondary bg-brand-secondary/10 px-2 py-0.5 rounded mr-2">{featuredTurf.distance}</span>
                                from center
                            </div>
                            <div className="text-slate-900 dark:text-white font-bold text-lg">
                                <span className="text-brand-secondary">UGX</span> {featuredTurf.pricePerHour.toLocaleString()}
                                <span className="text-xs text-slate-500 dark:text-slate-500 font-normal"> /hr</span>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        )}

        {/* Nearby / Search Results */}
        <div className="mb-4">
             <h2 className="text-xl font-bold text-slate-900 dark:text-white mb-4">
                 {searchTerm ? `Results for "${searchTerm}"` : `${filter} Courts`}
             </h2>

             {filteredTurfs.length === 0 ? (
                 <div className="text-center py-10 text-slate-400">
                     <p>No pitches found. Try changing filters.</p>
                 </div>
             ) : (
                 <div className={`${searchTerm ? 'grid grid-cols-1 gap-4' : 'flex overflow-x-auto space-x-4 pb-4 -mx-5 px-5 scrollbar-hide'}`}>
                     {filteredTurfs.map((turf) => (
                         <div 
                            key={turf.id} 
                            onClick={() => history.push(`/turf/${turf.id}`)}
                            className={`${searchTerm ? 'w-full' : 'min-w-[240px]'} bg-white dark:bg-slate-800 rounded-2xl p-3 border border-slate-200 dark:border-slate-700 shadow-sm cursor-pointer hover:shadow-md transition-shadow relative`}
                         >
                             <div className="h-32 rounded-xl overflow-hidden mb-3 relative">
                                 <img src={turf.image} className="w-full h-full object-cover" alt={turf.name} />
                                 <div className="absolute top-2 right-2 bg-black/50 backdrop-blur-sm px-2 py-1 rounded-lg text-white text-[10px] font-bold flex items-center">
                                     <MapPin size={10} className="mr-1" /> {turf.distance}
                                 </div>
                                 <button 
                                    onClick={(e) => toggleFavorite(e, turf.id)}
                                    className={`absolute top-2 left-2 p-1.5 rounded-full ${favorites.includes(turf.id) ? 'bg-red-500 text-white' : 'bg-black/50 text-white'}`}
                                 >
                                    <Heart size={12} className={favorites.includes(turf.id) ? 'fill-current' : ''} />
                                 </button>
                             </div>
                             <h3 className="font-bold text-slate-900 dark:text-white text-sm truncate">{turf.name}</h3>
                             <p className="text-slate-500 dark:text-slate-400 text-xs truncate mb-2">{turf.location}</p>
                             <div className="text-brand-secondary font-bold text-sm">
                                UGX {turf.pricePerHour.toLocaleString()} <span className="text-slate-400 text-xs font-normal">/hr</span>
                             </div>
                         </div>
                     ))}
                 </div>
             )}
        </div>

        {/* Filter Modal Overlay */}
        {showFilterModal && (
            <div className="fixed inset-0 z-50 flex items-end justify-center bg-black/50 backdrop-blur-sm animate-fadeIn">
                <div className="bg-white dark:bg-brand-surface w-full max-w-md rounded-t-3xl p-6 border-t border-slate-200 dark:border-slate-700 animate-slideUp">
                    <div className="flex justify-between items-center mb-6">
                        <h3 className="text-xl font-bold text-slate-900 dark:text-white">Filter & Sort</h3>
                        <button onClick={() => setShowFilterModal(false)} className="p-2 bg-slate-100 dark:bg-slate-800 rounded-full text-slate-500">
                            <X size={20} />
                        </button>
                    </div>

                    <div className="space-y-6">
                        <div>
                            <label className="text-xs font-bold text-slate-500 uppercase mb-3 block">Price Range</label>
                            <div className="flex items-center justify-between text-slate-900 dark:text-white font-bold mb-2">
                                <span>UGX 20k</span>
                                <span>UGX 150k+</span>
                            </div>
                            <input type="range" className="w-full h-2 bg-slate-200 dark:bg-slate-700 rounded-lg appearance-none cursor-pointer accent-brand-secondary" />
                        </div>

                        <div>
                            <label className="text-xs font-bold text-slate-500 uppercase mb-3 block">Amenities</label>
                            <div className="flex flex-wrap gap-2">
                                {['Floodlights', 'Parking', 'Showers', 'Bar'].map(am => (
                                    <button key={am} className="px-4 py-2 rounded-lg bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-300 text-sm font-medium hover:bg-brand-secondary hover:text-white transition-colors">
                                        {am}
                                    </button>
                                ))}
                            </div>
                        </div>

                         <div>
                            <label className="text-xs font-bold text-slate-500 uppercase mb-3 block">Sort By</label>
                            <div className="flex gap-2">
                                <button className="flex-1 py-3 border border-brand-secondary bg-brand-secondary/10 text-brand-secondary font-bold rounded-xl text-sm">Recommended</button>
                                <button className="flex-1 py-3 border border-slate-200 dark:border-slate-700 text-slate-500 font-bold rounded-xl text-sm">Lowest Price</button>
                            </div>
                        </div>

                        <button 
                            onClick={() => setShowFilterModal(false)}
                            className="w-full py-4 bg-brand-secondary text-white font-bold rounded-xl shadow-lg hover:bg-emerald-600 active:scale-95 transition-all"
                        >
                            Apply Filters
                        </button>
                    </div>
                </div>
            </div>
        )}
      </div>
    </Layout>
  );
};

import React, { useState, useEffect } from 'react';
import { useParams, useHistory } from 'react-router-dom';
import { ChevronLeft, ChevronRight, Share2, Heart, Star, CheckCircle, Home, Calendar, Clock, Lock, Users, Zap, Coffee, Shirt, Car, HeartPulse, ShoppingBag, Trophy, MapPin, QrCode } from 'lucide-react';
import { useBooking } from '../context/BookingContext';
import { useUser } from '../context/UserContext';

export const TurfDetail: React.FC = () => {
  const { id } = useParams<{id: string}>();
  const history = useHistory();
  const { turfs, bookings, addBooking } = useBooking();
  const { addXP } = useUser();

  const turf = turfs.find(t => t.id === id) || turfs[0];

  const [step, setStep] = useState<'details' | 'booking' | 'success'>('details');
  const [bookingId, setBookingId] = useState<string>('');

  // Calendar State
  const [currentMonth, setCurrentMonth] = useState(new Date());
  const [selectedDate, setSelectedDate] = useState<Date>(new Date());

  const [selectedTime, setSelectedTime] = useState<string | null>(null);
  const [duration, setDuration] = useState(1);
  const [splitPayment, setSplitPayment] = useState(false);

  // Derived State
  const totalPrice = turf.pricePerHour * duration;
  const splitPrice = Math.round(totalPrice / 5); // Mock 4 teammates + 1 user
  const dateStr = selectedDate.toISOString().split('T')[0];
  const isDateBlocked = turf.blockedDates.includes(dateStr);

  const getAmenityIcon = (amenity: string) => {
    const lower = amenity.toLowerCase();
    if (lower.includes('floodlight')) return <Zap size={18} className="text-yellow-400" />;
    if (lower.includes('bar')) return <Coffee size={18} className="text-amber-600" />;
    if (lower.includes('lounge')) return <Coffee size={18} className="text-orange-400" />;
    if (lower.includes('changing')) return <Shirt size={18} className="text-blue-400" />;
    if (lower.includes('shower')) return <Shirt size={18} className="text-cyan-400" />;
    if (lower.includes('parking')) return <Car size={18} className="text-slate-400" />;
    if (lower.includes('stand') || lower.includes('seat')) return <Users size={18} className="text-brand-secondary" />;
    if (lower.includes('aid')) return <HeartPulse size={18} className="text-red-500" />;
    if (lower.includes('shop')) return <ShoppingBag size={18} className="text-purple-400" />;
    if (lower.includes('turf')) return <Trophy size={18} className="text-emerald-400" />;
    return <CheckCircle size={18} className="text-slate-500" />;
  };

  // Generate Available Times based on Turf Operating Hours
  const generateTimeSlots = () => {
      const slots = [];
      const start = parseInt(turf.openingHour.split(':')[0]);
      const end = parseInt(turf.closingHour.split(':')[0]);

      for (let i = start; i < end; i++) {
          const time = `${i.toString().padStart(2, '0')}:00`;

          const isBooked = bookings.some(b => 
              b.turfId === turf.id && 
              b.date === dateStr && 
              b.time === time && 
              b.status !== 'CANCELLED'
          );

          slots.push({ time, isBooked });
      }
      return slots;
  };

  const timeSlots = generateTimeSlots();

  const handleBookingSubmit = () => {
      if (!selectedTime) return;

      const newId = Math.random().toString(36).substr(2, 9).toUpperCase();
      setBookingId(newId);

      addBooking({
          id: newId,
          turfId: turf.id,
          turfName: turf.name,
          userName: 'You', // In a real app, this comes from Auth
          date: dateStr,
          time: selectedTime,
          duration: duration,
          status: 'PENDING',
          price: totalPrice,
          createdAt: new Date().toISOString()
      });

      // Award XP for booking
      addXP(150);
      setStep('success');
  };

  // Calendar Helpers
  const daysInMonth = new Date(currentMonth.getFullYear(), currentMonth.getMonth() + 1, 0).getDate();
  const firstDayOfMonth = new Date(currentMonth.getFullYear(), currentMonth.getMonth(), 1).getDay();
  const prevMonth = () => setCurrentMonth(new Date(currentMonth.getFullYear(), currentMonth.getMonth() - 1, 1));
  const nextMonth = () => setCurrentMonth(new Date(currentMonth.getFullYear(), currentMonth.getMonth() + 1, 1));

  const isSelected = (day: number) => {
    return selectedDate.getDate() === day && 
           selectedDate.getMonth() === currentMonth.getMonth() && 
           selectedDate.getFullYear() === currentMonth.getFullYear();
  };

  if (step === 'success') {
      return (
          <div className="min-h-screen bg-slate-900 flex flex-col items-center justify-center p-6 text-center relative overflow-hidden">
              <div className="absolute inset-0 bg-brand-secondary/5" />

              <div className="bg-brand-secondary w-16 h-16 rounded-full flex items-center justify-center mb-4 shadow-[0_0_20px_rgba(16,185,129,0.5)] animate-bounce">
                  <CheckCircle size={32} className="text-white" />
              </div>

              <h1 className="text-2xl font-bold text-white mb-1">Booking Confirmed!</h1>
              <p className="text-slate-400 text-sm mb-6">Your slot has been reserved.</p>

              {/* Ticket / QR Card */}
              <div className="bg-white text-slate-900 w-full max-w-sm rounded-3xl overflow-hidden shadow-2xl relative mb-8">
                  {/* Top Part: Details */}
                  <div className="p-6 border-b border-dashed border-slate-300 relative">
                       {/* Punch holes for ticket effect */}
                       <div className="absolute bottom-0 left-0 transform -translate-x-1/2 translate-y-1/2 w-6 h-6 bg-slate-900 rounded-full"></div>
                       <div className="absolute bottom-0 right-0 transform translate-x-1/2 translate-y-1/2 w-6 h-6 bg-slate-900 rounded-full"></div>

                       <div className="text-center mb-4">
                           <h2 className="text-xl font-bold mb-1">{turf.name}</h2>
                           <p className="text-slate-500 text-xs flex items-center justify-center">
                               <MapPin size={10} className="mr-1" /> {turf.location}
                           </p>
                       </div>

                       <div className="grid grid-cols-2 gap-4 text-left">
                           <div>
                               <p className="text-[10px] text-slate-400 uppercase font-bold">Date</p>
                               <p className="font-bold text-sm">{dateStr}</p>
                           </div>
                           <div className="text-right">
                               <p className="text-[10px] text-slate-400 uppercase font-bold">Time</p>
                               <p className="font-bold text-sm">{selectedTime}</p>
                           </div>
                           <div>
                               <p className="text-[10px] text-slate-400 uppercase font-bold">Duration</p>
                               <p className="font-bold text-sm">{duration} hr{duration > 1 ? 's' : ''}</p>
                           </div>
                           <div className="text-right">
                               <p className="text-[10px] text-slate-400 uppercase font-bold">Total</p>
                               <p className="font-bold text-brand-secondary text-sm">UGX {totalPrice.toLocaleString()}</p>
                           </div>
                       </div>
                  </div>

                  {/* Bottom Part: QR */}
                  <div className="p-6 flex flex-col items-center justify-center bg-slate-50">
                      <div className="bg-white p-2 rounded-xl shadow-sm border border-slate-100 mb-2">
                           <QrCode size={120} className="text-slate-900" />
                      </div>
                      <p className="text-xs font-mono text-slate-500">ID: {bookingId}</p>
                      <p className="text-[10px] text-slate-400 mt-2">Scan at venue for entry</p>
                  </div>
              </div>

              <div className="w-full max-w-sm space-y-3">
                  <button onClick={() => history.push('/bookings')} className="bg-brand-secondary text-white w-full py-4 rounded-xl font-bold flex items-center justify-center shadow-lg hover:bg-emerald-600 transition-colors">
                      View My Bookings
                  </button>
                  <button onClick={() => history.push('/home')} className="text-slate-400 text-sm font-medium hover:text-white transition-colors">
                      Back to Home
                  </button>
              </div>
          </div>
      );
  }

  if (step === 'booking') {
      return (
          <div className="min-h-screen bg-slate-50 dark:bg-brand-dark flex flex-col">
              {/* Sticky Header */}
              <div className="sticky top-0 z-30 bg-white/80 dark:bg-brand-dark/80 backdrop-blur-md p-4 flex items-center justify-between border-b border-slate-200 dark:border-slate-800">
                  <button onClick={() => setStep('details')} className="p-2 bg-slate-100 dark:bg-slate-800 rounded-full text-slate-600 dark:text-white hover:bg-slate-200 dark:hover:bg-slate-700 transition-colors">
                      <ChevronLeft />
                  </button>
                  <div className="text-center">
                      <h2 className="text-slate-900 dark:text-white font-bold text-lg">Select Slot</h2>
                      <p className="text-slate-500 dark:text-slate-400 text-xs">{turf.name}</p>
                  </div>
                  <div className="w-10" />
              </div>

              <div className="flex-1 p-4 flex flex-col justify-between">
                  <div className="space-y-6">
                      {/* Calendar Strip */}
                      <div className="bg-white dark:bg-slate-800 rounded-2xl p-4 border border-slate-200 dark:border-slate-700">
                          <div className="flex justify-between items-center mb-4 text-slate-900 dark:text-white">
                              <button onClick={prevMonth} className="p-2 hover:bg-slate-100 dark:hover:bg-slate-700 rounded-full transition-colors hover:text-brand-secondary"><ChevronLeft size={20} /></button>
                              <h3 className="font-bold text-lg">{currentMonth.toLocaleDateString('en-US', { month: 'long', year: 'numeric' })}</h3>
                              <button onClick={nextMonth} className="p-2 hover:bg-slate-100 dark:hover:bg-slate-700 rounded-full transition-colors hover:text-brand-secondary"><ChevronRight size={20} /></button>
                          </div>
                          <div className="grid grid-cols-7 gap-1 text-center text-xs text-slate-400 dark:text-slate-500 mb-2 font-medium">
                              <div>Su</div><div>Mo</div><div>Tu</div><div>We</div><div>Th</div><div>Fr</div><div>Sa</div>
                          </div>
                          <div className="grid grid-cols-7 gap-y-2 gap-x-1 text-center">
                              {Array.from({ length: firstDayOfMonth }).map((_, i) => <div key={`empty-${i}`} />)}
                              {Array.from({ length: daysInMonth }).map((_, i) => {
                                  const day = i + 1;
                                  const selected = isSelected(day);
                                  return (
                                      <button 
                                          key={day}
                                          onClick={() => setSelectedDate(new Date(currentMonth.getFullYear(), currentMonth.getMonth(), day))}
                                          className={`w-8 h-8 rounded-full flex items-center justify-center mx-auto text-sm transition-all relative
                                              ${selected 
                                                  ? 'bg-brand-secondary text-white font-bold shadow-lg ring-2 ring-offset-2 ring-offset-white dark:ring-offset-slate-800 ring-brand-secondary scale-110 z-10' 
                                                  : 'text-slate-600 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-700'
                                              }
                                          `}
                                      >
                                          {day}
                                      </button>
                                  );
                              })}
                          </div>
                      </div>

                      {/* Available Slots */}
                      <div>
                          <h3 className="text-slate-900 dark:text-white font-bold flex items-center mb-3">
                              <span className="mr-2 text-brand-secondary"><Calendar size={18} /></span>
                              {isDateBlocked ? 'Venue Closed' : 'Available Slots'}
                          </h3>

                          {isDateBlocked ? (
                              <div className="bg-red-500/10 border border-red-500/30 rounded-xl p-4 flex flex-col items-center justify-center text-center">
                                  <Lock className="text-red-500 mb-2" size={24} />
                                  <p className="text-red-400 font-bold">This turf is closed on this date.</p>
                                  <p className="text-red-400/70 text-sm">Please select another day.</p>
                              </div>
                          ) : (
                              <div className="grid grid-cols-3 gap-3">
                                  {timeSlots.map(({ time, isBooked }) => (
                                      <button 
                                        key={time}
                                        disabled={isBooked}
                                        onClick={() => setSelectedTime(time)}
                                        className={`py-3 rounded-xl text-sm font-bold border transition-all ${
                                            isBooked 
                                                ? 'bg-slate-100 dark:bg-slate-800 text-slate-400 dark:text-slate-600 border-slate-200 dark:border-slate-800 cursor-not-allowed decoration-slate-400' 
                                                : selectedTime === time 
                                                    ? 'bg-brand-secondary border-brand-secondary text-white shadow-md' 
                                                    : 'bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-700 text-slate-600 dark:text-slate-300 hover:border-brand-secondary/50' 
                                        }`}
                                      >
                                          {time}
                                          {isBooked && <span className="block text-[8px] uppercase mt-1">Booked</span>}
                                      </button>
                                  ))}
                              </div>
                          )}
                      </div>

                      {/* Duration Picker */}
                      {!isDateBlocked && (
                          <div>
                              <h3 className="text-slate-900 dark:text-white font-bold flex items-center mb-3">
                                  <span className="mr-2 text-brand-secondary"><Clock size={18} /></span>
                                  Duration
                              </h3>
                              <div className="flex bg-white dark:bg-slate-800 p-1 rounded-xl border border-slate-200 dark:border-slate-700">
                                  {[1, 2, 3].map(h => (
                                      <button 
                                        key={h}
                                        onClick={() => setDuration(h)}
                                        className={`flex-1 py-3 rounded-lg text-sm font-bold transition-all ${
                                            duration === h 
                                            ? 'bg-brand-secondary text-white shadow-md' 
                                            : 'text-slate-500 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white'
                                        }`}
                                      >
                                          {h} hr{h > 1 ? 's' : ''}
                                      </button>
                                  ))}
                              </div>
                          </div>
                      )}

                      {/* Split Payment Toggle */}
                      {!isDateBlocked && (
                        <div>
                            <div 
                                onClick={() => setSplitPayment(!splitPayment)}
                                className={`p-4 rounded-xl flex items-center justify-between border cursor-pointer active:scale-[0.98] transition-all ${
                                    splitPayment 
                                    ? 'bg-white dark:bg-slate-800 border-brand-secondary ring-1 ring-brand-secondary/50' 
                                    : 'bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-700'
                                }`}
                            >
                                <div className="flex items-center">
                                    <div className="p-2 bg-brand-secondary/10 dark:bg-brand-secondary/20 rounded-lg mr-3 text-brand-secondary">
                                        <Share2 size={20} />
                                    </div>
                                    <div>
                                        <span className="text-slate-900 dark:text-white font-bold block">Split Payment</span>
                                        <span className="text-slate-500 text-xs">Share cost with 4 others</span>
                                    </div>
                                </div>
                                <div 
                                    className={`w-12 h-7 rounded-full p-1 transition-colors ${splitPayment ? 'bg-brand-secondary' : 'bg-slate-300 dark:bg-slate-600'}`}
                                >
                                    <div className={`w-5 h-5 bg-white rounded-full shadow-md transform transition-transform ${splitPayment ? 'translate-x-5' : 'translate-x-0'}`} />
                                </div>
                            </div>

                            {splitPayment && (
                                <div className="mt-3 bg-slate-50 dark:bg-slate-800/50 rounded-xl p-4 border border-slate-200 dark:border-slate-700 animate-fadeIn">
                                    <div className="flex justify-between items-center mb-4">
                                        <span className="text-slate-400 text-xs font-bold uppercase tracking-wider">Breakdown (5 Players)</span>
                                    </div>

                                    <div className="flex items-center justify-between mb-4">
                                        {/* Current User */}
                                        <div className="flex flex-col items-center space-y-2">
                                            <div className="w-12 h-12 rounded-full bg-brand-secondary text-white flex items-center justify-center font-bold text-xs border-2 border-white dark:border-slate-700 shadow-lg relative">
                                                You
                                                <div className="absolute -bottom-1 -right-1 w-4 h-4 bg-green-500 rounded-full border-2 border-white dark:border-slate-800"></div>
                                            </div>
                                            <span className="text-slate-900 dark:text-white font-bold text-xs">UGX {splitPrice.toLocaleString()}</span>
                                        </div>

                                        {/* Divider */}
                                        <div className="h-px w-8 bg-slate-300 dark:bg-slate-700"></div>

                                        {/* Teammates Mock */}
                                        <div className="flex -space-x-3">
                                            {[1,2,3,4].map(i => (
                                                <div key={i} className="w-12 h-12 rounded-full bg-slate-200 dark:bg-slate-700 text-slate-500 dark:text-slate-400 flex items-center justify-center border-2 border-white dark:border-slate-800 font-bold text-xs relative z-0" style={{zIndex: 4-i}}>
                                                    <Users size={16} />
                                                </div>
                                            ))}
                                        </div>

                                        <div className="flex flex-col items-end">
                                            <span className="text-slate-500 dark:text-slate-400 text-xs">4 others</span>
                                            <span className="text-slate-900 dark:text-white font-bold text-xs">UGX {splitPrice.toLocaleString()} ea</span>
                                        </div>
                                    </div>

                                    <div className="pt-3 border-t border-slate-200 dark:border-slate-700 flex justify-between items-center">
                                         <span className="text-slate-500 dark:text-slate-400 text-xs">Total Amount</span>
                                         <span className="text-slate-900 dark:text-white font-bold text-sm">UGX {totalPrice.toLocaleString()}</span>
                                    </div>
                                </div>
                            )}
                        </div>
                      )}
                  </div>

                  {/* Static Bottom Sheet / Footer */}
                  <div className="mt-8 pt-6 border-t border-slate-200 dark:border-slate-700">
                       <div className="flex justify-between items-end mb-4">
                           <div>
                               <p className="text-slate-500 dark:text-slate-400 text-xs mb-1">
                                   {splitPayment ? 'Per Player (1/5)' : 'Total Price'}
                               </p>
                               <h2 className="text-3xl font-bold text-slate-900 dark:text-white flex items-baseline">
                                   <span className="text-sm font-bold text-brand-secondary mr-1">UGX</span>
                                   {splitPayment ? splitPrice.toLocaleString() : totalPrice.toLocaleString()}
                               </h2>
                           </div>
                           {splitPayment && (
                               <div className="text-right">
                                   <p className="text-xs text-slate-500 dark:text-slate-400 mb-1">Total Team Price</p>
                                   <p className="text-xl font-bold text-slate-900 dark:text-white">
                                       <span className="text-xs font-bold text-slate-500 mr-1">UGX</span>
                                       {totalPrice.toLocaleString()}
                                   </p>
                               </div>
                           )}
                       </div>
                       <button 
                         disabled={!selectedTime || isDateBlocked}
                         onClick={handleBookingSubmit}
                         className={`w-full py-4 rounded-xl font-bold text-lg flex items-center justify-center space-x-2 shadow-lg transition-transform active:scale-[0.98] ${
                             selectedTime && !isDateBlocked ? 'bg-brand-secondary hover:bg-emerald-600 text-white' : 'bg-slate-200 dark:bg-slate-700 text-slate-400 dark:text-slate-500 cursor-not-allowed'
                         }`}
                       >
                           <span>{isDateBlocked ? 'Unavailable' : 'Confirm Booking'}</span>
                       </button>
                  </div>
              </div>
          </div>
      );
  }

  // Initial Details View
  return (
    <div className="bg-slate-50 dark:bg-slate-900 min-h-screen relative font-sans transition-colors duration-300 flex flex-col">
      <div className="relative h-96 w-full flex-shrink-0">
        <img src={turf.image} className="w-full h-full object-cover" />
        <div className="absolute inset-0 bg-gradient-to-b from-transparent via-slate-900/60 to-slate-900" />
        <div className="absolute top-4 left-4 z-10 flex w-full justify-between pr-8">
          <button onClick={() => history.goBack()} className="bg-black/30 backdrop-blur-md p-2 rounded-full text-white hover:bg-black/40 transition-colors">
            <ChevronLeft size={24} />
          </button>
          <div className="flex space-x-3">
              <button className="bg-black/30 backdrop-blur-md p-2 rounded-full text-white hover:bg-black/40 transition-colors"><Share2 size={20} /></button>
              <button className="bg-black/30 backdrop-blur-md p-2 rounded-full text-white hover:bg-black/40 transition-colors"><Heart size={20} /></button>
          </div>
        </div>
      </div>

      <div className="px-6 -mt-8 relative z-10 flex-1 flex flex-col justify-between">
        <div>
            <div className="flex justify-between items-start mb-2">
            <h1 className="text-3xl font-bold text-white leading-tight drop-shadow-md">{turf.name}</h1>
            <div className="bg-brand-secondary/90 text-white px-2 py-1 rounded-lg flex items-center backdrop-blur-sm shadow-lg">
                <Star size={14} className="fill-current mr-1" />
                <span className="font-bold">{turf.rating}</span>
            </div>
            </div>
            <p className="text-slate-300 text-sm mb-6 flex items-center">
                <MapPin size={14} className="mr-1" /> {turf.location} • 2.5km away
            </p>

            <div className="bg-white dark:bg-slate-800 p-5 rounded-2xl border border-slate-200 dark:border-slate-700 mb-6 shadow-sm">
                <h3 className="text-slate-900 dark:text-white font-bold mb-2">Description</h3>
                <p className="text-slate-500 dark:text-slate-400 text-sm leading-relaxed">Top-tier football turf with FIFA standard grass. Features floodlights for night games and a dedicated changing room.</p>

                <div className="mt-6">
                    <h3 className="text-slate-900 dark:text-white font-bold mb-3">Amenities</h3>
                    <div className="grid grid-cols-2 gap-3">
                        {turf.amenities.map(a => (
                            <div key={a} className="bg-slate-50 dark:bg-slate-700/50 border border-slate-100 dark:border-slate-700 p-2 rounded-xl flex items-center">
                                <div className="bg-white dark:bg-slate-800 p-2 rounded-lg mr-3 shadow-sm text-brand-secondary">
                                    {getAmenityIcon(a)}
                                </div>
                                <span className="text-slate-700 dark:text-slate-300 text-xs font-medium">{a}</span>
                            </div>
                        ))}
                    </div>
                </div>
            </div>
        </div>

        {/* Static Footer */}
        <div className="mt-4 mb-8 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 p-5 rounded-2xl shadow-lg">
           <div className="flex justify-between items-center">
               <div>
                   <p className="text-slate-500 dark:text-slate-400 text-xs mb-1">Starting from</p>
                   <h2 className="text-2xl font-bold text-slate-900 dark:text-white">
                       <span className="text-xs font-bold text-brand-secondary mr-1">UGX</span>
                       {turf.pricePerHour.toLocaleString()}
                       <span className="text-xs font-normal text-slate-500 ml-1">/hr</span>
                   </h2>
               </div>
               <button onClick={() => setStep('booking')} className="bg-brand-secondary text-white px-8 py-4 rounded-xl font-bold text-lg shadow-lg hover:bg-emerald-600 transition-colors active:scale-95">
                   Book Now
               </button>
           </div>
        </div>
      </div>
    </div>
  );
};
